window.RP_CHARACTER_SHEETS={"version":1,"scale":5,"axes":[{"id":"social","name":"사교성","description":"새로운 사람에게 다가가고 대화를 시작하는 경향"},{"id":"emotion","name":"감정성","description":"감정이 표현과 선택에 드러나는 정도"},{"id":"altruism","name":"이타성","description":"타인을 위해 자신의 이익이나 부담을 감수하는 경향"},{"id":"initiative","name":"주도성","description":"먼저 제안하고 행동하며 상황을 이끄는 경향"},{"id":"caution","name":"신중성","description":"행동하기 전에 위험과 결과를 살피는 경향"},{"id":"bonds","name":"관계성","description":"이미 맺은 유대와 약속을 중요하게 여기고 유지하는 경향"}],"entries":{"P-c9505ea97ebc":{"name":"마리아 아나이스 에스더","tagline":"달라진 모습으로 돌아와, 함께 살아갈 평범한 내일을 다시 그리는 사람.","tags":["관계에 진심인","일상을 찾아가는","감정 표현이 풍부한"],"profileNote":"사제로 지내던 시기부터 언데드로 돌아온 뒤의 생활까지 함께 정리했다. 죽음 이후의 귀환과 훗날 샤덴프로이데 교회에서 돌아온 사건은 서로 다른 시점의 일이다.","facts":[{"label":"역할과 신앙","value":"스스로 사제라고 소개하며 신성력을 사용한다. 이른 시기의 대화에서는 자신에게 말하는 존재가 라운데라를 자칭하지만 그 정체를 알 길이 없다고 답한다. 신앙의 대상에 관한 의문도 서사의 일부다.","source":"S-fb849ce46990"},{"label":"죽음 이후","value":"장례를 치른 뒤 언데드의 모습으로 길드에 돌아온다. 귀환한 자리에서도 자신을 마리아 아나이스이자 사제로 소개하며 동료들과 다시 어울린다.","source":"S-70d9b92f2bd2"},{"label":"기념하는 생일","value":"정확한 생일을 모르기 때문에 자신이 원하는 12월 25일을 생일로 삼았다고 말한다. 하일로와 생일 선물을 약속하는 장면에서 확인된다.","source":"S-fb71ebdf395f"},{"label":"반려 관계","value":"하일로 조바의 사과와 청혼을 받아들이고 교회에서 길드로 돌아간다. 이후 함께 살 집과 생활비, 앞으로의 일에 관해 의논한다.","source":"S-e945f3ae3270"},{"label":"현재의 생활","value":"변화한 몸에 적응하면서 설거지와 요리 같은 집안일에 보람을 느낀다. 모나에게 손을 관리하는 법과 달라진 자신을 바라보는 이야기를 듣는다.","source":"S-44fd8459dc7f"},{"label":"앞으로의 바람","value":"하일로와 길드 밖에서 살아보자고 제안한다. 곧바로 떠나기보다는 돈을 모을 기간과 생계를 생각하며, 위험한 모험을 줄이고 평범하게 사는 가능성을 의논한다.","source":"S-3728faa118dd"}],"evaluation":[{"title":"약속 하나가 특별해지는 사람","text":"정확한 생일을 모른다는 이야기는 곧 생일 선물을 기대하는 대화로 바뀐다. 마리아는 하일로의 약속을 거듭 확인하고 기뻐한다. 소소한 기념일에도 누군가 자신을 기억하고 찾아와 주기를 바라는 마음이 담겨 있어, 일상적인 장면이 관계의 중요한 순간이 된다.","source":"S-fb71ebdf395f"},{"title":"소중한 사람을 모두 붙잡고 싶은 마음","text":"데미안을 둘러싼 갈등에서는 에레모시스와의 관계까지 흔들린다. 마리아는 사과하며 두 사람 모두 필요하다고 말하고, 데미안만 데려오는 대신 에레모시스도 함께 돌아오라고 요구한다. 관계를 지키려는 절박함이 크지만, 그 감정을 정리해 전달하는 데에는 어려움도 있는 인물이다.","source":"S-4f109cb1ad08"},{"title":"다시 함께하기로 고르는 순간","text":"샤덴프로이데 교회에서의 재회는 하일로의 사과와 청혼, 마리아의 응답으로 이어진다. 동료들의 놀림에 발끈하면서도 함께 귀환하는 모습에는 서운함과 애정이 나란히 남아 있다. 관계의 상처를 한 번에 지웠다고 보기보다, 다시 함께할 다음 장면을 선택했다고 읽는 편이 어울린다.","source":"S-e945f3ae3270"},{"title":"달라진 몸으로 발견하는 일상의 보람","text":"설거지를 마치는 뿌듯함과 동료의 격려가 현재의 자신을 받아들이는 계기가 된다. 모나는 외모와 매력의 기준이 하나가 아니라는 경험을 나누고, 마리아는 그 말을 듣고 자신의 변화를 새롭게 생각한다. 모험의 성과뿐 아니라 작은 생활의 성취로도 자신을 세워가는 과정이 보인다.","source":"S-44fd8459dc7f"},{"title":"함께할 미래를 생활의 언어로 말하다","text":"길드 밖에서 함께 살자는 말을 먼저 꺼내면서도 당장 떠나자는 반응에는 준비가 필요하다고 답한다. 저축, 일, 요리의 역할 분담처럼 구체적인 이야기가 이어진다. 사랑받고 싶은 마음이 함께 살아갈 조건을 고르는 주도성으로 확장되는 장면이다.","source":"S-3728faa118dd"}],"traits":{"social":{"score":4,"text":"식사와 집안일을 접점으로 동료들과 대화를 이어가고, 생일이나 근황처럼 개인적인 이야기도 나눈다. 낯가림이나 당황하는 반응이 있어도 관계를 시작하고 이어가려는 태도가 반복된다.","source":"S-44fd8459dc7f","supportingSources":["S-fb71ebdf395f","S-70d9b92f2bd2"]},"emotion":{"score":5,"text":"선물 약속의 기쁨, 관계가 흔들릴 때의 불안, 재회 뒤의 부끄러움과 애정이 말과 행동에 강하게 드러난다. 감정은 단순한 반응을 넘어 사과와 귀환, 미래를 선택하는 중요한 동기가 된다.","source":"S-4f109cb1ad08","supportingSources":["S-fb71ebdf395f","S-e945f3ae3270"]},"altruism":{"score":4,"text":"남은 설거지를 맡고 상대에게 음식을 해주며 함께 사는 일을 돕는다. 에레모시스에게는 데미안만이 아니라 자신도 살아 돌아오라고 요청한다. 타인을 돌보는 마음은 생활의 행동과 가까운 이들의 안위를 챙기는 방식으로 나타난다.","source":"S-44fd8459dc7f","supportingSources":["S-3728faa118dd","S-4f109cb1ad08"]},"initiative":{"score":4,"text":"갈등 뒤 사과하러 찾아가고, 현재의 생활에서는 요리를 시도하거나 독립 생활을 먼저 제안한다. 늘 능숙하게 상황을 이끄는 것은 아니지만 원하는 관계와 미래를 위해 먼저 말을 꺼내고 행동한다.","source":"S-3728faa118dd","supportingSources":["S-4f109cb1ad08","S-44fd8459dc7f"]},"caution":{"score":3,"text":"처음 휴가 계획에서는 경로와 동행을 스텔라의 도움으로 구체화한다. 이후 독립 생활에서는 준비 기간과 저축, 위험한 일을 계속할지를 직접 따진다. 즉흥적인 바람을 생활 계획으로 다듬어가는 면이 함께 보인다.","source":"S-3728faa118dd","supportingSources":["S-745e3605ea69"]},"bonds":{"score":5,"text":"가까운 이들과의 약속을 반복해서 확인하고, 갈등 뒤에도 함께 돌아올 길을 찾는다. 하일로와 따로 살더라도 길드에는 다시 찾아오면 된다고 생각한다. 삶의 형태가 바뀌어도 관계를 이어가려는 마음이 일관된다.","source":"S-3728faa118dd","supportingSources":["S-fb71ebdf395f","S-4f109cb1ad08","S-e945f3ae3270"]}},"relations":[{"name":"하일로 조바","text":"생일의 작은 약속에서 사과와 청혼, 함께 살 미래의 논의까지 관계가 이어진 반려자. 서로의 바람을 생활 속에서 맞춰가는 모습이 보인다.","source":"S-e945f3ae3270","characterId":"P-f6ccefd2c259"},{"name":"모나 델핀","text":"달라진 몸과 일상의 보람을 편하게 이야기하는 동료. 외모를 바라보는 다양한 시선과 돌아와 줘서 고맙다는 말을 건넨다.","source":"S-44fd8459dc7f","characterId":"P-48cca58d02b2"},{"name":"에레모시스","text":"가족으로 여기지만 데미안을 둘러싼 일로 깊이 부딪친 상대. 사과와 함께 돌아오겠다는 약속을 통해 다시 관계를 붙잡으려 한다.","source":"S-4f109cb1ad08","characterId":"P-d6e0d1eb8b63"},{"name":"스텔라 스타라이트","text":"휴가의 목적지와 이동 방법을 구체화해 주고 정기적으로 편지를 보내라고 당부한 동료. 마리아가 길드 밖으로 나갈 때에도 이어지는 돌봄의 관계다.","source":"S-745e3605ea69","characterId":"P-e6655a038328"}],"scenes":[{"source":"S-fb71ebdf395f","text":"스스로 정한 생일과 처음 받아보는 선물 약속, 밤의 연주."},{"source":"S-4f109cb1ad08","text":"에레모시스에게 사과하며 두 사람 모두 돌아오라고 부탁하는 대화."},{"source":"S-7049bda75420","text":"동료들이 마지막 인사를 건네는 장례. 이후의 귀환을 읽기 위한 앞선 사건."},{"source":"S-e945f3ae3270","text":"훗날 교회에서 이루어진 재회와 청혼, 다시 함께하는 귀환."},{"source":"S-44fd8459dc7f","text":"설거지를 하며 달라진 자신을 이야기하고 동료의 환영을 받는 시간."},{"source":"S-3728faa118dd","text":"서툰 점심 요리에서 저축과 두 사람의 미래로 이어지는 대화."}],"updatedAt":"2026-09-29","asOf":"2026-09-27","sources":["S-fb849ce46990","S-70d9b92f2bd2","S-fb71ebdf395f","S-e945f3ae3270","S-44fd8459dc7f","S-3728faa118dd","S-4f109cb1ad08","S-745e3605ea69","S-7049bda75420"]},"P-96ab98d2591c":{"name":"라이아흐 아카쿠","tagline":"웃으며 사람들 사이에 섞이고, 소중한 이들과 살아갈 길을 스스로 고르는 사람.","tags":["친화적","가족 중심적","능동적"],"profileNote":"사제 직위는 내려놓았다고 스스로 설명하지만, 카카투 신앙과 신성력은 유지한다. 출신·직업·능력은 아래의 관련 기록을 기준으로 정리했다.","facts":[{"label":"종족","value":"드라고니안. 인간 중심의 골기아에서 종족에 대한 편견과 차별을 경험한다.","source":"S-4fad1d04608a"},{"label":"출신과 배경","value":"스카일라 왕국 라이아흐 가문의 후계자로 종교 교육을 받았다. 클램시와의 만남 뒤 가문 밖에서 살기로 미샤와 뜻을 모으고, 석 달 뒤 골기아로 망명한다.","source":"S-f80c598e4db0"},{"label":"신앙","value":"라 엘라와 바슈르에게 기도하는 카카투 신앙의 사제 출신. 현재는 사제 직위를 내려놓은 일반인으로 자신을 설명한다.","source":"S-f7301c18bfae"},{"label":"직업과 생활","value":"길드의 모험가로 활동하며 살롱을 통해 마사지 일을 한다. 미샤와 따로 집에서 살고, 아침 기도와 식사를 마친 뒤 일하러 나가는 일상이 있다.","source":"S-f7301c18bfae"},{"label":"능력","value":"카카투의 은혜로 신성력을 사용한다. 동료의 몸 상태를 살피고 치유를 돕지만, 오래된 손상처럼 자신의 능력으로 해결하기 어려운 경우도 구분한다.","source":"S-a93aee63b76c"},{"label":"가족","value":"인간인 미샤의 반려자. 서로를 숨기지 않고 당당히 사랑하며 여행하고 싶다는 바람이 가문을 떠나는 결정으로 이어진다.","source":"S-f80c598e4db0"}],"evaluation":[{"title":"자기 삶을 선택하는 용기","text":"가문의 보장된 생활을 사슬에 묶인 코끼리에 빗대며, 미샤와 자유롭게 사랑하고 여행하는 삶을 원한다고 말한다. 생활의 어려움에 관한 미샤의 질문을 듣고도 함께 떠날 이유를 구체화한다. 타인의 말에서 용기를 얻은 뒤 자신의 선택으로 옮기는 힘이 있는 인물이다.","source":"S-f80c598e4db0"},{"title":"웃으며 가까워지는 사람","text":"맡겨진 종족 문화 교류회를 귀찮아하면서도 사람들을 부르고 소개 순서를 정하며 대화를 이끈다. 격식을 가볍게 풀어내는 농담과 거리낌 없는 말투가 모임의 분위기를 만든다. 처음부터 모두를 이해하는 인물은 아니며, 서로의 차이를 생활 속에서 부딪치고 배워간다.","source":"S-7c736b1d84bd"},{"title":"존엄을 지키는 현실적인 대응","text":"차별적인 상인 앞에서는 물러나지 않고 제대로 된 사과를 요구한다. 길드 소속과 망명 절차를 거친 신분, 장사에 미칠 영향을 짚으며 상대를 설득하고 압박한다. 화가 나는 상황에서도 자신의 처지와 사용할 수 있는 수단을 생각하는 면모가 드러난다.","source":"S-4fad1d04608a"},{"title":"가족을 지키기 위해 감수하는 타협","text":"길란과의 만남에서는 라운데라 교단에 동족과 서부인의 동향을 보고하고, 이를 골기아에서 가족·동료·신앙을 지키기 위한 적응으로 설명한다. 필요한 사람과 가까워져야 한다는 계산도 숨기지 않는다. 이 선택에는 현실 감각과 씁쓸한 타협이 함께 있으며, 그의 친화력에 생존의 사정이 얽혀 있음을 보여준다.","source":"S-9fe18be02a0b"},{"title":"살아 있는 동료를 위해 싸우고 믿음을 배우다","text":"티아멧의 유해를 찾는 여정 뒤, 죽은 이를 위해 목숨을 거는 동료들을 온전히 이해하지 못했다고 말한다. 자신은 위험에 처한 살아 있는 동료들을 위해 싸웠다는 것이다. 션의 이야기를 들으며 가까운 사람들을 믿어보겠다고 답하고, 자신의 생각도 바꿀 필요가 있음을 인정한다. 애정과 두려움을 품은 채 관계의 폭을 넓혀가는 모습이 인상적이다.","source":"S-7ac67eae8ee4"}],"traits":{"social":{"score":5,"text":"문화 교류회에서 사람들을 부르고 자기소개와 문답을 이끈다. 비를 맞고 찾아온 어거스트를 맞아 불과 담요를 챙기고, 모카에게 서로 좋아하는 음식을 먹어보자고 제안하는 등 새 접점을 만드는 행동이 반복된다.","source":"S-7c736b1d84bd","supportingSources":["S-02e2a5196fb5","S-b93ec61f9dd6"]},"emotion":{"score":4,"text":"미샤가 없는 악몽의 불안을 동료들에게 털어놓고, 미샤의 비밀 의뢰를 오해했을 때는 션에게 관계를 상담한다. 애정과 불안이 판단에 영향을 주지만, 대화를 통해 돌아보고 진정하려는 모습도 있다.","source":"S-861086b4090d","supportingSources":["S-28e0b7447b47"]},"altruism":{"score":4,"text":"비에 젖은 낯선 방문자를 챙기고 동료의 몸 상태를 살핀다. 티아멧의 여정에서는 살아 있는 동료들이 위험해서 싸웠다고 설명한다. 주변 사람을 실제로 돕되, 무조건적인 자기희생을 당연하게 여기지는 않는 성향으로 읽힌다.","source":"S-7ac67eae8ee4","supportingSources":["S-02e2a5196fb5","S-a93aee63b76c"]},"initiative":{"score":4,"text":"가문을 떠나 미샤와 살 길을 직접 제안하고 실행한다. 모임의 진행을 맡아 사람들을 모으고, 차별적인 상인에게는 사과를 받아낼 때까지 행동한다. 매번 앞장서는 지휘관은 아니지만 중요한 선택과 일상의 문제를 스스로 움직여 풀어간다.","source":"S-f80c598e4db0","supportingSources":["S-7c736b1d84bd","S-4fad1d04608a"]},"caution":{"score":3,"text":"떠내려온 물고기를 확인 없이 먹어 배탈이 나는 등 일상에서는 즉흥적인 면이 있다. 반면 상인의 차별에는 신분과 손익을 이용해 대응하고, 가족과 신앙에 관한 일에는 골기아 사회의 위험과 이해관계를 계산한다. 상황에 따라 신중함의 정도가 달라지는 인물로 평가했다.","source":"S-9fe18be02a0b","supportingSources":["S-4fad1d04608a","S-fb96aac6cfe4","S-f7301c18bfae"]},"bonds":{"score":5,"text":"미샤의 외로움과 짐을 함께 감당하며 곁에 있겠다고 약속한다. 티아멧의 여정 뒤에는 션과 동료들을 믿는 법을 고민한다. 가까운 이들과 함께 살아갈 관계가 선택의 큰 기준이 된다.","source":"S-7ab1c252d917","supportingSources":["S-7ac67eae8ee4"]}},"relations":[{"name":"라이아흐 미샤","text":"가문을 떠나 함께 정착한 반려자. 사랑과 자유를 함께 선택했으며, 불안과 오해를 겪으면서도 서로의 삶을 나누려 한다.","source":"S-7ab1c252d917","characterId":"P-41ba4c5736e6"},{"name":"션","text":"미샤에 관한 불안과 동료에 대한 믿음을 상담한 친구. 티아멧의 여정 뒤 신뢰를 어떻게 배울지 이야기를 나눈다.","source":"S-7ac67eae8ee4","characterId":"P-3bbc4a823df9"},{"name":"사이먼 피터 포레스트","text":"서로의 몸 상태를 살피며 신앙과 치유의 한계를 이야기한 동료.","source":"S-a93aee63b76c","characterId":"P-3ea4affc20fd"},{"name":"모카","text":"서로 좋아하는 음식을 먹어보자고 제안하고 데미간 시장의 음식 문화를 함께 경험한 동료.","source":"S-b93ec61f9dd6","characterId":"P-f400f584340f"},{"name":"폴라리스","text":"바꿀 수 없는 과거와 길드의 어린 인물들을 어떻게 대할지 걱정을 나눈 동료.","source":"S-8e1231167356","characterId":"P-5d0c306440d0"}],"scenes":[{"source":"S-f80c598e4db0","text":"가문의 사슬을 벗어나 미샤와 자유롭게 살기로 결정한 대화."},{"source":"S-7ab1c252d917","text":"이해하지 못했던 외로움까지 함께 짊어지겠다는 약속."},{"source":"S-f7301c18bfae","text":"기도와 아침 식사, 살롱의 마사지 일을 이어가는 평소의 생활."},{"source":"S-4fad1d04608a","text":"차별을 당한 시장에서 자신의 존엄과 사과를 요구하는 방식."},{"source":"S-7ac67eae8ee4","text":"위험한 여정 뒤 션과 나눈 삶의 가치와 동료에 대한 믿음."},{"source":"S-9fe18be02a0b","text":"골기아에서 가족과 신앙을 지키기 위해 감수하는 타협과 계산."}],"updatedAt":"2026-09-29","asOf":"2026-09-24","sources":["S-4fad1d04608a","S-f80c598e4db0","S-f7301c18bfae","S-a93aee63b76c","S-7c736b1d84bd","S-9fe18be02a0b","S-7ac67eae8ee4","S-02e2a5196fb5","S-b93ec61f9dd6","S-861086b4090d","S-28e0b7447b47","S-fb96aac6cfe4","S-7ab1c252d917","S-8e1231167356"]},"P-b522cca806d0":{"name":"에스텔 벨라시타","tagline":"누군가를 구하는 길 위에서 자신도 소중히 여기는 법을 배우는 사람.","tags":["헌신적","자기성찰적인","마음 표현이 섬세한"],"profileNote":"벨라시타와 베라시타는 같은 인물이다. 성기사를 꿈꾸지만, 아서와의 대화에서는 아직 사제도 기사도 아니며 신성력이 없다고 스스로 설명한다. 출생의 비밀은 인물이 아는 내용과 추정의 범위를 구분했다.","facts":[{"label":"성장 배경","value":"어린 시절 성기사에게 구조되어 로운델 변방의 수녀원에서 자랐다. 자신을 구해준 사람과 같은 성기사가 되고 싶어 약 15살에 수녀원을 떠났다고 말한다.","source":"S-4787c94fc568"},{"label":"출생에 관한 고백","value":"생모를 포함한 희생자들이 바쳐진 흑주술 의식 속에서 태어났다고 토르번에게 털어놓는다. 정확히 어떤 의식이었는지, 자신에게 무엇을 남겼는지는 다 알지 못한다.","source":"S-9d683124e3f2"},{"label":"계속되는 조사","value":"잠결에 그린 문양을 도리안에게 보내 그 효과와 연결된 존재를 알아봐 달라고 부탁한다. 도리안도 즉시 답을 확정하지 못하며, 출생과 문양의 관계는 조사 중인 문제로 남는다.","source":"S-cc7e377a27cb"},{"label":"전투와 훈련","value":"한쪽 다리의 무릎 아래를 잃은 뒤 의족을 사용한다. 근력 운동과 검술 연습을 이어가고, 브랜의 도움으로 전투에 쓸 판금 의족을 마련한다.","source":"S-a2267866e320"},{"label":"길드에서 하는 일","value":"토르번의 집무실에서 서류를 돕고 임무와 교섭을 함께 고민한다. 사자회와의 충돌을 막기 위해 소규모 사절단을 먼저 보내자는 의견을 낸다.","source":"S-1e96be16c475"},{"label":"일상의 실천","value":"교회에서 빈민 급식을 준비하는 일을 돕는다. 사람을 구하고 싶다는 바람은 큰 임무 밖의 봉사와 노동으로도 이어진다.","source":"S-4185f70d4c10"}],"evaluation":[{"title":"선의에 얽힌 존재의 질문","text":"타인을 구하는 것 외에는 자신이 존재해도 된다는 확신을 얻지 못한다면 어떻게 해야 하느냐고 루체에게 묻는다. 남을 돕는 열망에는 자신의 출생을 죄처럼 짊어진 마음도 얽혀 있다. 루체 앞에서 자신을 소중히 여기겠다고 말하는 장면은, 그 부담을 스스로 알아보고 다른 길을 연습하는 시작점이다.","source":"S-65466fac2104"},{"title":"미움받을까 두려워도 내는 의견","text":"스텔라의 계획에 반대하면서 상관과 동료에게 미움받을까 두려웠다고 고백한다. 그럼에도 사람들이 다치거나 죽는 것이 더 싫어서 사절단을 제안했다. 순응적인 말투 안에도 자신의 판단을 지키는 힘이 있고, 상대가 위협을 느끼지 않게 접근할 방법까지 생각한다.","source":"S-9d683124e3f2"},{"title":"몸의 변화에 맞춰 계속 배우다","text":"의족을 쓴 몸으로 어떻게 버티고 움직일지 직접 훈련하고, 새로운 장비를 마련한다. 브랜에게 제작을 맡기고 도움에 감사하는 모습도 함께 나온다. 상실 뒤의 에스텔은 혼자 견디기만 하는 인물이 아니라, 동료의 기술과 자신의 노력을 연결해 다음 행동을 준비하는 인물이다.","source":"S-a2267866e320"},{"title":"편지와 고백으로 넓어지는 신뢰","text":"부상을 걱정시킬까 만남을 피하면서도 토르번과 필담을 이어가고, 훗날에는 출생의 비밀까지 털어놓는다. 두 사람은 자신 대신 희생된 이들의 이야기를 나눈다. 작은 장난과 부끄러움이 쌓인 관계가, 감추고 싶었던 부분까지 보여줄 수 있는 신뢰로 깊어진다.","source":"S-9d683124e3f2"},{"title":"혼자 갚는 삶에서 도움을 청하는 삶으로","text":"도리안에게 문양의 조사를 부탁하기까지는 동료를 사적인 일에 끌어들여도 되는지 망설인다. 결국 먼저 손을 내밀고, 출생의 기억을 들려주기로 한다. 남에게 기대도 된다는 말을 뒤늦게 받아들이는 변화는 에스텔의 성장에서 중요한 부분이다.","source":"S-cc7e377a27cb"}],"traits":{"social":{"score":3,"text":"예의를 갖춰 대화하고 도움을 요청할 수 있지만, 상처나 비밀을 보이는 일에는 오래 망설인다. 토르번과는 편지로 거리를 좁히고 도리안에게는 조심스럽게 상담을 청한다. 폭넓은 접근보다 신뢰를 쌓은 뒤 깊어지는 교류에 가깝다.","source":"S-006a9f46a0cf","supportingSources":["S-cc7e377a27cb","S-4787c94fc568"]},"emotion":{"score":4,"text":"걱정시키고 싶지 않은 마음과 미움받을까 하는 두려움이 행동을 망설이게 한다. 신뢰받는 순간에는 부끄러움과 눈물, 고마움도 선명하게 표현한다. 감정이 크면서도 상대를 배려해 표현을 고르는 편이다.","source":"S-9d683124e3f2","supportingSources":["S-006a9f46a0cf","S-65466fac2104"]},"altruism":{"score":5,"text":"타인을 구하는 일을 자신의 존재 이유와 연결할 만큼 중요하게 생각한다. 교회의 봉사를 돕고, 동료들이 다칠 위험을 줄이기 위해 상관에게 반대 의견도 낸다. 그 헌신이 자기 소모로 이어질 수 있다는 점까지 포함한 평가다.","source":"S-65466fac2104","supportingSources":["S-4185f70d4c10","S-1e96be16c475"]},"initiative":{"score":4,"text":"사절단을 먼저 제안하고 교섭 방식을 고민한다. 의족과 훈련을 준비하며 출생의 문양도 스스로 조사 의뢰한다. 머뭇거림이 있어도 필요한 일을 판단하면 직접 움직이는 장면이 반복된다.","source":"S-1e96be16c475","supportingSources":["S-a2267866e320","S-cc7e377a27cb"]},"caution":{"score":3,"text":"교섭에서는 상대를 자극할 위험과 정보 수집, 충돌을 피할 방법을 따진다. 반면 자기 부상은 숨기고 자신을 희생의 예외로 두기 쉽다. 다른 사람의 안전을 살피는 능력과 자기 보호의 어려움을 함께 반영했다.","source":"S-9d683124e3f2","supportingSources":["S-006a9f46a0cf","S-65466fac2104"]},"bonds":{"score":5,"text":"토르번의 편지를 소중히 간직하고 깊은 비밀을 나누며, 루체와 한 자기 보호의 약속을 받아들인다. 도리안이 해주었던 말을 기억하고 다시 찾아가는 모습에서도 관계의 말을 오래 품는 성향이 드러난다.","source":"S-006a9f46a0cf","supportingSources":["S-9d683124e3f2","S-65466fac2104","S-cc7e377a27cb"]}},"relations":[{"name":"토르번 팔켄하인","text":"편지와 안부를 주고받고 교섭의 역할을 함께 나누는 상대. 서로의 출생과 희생의 기억을 고백하며 신뢰가 깊어진다.","source":"S-9d683124e3f2","characterId":"P-7ba611cf90be"},{"name":"루체 루멘","text":"구하려는 사람들 속에 에스텔 자신도 들어가야 한다고 끈질기게 말해준 동료. 자신을 소중히 여기겠다는 약속을 나눈다.","source":"S-65466fac2104","characterId":"P-d8e7afee7c51"},{"name":"브랜","text":"판금 의족을 제작하고 필요하면 다시 손봐주겠다고 한 동료. 에스텔이 계속 움직이고 싸울 수 있도록 기술로 돕는다.","source":"S-a2267866e320","characterId":"P-55e987e3c831"},{"name":"도리안 바이덴스","text":"기대도 된다는 말을 기억하게 한 동료이자 문양의 조사를 부탁한 상대. 숨기던 출생의 이야기를 직접 들려준다.","source":"S-cc7e377a27cb","characterId":"P-dd70a1273f02"},{"name":"아서 나이츠베인","text":"기사란 무엇인지, 재능과 지위 없이도 무엇을 추구할 수 있는지 이야기한 동료. 서로의 이상을 다시 바라보게 한다.","source":"S-4787c94fc568","characterId":"P-9d7bf25dbba3"}],"scenes":[{"source":"S-4185f70d4c10","text":"구하고 싶은 마음이 빈민 급식 준비라는 일상의 노동으로 이어지는 장면."},{"source":"S-006a9f46a0cf","text":"부상을 숨긴 마음과 걱정, 장난이 쌓이는 집무실의 편지."},{"source":"S-9d683124e3f2","text":"미움받을 두려움을 넘어 낸 의견과 토르번에게 들려주는 출생의 비밀."},{"source":"S-cc7e377a27cb","text":"도리안에게 문양의 조사를 부탁하며 먼저 도움의 손을 뻗는 대화."},{"source":"S-a2267866e320","text":"꾸준한 훈련과 브랜의 제작으로 완성되는 새 판금 의족."},{"source":"S-65466fac2104","text":"루체 앞에서 자신도 소중히 여기겠다고 말하는 순간."}],"updatedAt":"2026-09-29","asOf":"2026-09-26","sources":["S-4787c94fc568","S-9d683124e3f2","S-cc7e377a27cb","S-a2267866e320","S-1e96be16c475","S-4185f70d4c10","S-65466fac2104","S-006a9f46a0cf"]},"P-d8e7afee7c51":{"name":"루체 루멘","tagline":"소중한 사람을 지키기 위해 어른에게도 필요한 질문을 던지는 사람.","tags":["직설적인","동료를 아끼는","행동하는"],"profileNote":"루멘 수도원에서 나온 어린 모험가의 활동을 정리했다. 어른에게 보호받는 일상과 실제 임무에서 판단하고 행동하는 모습을 함께 읽었다. 션과 숀은 서로 다른 인물이며, 여기서 아빠라고 부르는 상대는 션이다.","facts":[{"label":"출신","value":"루멘 수도원에서 지냈으며, 어머니가 몸담았던 인연을 따라 어설픈 용맹을 찾아온다. 수도원으로 돌아가기 싫다는 뜻을 분명히 밝힌다.","source":"S-7bab4166ab21"},{"label":"어머니","value":"스텔라가 티아리엘 산크타 룩스라는 이름을 알아보고, 멜라니온도 어머니와의 인연을 이야기한다. 길드에서의 첫 만남부터 어머니가 남긴 관계가 루체를 둘러싼다.","source":"S-7bab4166ab21"},{"label":"신앙과 능력","value":"라운데라에게 기도하고 신성력을 사용한다. 에켈수르 사건에서 상자의 기운을 살피고 기도로 갈 길을 묻는 등 신앙을 실제 사건 해결에 연결한다.","source":"S-3d36d422dff8"},{"label":"임무에서의 역할","value":"알아즈라 구출에 참여해 예비 수녀복을 활용하고, 지도에서 우물과 저수지의 연결을 찾아 탈출을 제안한다. 리엔 등 동료들의 능력과 함께 이동 방법을 마련한다.","source":"S-9a32dd671a68"},{"label":"가까운 가족 관계","value":"션과 서로 아빠와 딸로 대하는 관계다. 책을 읽어주거나 스스로 읽으면 용돈을 주겠다고 약속하는 식의 일상적인 돌봄이 기록되어 있다.","source":"S-407e4ad91cf4"},{"label":"중요하게 여기는 문제","value":"나이가 어리다는 이유로 동료의 선택을 배제하는 일에 반발한다. 아서를 남겨둔 판단에 관해 토르번에게 직접 묻고 신뢰의 기준을 따진다.","source":"S-92e4ccdfb559"}],"evaluation":[{"title":"자신의 자리부터 직접 요구하다","text":"길드에 처음 들어올 때부터 돌아가기 싫은 곳과 머물고 싶은 곳을 분명히 말한다. 어머니의 인연으로 어른들의 관심을 받지만, 그 안에서 자신의 의사도 강하게 드러낸다. 보호받는 위치에서도 스스로 결정하려는 태도가 이후의 활동으로 이어진다.","source":"S-7bab4166ab21"},{"title":"보호 속에 가려진 선택권을 묻다","text":"토르번에게 아서의 일을 따져 묻는 것은 단순한 반항으로만 읽기 어렵다. 루체가 중요하게 보는 것은 위험을 함께 감수할 동료로 인정받고, 자신이 모르는 곳에서 결정이 끝나지 않는 관계다. 상대에게도 사정이 있다는 설명을 듣지만 의견 차이가 완전히 사라지는 것은 아니다.","source":"S-92e4ccdfb559"},{"title":"신앙을 행동과 연결하는 문제 해결","text":"궁전 구출에서 기도로 얻은 실마리를 지도와 연결하고 우물의 상태를 손본다. 말로 해법을 내는 데서 그치지 않고 밧줄과 이동 경로를 준비하는 모습이 보인다. 탈출은 동료들의 협력으로 이루어지며, 루체의 강점은 그 협력이 향할 구체적인 방향을 찾는 데 있다.","source":"S-9a32dd671a68"},{"title":"친구의 자기희생에 동의하지 않는 다정함","text":"에스텔이 타인을 구해야 자신의 존재를 긍정할 수 있다고 말하자, 루체는 이미 존재하는 사람의 소중함을 되묻는다. 부드럽게 달래기보다 상대가 직접 자신을 소중히 여기겠다고 말할 때까지 대화를 이어간다. 직설적인 말투가 가까운 사람을 지키는 애정의 방식이 된다.","source":"S-65466fac2104"},{"title":"배움과 장난이 함께 있는 일상","text":"션에게 책을 읽어달라고 하고 용돈 약속을 받는 모습에는 아직 돌봄과 배움이 필요한 나이가 드러난다. 어른에게 질문하고 임무를 해결하는 능력과 이런 일상은 함께 존재한다. 모든 장면에서 작은 어른일 필요가 없다는 점이 루체를 더 입체적으로 만든다.","source":"S-407e4ad91cf4"}],"traits":{"social":{"score":4,"text":"첫 방문부터 자신의 의사를 직접 말하고, 필요한 논쟁이 있으면 토르번에게 먼저 찾아간다. 에스텔과는 진로와 출신을 묻는 대화를 깊게 이어간다. 말투가 거침없을 때도 있지만 사람과의 접점을 주저 없이 만든다.","source":"S-7bab4166ab21","supportingSources":["S-92e4ccdfb559","S-65466fac2104"]},"emotion":{"score":4,"text":"동료를 배제했다고 느끼면 분명하게 반발하고, 수도원으로 돌아가기 싫은 마음도 숨기지 않는다. 에스텔을 아끼는 마음 역시 반복되는 질문과 요구로 표현한다. 좋고 싫음과 걱정이 행동에 잘 드러나는 편이다.","source":"S-92e4ccdfb559","supportingSources":["S-7bab4166ab21","S-65466fac2104"]},"altruism":{"score":4,"text":"에스텔이 자신을 소모하지 않도록 긴 대화를 나누고, 위험한 구출에서는 일행이 빠져나갈 방법을 찾는다. 개인의 신앙과 행동력이 주변 사람을 살리고 함께 돌아오는 방향으로 사용된다.","source":"S-65466fac2104","supportingSources":["S-9a32dd671a68","S-3d36d422dff8"]},"initiative":{"score":5,"text":"동료의 처우에 관해 직접 질문하고, 에켈수르에서는 상자를 옮겨 문제를 해결하는 행동에 나선다. 궁전에서도 단서를 연결해 탈출로를 제안하고 준비한다. 필요하다고 판단하면 말과 행동 양쪽에서 먼저 움직인다.","source":"S-9a32dd671a68","supportingSources":["S-3d36d422dff8","S-92e4ccdfb559"]},"caution":{"score":3,"text":"궁전에서는 복장과 지도, 우물과 밧줄을 활용해 이동을 준비한다. 한편 비버 댐 소동에서는 라르손의 양말을 이용한 과감한 방법이 뒤탈을 남긴다. 준비할 줄 아는 능력과 즉흥적인 대담함을 함께 반영한 점수다.","source":"S-9a32dd671a68","supportingSources":["S-ab7cb0c49ff3"]},"bonds":{"score":5,"text":"함께하는 사람을 동료로 믿고 존중해야 한다는 기준이 강하다. 션과의 가족 같은 일상, 에스텔의 자기 보호를 요구하는 대화에서도 가까운 관계를 계속 돌보려는 태도가 드러난다.","source":"S-92e4ccdfb559","supportingSources":["S-407e4ad91cf4","S-65466fac2104"]}},"relations":[{"name":"션","text":"아빠와 딸로 대하며 책 읽기와 용돈, 돌봄을 나누는 가족 관계. 임무 밖에서 루체가 기대고 배우는 일상을 보여준다.","source":"S-407e4ad91cf4","characterId":"P-3bbc4a823df9"},{"name":"에스텔 벨라시타","text":"각자 수녀원에서 지냈다는 접점에서 진로와 자기 가치를 이야기한 동료. 에스텔 자신도 지켜야 한다고 요구한다.","source":"S-65466fac2104","characterId":"P-b522cca806d0"},{"name":"토르번 팔켄하인","text":"동료의 안전과 선택권을 두고 직접 논쟁하는 대장. 보호하려는 판단에도 신뢰에 관한 질문을 던진다.","source":"S-92e4ccdfb559","characterId":"P-7ba611cf90be"},{"name":"리엔 에이라스","text":"알아즈라에서 구출과 탈출을 함께한 동료. 루체가 찾은 경로와 리엔의 정령술이 협력하는 모습을 볼 수 있다.","source":"S-9a32dd671a68","characterId":"P-a161473e74e0"},{"name":"모나 델핀","text":"축제를 함께 즐기다가 검은 비의 사건까지 맞닥뜨린 동료. 모나는 루체를 돌보면서도 사건을 해결하는 행동을 함께한다.","source":"S-3d36d422dff8","characterId":"P-48cca58d02b2"}],"scenes":[{"source":"S-7bab4166ab21","text":"어머니의 이름과 루멘 수도원의 사정이 밝혀지는 첫 길드 방문."},{"source":"S-3d36d422dff8","text":"즐거운 축제에서 검은 비의 위기로, 기도와 상자를 둘러싼 선택."},{"source":"S-92e4ccdfb559","text":"동료를 보호한다는 말과 선택권을 믿는다는 말 사이의 논쟁."},{"source":"S-407e4ad91cf4","text":"션이 읽어주는 책과 스스로 읽은 뒤 받을 용돈의 약속."},{"source":"S-9a32dd671a68","text":"위장과 지도, 우물의 연결로 찾아내는 궁전의 탈출 경로."},{"source":"S-65466fac2104","text":"에스텔에게 자신의 소중함을 직접 말하게 하는 대화."}],"updatedAt":"2026-09-29","asOf":"2026-09-26","sources":["S-7bab4166ab21","S-3d36d422dff8","S-9a32dd671a68","S-407e4ad91cf4","S-92e4ccdfb559","S-65466fac2104","S-ab7cb0c49ff3"]},"P-48cca58d02b2":{"name":"모나 델핀","tagline":"두려워하는 동료에게 살아 돌아올 이유를 건네는 사람.","tags":["다정한","생명을 존중하는","귀환을 바라는"],"profileNote":"찹츄·챱츄로 남은 프로필도 모나의 기록에 포함한다. 자연과 순환에 관한 말은 모나의 관점으로 정리했으며, 순환을 겪는 꿈을 실제 사망이나 환생 이력으로 단정하지 않았다.","facts":[{"label":"성장 배경","value":"단델리온 유랑단에서 지냈다. 함께 자란 데미간들을 가족으로 여기며, 유랑단 시절부터 잡일과 어린 동생들을 돌보는 일에 익숙했다고 말한다.","source":"S-44fd8459dc7f"},{"label":"가족의 범위","value":"혈연과 종족에 한정하지 않고 유랑단과 길드 사람들을 가족으로 부른다. 새로 온 루체에게도 가족이 되었다고 환영한다.","source":"S-7bab4166ab21"},{"label":"능력","value":"자연력을 다루고 동물로 변신하는 드루이드다. 토팔에서는 식물 줄기를 자라게 하고 시들게 하는 능력을 상황에 맞게 활용한다.","source":"S-270dd493703c"},{"label":"자연관","value":"릴리 할머니에게 배운 순환의 관점을 이야기한다. 농사도 자연의 순리를 따르는 일이며 죽음도 새로운 생명으로 이어진다고 보고, 서로 다른 자연관에 관심을 보인다.","source":"S-70d9b92f2bd2"},{"label":"중요한 사건","value":"도착하지 않는 유랑단 가족을 기다리다 근심하는 모습이 단델리온 구출 사건의 출발점이 된다. 동료들이 가족의 행방을 찾아 나서며 길드와 유랑단의 인연이 이어진다.","source":"S-ff3ac8a00b17"},{"label":"돌봄을 받는 시간","value":"토팔에서 팔을 다친 뒤 라이티티아에게 포션과 돌봄을 받는다. 자신을 도와준 일에 감사하면서 라이티티아도 쉬어야 한다고 당부한다.","source":"S-e37297ab4b6c"}],"evaluation":[{"title":"가족으로 맞아들이는 환대","text":"새 사람에게 인사하고 자연스럽게 가족이라는 말을 건넨다. 그 말에는 다양한 데미간과 함께 자란 유랑단의 경험이 깔려 있다. 종족이나 외모가 달라도 한 울타리에서 돌보고 지낼 수 있다는 생각이 길드의 일상에서도 반복된다.","source":"S-7bab4166ab21"},{"title":"두려움을 없애는 대신 다음 걸음을 찾다","text":"엘레나가 죽음과 배신을 두려워하자 그 감정을 당연한 것으로 받아들인다. 물건을 대신 맡아주는 대신 무사히 돌아가 직접 전할 이유로 간직하라고 권한다. 모나의 위로는 감정을 부정하지 않으면서 살아갈 다음 행동을 찾게 하는 방식이다.","source":"S-5660e15d73e6"},{"title":"순환의 관점을 애도에 쓰다","text":"토팔에서 마리나의 무덤 곁에 꽃을 피우고 다음 순환에서 다시 만나기를 빈다. 다른 동료의 상실 앞에서도 작은 꽃으로 애도를 건넨다. 생명과 죽음의 순환을 믿는 태도가 슬픔을 가볍게 넘기는 이유가 되지 않고, 떠난 존재를 기억하는 행동으로 이어진다.","source":"S-270dd493703c"},{"title":"다정함 뒤에 있는 실무와 대응력","text":"에켈수르 축제에서 루체를 챙기고, 지크를 둘러싼 소동에는 정중히 말을 건네 상황을 풀려 한다. 검은 비가 내리자 원인을 찾고 동료들과 함께 움직이려 한다. 돌봄의 말뿐 아니라 주변을 살피고 문제에 개입하는 행동도 모나의 중요한 면이다.","source":"S-3d36d422dff8"},{"title":"돌보는 사람도 기대어 쉴 수 있다","text":"다친 팔이 아파도 처음에는 괜찮다고 말하지만, 라이티티아가 건네는 도움을 받고 고마움을 표현한다. 동시에 상대의 무리도 알아보고 휴식을 권한다. 늘 여유롭게 남을 챙길 수 있는 존재라기보다, 서로의 약한 순간을 돌보며 관계를 이어가는 사람으로 읽힌다.","source":"S-e37297ab4b6c"}],"traits":{"social":{"score":4,"text":"신입 때 모닥불에 어울리고 새로 온 루체에게 가족이라는 말을 건네는 등 환영과 인사에 적극적이다. 정령과 길드 사람들에게 먼저 말을 걸며 새로운 만남을 일상의 공동체 안으로 들인다.","source":"S-cd92a7ca2914","supportingSources":["S-7bab4166ab21","S-70d9b92f2bd2"]},"emotion":{"score":4,"text":"가족이 오지 않자 근심하고, 동료의 귀환에는 고마움을 표현한다. 엘레나의 두려움과 토팔에서의 상실에도 함께 반응한다. 밝고 다정한 말투 안에 걱정과 슬픔을 받아들이는 감정의 폭이 있다.","source":"S-ff3ac8a00b17","supportingSources":["S-44fd8459dc7f","S-5660e15d73e6","S-270dd493703c"]},"altruism":{"score":4,"text":"어린 동료를 챙기고 집안일을 함께하며, 상실을 겪은 사람 곁에 머문다. 다쳤을 때에도 자신을 돌봐준 상대의 휴식을 걱정한다. 스스로의 휴식과 도움도 필요한 사람이라는 점을 함께 반영했다.","source":"S-e37297ab4b6c","supportingSources":["S-44fd8459dc7f","S-3d36d422dff8","S-270dd493703c"]},"initiative":{"score":4,"text":"동료가 충돌한 자리에서 대화를 시도하고 검은 비의 원인을 찾자고 제안한다. 토팔에서는 자연력을 상황에 맞게 응용하고, 엘레나에게는 맡기려는 물건의 의미를 바꿔 제시한다. 조용히 따르기만 하는 돌봄은 아니다.","source":"S-3d36d422dff8","supportingSources":["S-270dd493703c","S-5660e15d73e6"]},"caution":{"score":4,"text":"엘레나에게 복수를 위해 몸을 내던지기보다 우선 살아 돌아갈 이유를 붙잡게 한다. 축제의 위험 앞에서는 동료들과 함께 조사하려 하고, 부상 뒤에는 서로 쉬어야 한다고 당부한다. 다만 자기 통증을 처음에 괜찮다고 넘기는 모습도 있다.","source":"S-5660e15d73e6","supportingSources":["S-3d36d422dff8","S-e37297ab4b6c"]},"bonds":{"score":5,"text":"유랑단과 길드 사람들을 가족으로 여기며, 동료가 돌아갈 사람과 장소를 소중하게 생각한다. 돌아온 마리아를 환영하고 떠난 이에게도 꽃과 기억을 남긴다. 함께 지내온 관계를 이어가려는 태도가 중심에 있다.","source":"S-7bab4166ab21","supportingSources":["S-ff3ac8a00b17","S-5660e15d73e6","S-44fd8459dc7f"]}},"relations":[{"name":"엘레나 레지아노","text":"죽음과 배신의 두려움을 털어놓은 동료. 모나는 물건을 맡아주는 대신 함께 살아 돌아갈 이유를 건네준다.","source":"S-5660e15d73e6","characterId":"P-89d5e8c6329e"},{"name":"마리아 아나이스 에스더","text":"설거지를 함께하며 각자의 변화를 나누는 동료. 돌아와 줘서 고맙다고 환영하고, 외모와 매력을 바라보는 자신의 경험을 이야기한다.","source":"S-44fd8459dc7f","characterId":"P-c9505ea97ebc"},{"name":"루체 루멘","text":"새 가족으로 맞아들인 어린 동료. 축제의 일상에서는 돌보고, 위기에서는 함께 상자를 옮기며 해결에 나선다.","source":"S-3d36d422dff8","characterId":"P-d8e7afee7c51"},{"name":"라이티티아","text":"부상 뒤 포션과 자장가로 모나를 돌본 동료. 모나도 도움을 받아들이고 상대의 휴식을 챙기며 돌봄을 주고받는다.","source":"S-e37297ab4b6c","characterId":"P-fae6af716ea2"}],"scenes":[{"source":"S-ff3ac8a00b17","text":"늦어지는 가족의 소식에서 시작되는 단델리온 유랑단 구출."},{"source":"S-70d9b92f2bd2","text":"언데드로 돌아온 동료와 새로운 사람들을 맞으며 나누는 자연과 순환 이야기."},{"source":"S-6863afb166b8","text":"여러 생명의 순환을 꿈꾸고 양의 모습으로 잠든 밤."},{"source":"S-5660e15d73e6","text":"엘레나가 맡기려던 물건을 살아 돌아올 이유로 바꾸는 대화."},{"source":"S-e37297ab4b6c","text":"부상 뒤 모나가 도움을 받고, 도와준 사람의 휴식도 챙기는 시간."},{"source":"S-270dd493703c","text":"자연력을 활용한 싸움과, 상실 뒤 꽃을 피워 건네는 애도."}],"updatedAt":"2026-09-29","asOf":"2026-09-26","sources":["S-44fd8459dc7f","S-7bab4166ab21","S-270dd493703c","S-70d9b92f2bd2","S-ff3ac8a00b17","S-e37297ab4b6c","S-5660e15d73e6","S-3d36d422dff8","S-cd92a7ca2914","S-6863afb166b8"]},"P-7ba611cf90be":{"name":"토르번 팔켄하인","tagline":"동료에게 구원받은 기억으로, 다시 동료의 내일을 지키려는 대장.","tags":["책임감 있는","걱정이 많은","애정 표현이 서툰"],"profileNote":"길드에서 공격대장을 맡는다. 팔켄하인 가문의 사건과 애건의 결말, 카일라와의 약속을 포함해 현재의 책임감이 생긴 배경을 함께 정리했다.","facts":[{"label":"역할","value":"스텔라에게 공격대장을 맡았다고 말한다. 길드원들을 책임지는 부담과 낭만적인 모험을 하고 싶은 마음을 시안에게 털어놓는다.","source":"S-5c80169e53df"},{"label":"실무","value":"업무 분담 뒤 길드원 관리를 맡는다. 스텔라는 왕가와 귀족에 관한 일, 션은 모험가 연합 등 대외 업무를 담당한다.","source":"S-39cc952fac30"},{"label":"가문과 형제","value":"팔켄하인 가문의 저주에 얽혀 있으며, 쌍둥이 동생 애건이 자신을 완벽한 팔켄하인으로 만들기 위한 제물로 바쳐졌다는 사실을 알게 된다. 동료들에게 도움을 요청하고 가문에 맞선다.","source":"S-6fa6dc7c1a69"},{"label":"전투 능력","value":"검을 사용하며 번개를 다루는 모습이 기록되어 있다. 팔켄하인 저택에서는 자신의 생명과 연결된 적을 상대하면서 동료들과 탈출과 대응책을 찾는다.","source":"S-6fa6dc7c1a69"},{"label":"기억하는 사람들","value":"애건의 일기를 보관하고, 자신 대신 희생된 동생과 시종들을 기린다. 에스텔에게 그 희생과 길드 동료들의 도움을 받은 것이 열심히 살아가는 이유라고 말한다.","source":"S-9d683124e3f2"},{"label":"카일라와의 약속","value":"죽음을 원하는 카일라에게 함께 짊어지겠다고 말하고 직접 검을 든다. 빼앗긴 목숨보다 더 많은 목숨을 살려 비명 대신 웃음이 들리게 하겠다고 약조한다.","source":"S-321f38393db2"}],"evaluation":[{"title":"도움을 받아 살아남은 사람이 책임을 맡다","text":"팔켄하인의 저주를 끊으려는 여정은 토르번이 동료들에게 도움을 청하면서 시작된다. 사건 뒤에는 애건의 일기를 남기고, 훗날 자신이 살아온 데에는 타인의 희생과 기대가 있었다고 고백한다. 책임감은 직책만의 문제가 아니라 자신을 구해준 이들에게 어떻게 응답할지에 관한 문제이기도 하다.","source":"S-9d683124e3f2"},{"title":"검으로 끝내기보다 살아갈 이유를 건네다","text":"카일라가 죽음을 원할 때 토르번은 그 선택을 도울 수 없다고 말한다. 직접 싸운 끝에 앞으로 함께 더 많은 생명을 구하겠다는 약속을 건넨다. 상대의 고통을 즉시 해결했다고 단정할 수는 없지만, 고통을 함께 짊어질 관계와 미래를 제안한다는 점이 토르번다운 장면이다.","source":"S-321f38393db2"},{"title":"싸움 전에 선택지를 확보하는 대장","text":"사자회에 대한 강경 대응을 보고 곧바로 전쟁에 해당할 수 있음을 지적한다. 에스텔의 사절단 제안을 받아들여 교섭과 정보 확인을 우선하고 필요한 인원을 고른다. 소중한 사람을 구하려는 목적을 놓지 않으면서도, 모두가 감당할 위험을 줄일 방법을 찾는다.","source":"S-1e96be16c475"},{"title":"보호하려는 판단도 질문받아야 한다","text":"루체가 아서를 남겨둔 일을 문제 삼자 당시 상황을 설명하고 과보호를 줄이겠다고 답한다. 다만 동료를 지킨다는 자신의 판단과 상대가 느끼는 배제 사이의 간극이 완전히 해소되지는 않는다. 책임을 지는 선의가 곧 정답은 아니라는 어려움이 이 관계에 남아 있다.","source":"S-92e4ccdfb559"},{"title":"대장이라는 호칭 뒤의 친구","text":"사이먼의 죽음을 듣고 더 잘해주지 못한 일을 후회하며, 무슨 일이 생겨도 자신의 책임처럼 느껴진다고 털어놓는다. 그러면서 시안에게 친구처럼 지내자고 청한다. 늘 버티는 대장의 모습 아래에는 책임을 잠시 내려놓고 동료들과 편하게 어울리고 싶은 사람도 있다.","source":"S-5c80169e53df"}],"traits":{"social":{"score":3,"text":"대장이라는 호칭이 만드는 거리를 느끼면서도 시안에게 친구처럼 지내자고 말한다. 에스텔에게는 편지로 마음을 전하며 머뭇거린다. 누구에게나 쉽게 다가가기보다 가까운 관계에서 조금씩 개인적인 얼굴을 보이는 편이다.","source":"S-5c80169e53df","supportingSources":["S-006a9f46a0cf","S-eb6cf10d0729"]},"emotion":{"score":4,"text":"동료의 죽음과 자신 대신 희생된 사람들에 대한 마음을 오래 품는다. 에스텔의 부상을 걱정하고 감춰진 사연을 들으며 자신의 기억도 나눈다. 감정을 절제해 말하는 편이지만 책임과 선택을 움직이는 힘은 크다.","source":"S-5c80169e53df","supportingSources":["S-9d683124e3f2","S-006a9f46a0cf"]},"altruism":{"score":4,"text":"카일라의 고통을 함께 짊어지고 앞으로 생명을 구하겠다고 약속한다. 가문의 사건이 끝날 때에는 억지로 동원된 영지민도 있을 것이라 보고 투항을 권고한다. 책임을 적극적으로 감수하되 모두를 혼자 구할 수 있다는 인물은 아니다.","source":"S-321f38393db2","supportingSources":["S-6fa6dc7c1a69","S-5c80169e53df"]},"initiative":{"score":5,"text":"가문의 저주에 맞서기 위해 도움을 청하고 직접 움직인다. 사자회 문제에서는 교섭 방안을 정하고 인원을 선발하며, 카일라에게는 행동과 약속으로 답한다. 개인의 위기와 공동의 일 양쪽에서 방향을 잡는 역할을 맡는다.","source":"S-1e96be16c475","supportingSources":["S-6fa6dc7c1a69","S-321f38393db2"]},"caution":{"score":4,"text":"사자회의 지도부와 바키르의 상태를 확인하고 무력 충돌을 마지막으로 미루는 순서를 세운다. 동료의 위험을 크게 보는 태도는 때로 과보호가 되기도 한다. 위험을 감수할 때에도 가능한 정보와 대안을 먼저 확보하려는 경향이 있다.","source":"S-9d683124e3f2","supportingSources":["S-1e96be16c475","S-92e4ccdfb559"]},"bonds":{"score":5,"text":"애건의 일기와 자신을 도운 사람들의 기억을 간직하고, 에스텔에게는 상처도 함께 나누어 달라고 말한다. 길드 사람들을 가족으로 부르며 함께 살아갈 약속을 중요하게 여긴다. 관계의 기억이 현재의 책임과 행동으로 이어진다.","source":"S-6fa6dc7c1a69","supportingSources":["S-006a9f46a0cf","S-eb6cf10d0729","S-321f38393db2"]}},"relations":[{"name":"에스텔 벨라시타","text":"편지와 작은 안부를 나누고, 교섭의 역할과 숨겨온 과거까지 공유하는 상대. 하고 싶은 말을 더 해도 된다며 판단을 믿어준다.","source":"S-9d683124e3f2","characterId":"P-b522cca806d0"},{"name":"루체 루멘","text":"보호하는 방식과 동료의 선택권을 직접 질문하는 동료. 토르번이 자신의 판단을 설명하고 돌아보게 한다.","source":"S-92e4ccdfb559","characterId":"P-d8e7afee7c51"},{"name":"시안 던 브링어","text":"사이먼의 죽음과 대장의 책임을 이야기한 동료. 직책이 만드는 거리 너머에서 친구처럼 지내고 싶다는 마음을 건넨다.","source":"S-5c80169e53df","characterId":"P-77d4478f4f51"},{"name":"스텔라 스타라이트","text":"길드의 위기를 함께 처리하지만 대응 방식에는 의견 차이도 있는 운영 동료. 사자회 문제에서 강경 대응을 교섭으로 조정하려 한다.","source":"S-1e96be16c475","characterId":"P-e6655a038328"},{"name":"션","text":"팔켄하인 가문의 저주에 맞서는 여정에 함께한 동료. 토르번이 자신의 위기를 길드에 맡길 수 있음을 보여주는 관계다.","source":"S-6fa6dc7c1a69","characterId":"P-3bbc4a823df9"}],"scenes":[{"source":"S-321f38393db2","text":"카일라에게 더 많은 목숨을 살리며 함께 짊어지겠다고 약속하는 대결."},{"source":"S-6fa6dc7c1a69","text":"가문의 저주에 맞서는 동료들, 애건의 희생과 남겨진 일기."},{"source":"S-5c80169e53df","text":"사이먼을 애도하며 대장이라는 책임과 친구라는 관계를 이야기하는 밤."},{"source":"S-006a9f46a0cf","text":"에스텔에게 상처도 나누어 달라고 적는 집무실의 편지."},{"source":"S-9d683124e3f2","text":"교섭의 역할을 나누다가 서로의 아픈 과거를 고백하는 시간."},{"source":"S-92e4ccdfb559","text":"루체의 질문 앞에서 보호와 신뢰의 기준을 다시 설명하는 대화."}],"updatedAt":"2026-09-29","asOf":"2026-09-23","sources":["S-5c80169e53df","S-39cc952fac30","S-6fa6dc7c1a69","S-9d683124e3f2","S-321f38393db2","S-1e96be16c475","S-92e4ccdfb559","S-006a9f46a0cf","S-eb6cf10d0729"]},"P-e6655a038328":{"name":"스텔라 스타라이트","tagline":"길드의 내일을 챙기면서 자신의 마법도 다시 찾으려는 사람.","tags":["실무적인","학구적인","책임을 중시하는"],"profileNote":"부길드장으로서의 운영 업무와 별을 좇아 마법을 배운 개인의 이야기를 함께 정리했다. 평소의 신중한 실무와 가까운 사람의 소식에 흔들리는 순간을 모두 성향 평가에 반영했다.","facts":[{"label":"길드에서의 역할","value":"어설픈 용맹의 부길드장. 12년 동안 운영을 맡아왔다고 회상하며, 토르번·션과 일을 나눈 뒤에는 주로 귀족과 왕가에 관한 업무를 처리한다.","source":"S-39cc952fac30"},{"label":"마법을 시작한 계기","value":"어릴 때 스스로 움직이는 듯한 밝은 별을 보고 고향의 산 정상에 있는 점성탑으로 향했다고 존에게 이야기한다. 마법 그 자체를 즐기는 마음을 중요하게 여긴다.","source":"S-15a9e2c59ba5"},{"label":"학문과 수련","value":"점성탑의 의지를 이은 마법사로 자신을 돌아본다. 실무에 매여 마법 이론이 낯설어진 것을 깨닫자 일주일 휴가를 선언하고 다시 공부할 시간을 찾는다.","source":"S-ce822b057b6d"},{"label":"가르치는 방식","value":"잭에게 세계의 끈 이론과 마법의 원리를 설명하고 실제 주문을 연습하게 한다. 이후 연습할 주문과 수인, 자신의 조언을 적은 자료도 챙겨준다.","source":"S-22cb536224a9"},{"label":"동료를 돕는 일","value":"에피메네우스의 생존 소식을 가족에게 알린다. 아들이 찾아온 뒤에도 가족의 요구만으로 결정하지 않고 에피메네우스 자신의 자유의지를 중요하게 말한다.","source":"S-195e708164b5"},{"label":"오래된 인연","value":"클램시를 친구이자 우상, 자신을 모험으로 이끌었던 영웅으로 회상한다. 클램시와 사자회의 단서를 받는 일은 오랫동안 운영을 지탱해온 개인적인 마음까지 흔든다.","source":"S-1e96be16c475"}],"evaluation":[{"title":"안부를 계획으로 바꾸는 실무","text":"마리아가 휴가를 떠나려 하자 목적지와 이동 경로, 믿을 만한 상단을 확인하게 하고 편지를 당부한다. 막연히 조심하라는 말보다 실제로 확인할 항목을 마련하는 방식이다. 스텔라의 돌봄은 일정과 문서, 경로처럼 생활을 지탱하는 구체적인 형태로 자주 나타난다.","source":"S-745e3605ea69"},{"title":"길드를 지키다가 놓친 자신의 마법","text":"오랫동안 서류를 처리하다 마법학개론이 낯설게 느껴지는 순간 큰 충격을 받는다. 스스로를 호되게 평가하는 반응에는 과장된 유머도 있지만, 좋아했던 일을 놓치고 있다는 아쉬움이 분명하다. 휴가를 선언하는 일은 책임을 맡은 사람에게도 자신을 되찾을 시간이 필요함을 드러낸다.","source":"S-ce822b057b6d"},{"title":"다른 마법사의 질문이 다시 켜는 호기심","text":"존과 야식 카레를 먹으며 마법이 수단인지 삶의 목표인지 논쟁한다. 어린 날의 별을 이야기하고 마음속의 별이 무엇인지 묻는 대화는 스텔라가 여전히 마법의 즐거움과 낭만을 원한다는 것을 보여준다. 경험 많은 운영자에게도 아직 답을 찾는 질문이 남아 있다.","source":"S-15a9e2c59ba5"},{"title":"책임이라는 말 뒤에 숨겼던 친밀함","text":"아리차가 떠난 뒤 모카와 친구의 의미를 이야기하며, 더 직접적으로 마음을 표현했어야 했는지 돌아본다. 사람들을 돌보는 의무에 익숙해도 자신이 누군가를 어떻게 좋아하는지 말하는 일은 쉽지 않다. 책임을 잘 수행하는 모습과 관계에 서툰 모습이 같은 사람 안에 있다.","source":"S-9b1369260074"},{"title":"유능한 판단에도 개인의 마음이 끼어든다","text":"사자회 문제에서는 바키르와 클램시에 얽힌 감정 속에서 강경한 대응을 추진한다. 토르번과 에스텔이 위험을 지적하고 사절단을 제안하자 제한된 시간을 허용한다. 언제나 침착한 관리자라기보다 소중한 관계 때문에 흔들리고, 동료의 의견과 조정하며 결정을 내리는 인물로 읽힌다.","source":"S-1e96be16c475"}],"traits":{"social":{"score":3,"text":"존과 식사를 나누며 논쟁과 개인적인 이야기를 이어가고, 잭에게는 시간을 들여 가르친다. 반면 친구라는 감정을 직접 표현하는 데에는 어려움이 있다. 역할이나 공통 관심사에서 시작해 가까워지는 교류가 두드러진다.","source":"S-15a9e2c59ba5","supportingSources":["S-22cb536224a9","S-9b1369260074"]},"emotion":{"score":4,"text":"평소에는 업무와 책임의 말로 감정을 정리하지만, 아리차의 부재나 클램시의 소식에는 그리움과 후회가 강하게 드러난다. 마법을 잊어가는 자신에게도 큰 충격을 받는다. 겉으로 차분한 장면만으로 감정의 영향이 작다고 보기는 어렵다.","source":"S-1e96be16c475","supportingSources":["S-9b1369260074","S-ce822b057b6d"]},"altruism":{"score":4,"text":"동료의 여행이 안전하도록 확인할 사항을 짚어주고, 잭의 연습 자료를 준비한다. 에피메네우스의 가족을 연결하면서도 본인의 뜻을 존중하려 한다. 시간과 실무 능력을 타인의 생활과 선택을 돕는 데 쓴다.","source":"S-745e3605ea69","supportingSources":["S-22cb536224a9","S-195e708164b5"]},"initiative":{"score":5,"text":"가족에게 직접 생존 소식을 알리고 수업과 운영의 결정을 실행한다. 자신의 공부가 밀린 것을 깨달았을 때도 휴가를 선언해 시간을 확보한다. 공동의 문제와 개인의 필요를 구체적인 행동으로 옮기는 힘이 크다.","source":"S-9ac1aab1539b","supportingSources":["S-22cb536224a9","S-ce822b057b6d","S-39cc952fac30"]},"caution":{"score":4,"text":"휴가 경로와 상단의 신뢰성을 확인하는 등 평소 실무에서는 위험을 세심하게 따진다. 다만 사자회 문제에서는 가까운 사람에 대한 감정이 강경 대응으로 이어져 동료들의 제동을 받는다. 안정적인 실무 능력과 흔들릴 수 있는 판단을 함께 반영했다.","source":"S-745e3605ea69","supportingSources":["S-1e96be16c475","S-195e708164b5"]},"bonds":{"score":5,"text":"클램시에 대한 오랜 우정과 그리움을 간직하고, 떠난 아리차에게 표현하지 못한 마음을 돌아본다. 동료의 편지를 기다리고 가족의 생존 소식을 잇는 행동에서도 관계를 오래 유지하려는 마음이 보인다. 표현의 서툶과 유대를 중시하는 정도를 구분해 평가했다.","source":"S-1e96be16c475","supportingSources":["S-9b1369260074","S-745e3605ea69","S-9ac1aab1539b"]}},"relations":[{"name":"존 (마법사)","text":"야식 카레를 함께 먹으며 마법의 즐거움과 앞으로의 목표를 논쟁하는 동료. 스텔라가 자신의 어린 날과 현재의 질문을 꺼내게 한다.","source":"S-15a9e2c59ba5","characterId":"P-79263e0865dd"},{"name":"잭 해리슨","text":"마법의 원리와 주문을 가르치는 상대. 말로 설명하는 데서 끝내지 않고 연습과 자료까지 챙기며 성장을 요구한다.","source":"S-22cb536224a9","characterId":"P-58df75b248fb"},{"name":"모카","text":"아리차의 부재 뒤 친구와 책임감에 관한 속마음을 나눈 상대. 어린 동료의 관점을 들으며 자신의 표현 방식을 돌아본다.","source":"S-9b1369260074","characterId":"P-f400f584340f"},{"name":"마리아 아나이스 에스더","text":"휴가의 이동 방법을 챙기고 편지를 보내라고 당부한 동료. 떠나 있는 동안에도 소식이 이어지기를 바란다.","source":"S-745e3605ea69","characterId":"P-c9505ea97ebc"},{"name":"토르번 팔켄하인","text":"길드의 일을 나누어 맡으며 위기 대응을 함께 의논하는 공격대장. 강경 대응에 반대하는 의견을 받고 사절단을 보낼 시간을 허용한다.","source":"S-1e96be16c475","characterId":"P-7ba611cf90be"}],"scenes":[{"source":"S-ce822b057b6d","text":"낯설어진 마법학개론 앞에서 자신을 돌아보고 휴가를 선언하는 순간."},{"source":"S-39cc952fac30","text":"업무를 나눈 뒤 홍차와 샌드위치 곁에서 다시 펼치는 마법책."},{"source":"S-9b1369260074","text":"모카에게 친구의 의미를 묻고 표현하지 못한 마음을 돌아보는 대화."},{"source":"S-195e708164b5","text":"에피메네우스와 가족의 재회를 돕되 본인의 선택을 중요하게 여기는 작별."},{"source":"S-15a9e2c59ba5","text":"존과 함께 먹는 야식, 마법을 시작하게 한 별과 아직 남아 있는 질문."},{"source":"S-1e96be16c475","text":"오래된 친구의 단서 앞에서 드러나는 그리움과 사절단을 둘러싼 결정."}],"updatedAt":"2026-09-29","asOf":"2026-09-22","sources":["S-39cc952fac30","S-15a9e2c59ba5","S-ce822b057b6d","S-22cb536224a9","S-195e708164b5","S-1e96be16c475","S-745e3605ea69","S-9b1369260074","S-9ac1aab1539b"]},"P-3bbc4a823df9":{"name":"션","updatedAt":"2026-09-30","tagline":"동료가 살아 돌아올 길을 가르치며, 자신도 사람에게 곁을 내주는 법을 배우는 사람.","tags":["능청스러운","가르치며 돌보는","신뢰를 선택하는"],"profileNote":"샤르니르라는 이름으로도 등장하는 션의 기록이다. 숀 카리엔·숀 사우스 풋과는 별개의 인물이다. 전쟁과 어린 시절의 회상은 대화가 기록된 날짜보다 앞선 사건이며, 진행자가 맡은 다른 인물의 행동과 구분해 정리했다.","facts":[{"label":"출신과 성장","value":"북부 헬그린두르에서 자란 샤르니르. 어린 시절 아버지의 가혹한 훈련과 폭력을 겪었다는 회상이 남아 있다. 강한 전사로 보이는 현재의 모습 뒤에 타인에게 쉽게 드러내지 않는 기억이 있다.","source":"S-a72740846b02"},{"label":"기사로서의 이력","value":"자신을 몰락귀족 출신이라고 말하며, 한때 듀플란테스 장원을 하사받은 지주기사였다고 설명한다. 옛 부관이자 대관인 하리에게 영지의 소식을 전하는 편지를 받는다. 현재 소유권에 대해서는 션의 설명과 하리의 편지가 서로 다르다.","source":"S-53ef21358683"},{"label":"전쟁 경험","value":"밀레엄의 전쟁을 회상하며 중앙수비대장, 중기병대의 선봉, 하사관들의 검술교관을 맡았다고 서술한다. 보급과 경계, 훈련을 중시하는 지휘 체계 속에서 일한 경험이 있다.","source":"S-c581cc4a6d67"},{"label":"길드에서의 역할","value":"길드원들의 지휘와 교육에 책임을 느껴 공격대장을 자청한다. 이후 운영 업무를 나눈 기록에서는 모험가 연합 등 대외 업무를 담당하는 인물로 나온다.","source":"S-39cc952fac30"},{"label":"가족","value":"루체는 옛 연인 티아리엘과의 사이에서 태어난 친딸이다. 딘에게 이 사실을 밝히며, 자신도 최근까지 딸의 존재를 몰랐고 티아리엘은 이미 세상을 떠났다고 말한다.","source":"S-53ef21358683"},{"label":"마리우스와의 관계","value":"마리우스를 첫 제자로 받아들인 뒤 연인이 된다. 고백을 받았을 때는 자신이 마흔 중반이며 딸이 있다는 점을 들어 거절하지만, 이후 다시 대화하고 함께하기로 한다.","source":"S-9c050760b1e6"},{"label":"전투와 가르침","value":"검술을 비롯한 다양한 무기와 실전 경험을 갖춘 무인이다. 마리우스와의 대련에서는 상대의 체구에 맞는 거리와 방어, 칼이 맞닿는 감각을 가르치며 유효타를 인정한다.","source":"S-7122ec5d483f"},{"label":"현재의 몸과 생활","value":"왼손을 잃은 뒤 간이 의수를 거쳐 새 의수를 사용한다. 식사 도구를 다룰 만큼 정교하게 움직이지만 감각은 없다고 느끼며, 달라진 몸으로 일상과 전투를 이어간다.","source":"S-259a89931e65"}],"evaluation":[{"title":"자유롭게 떠돌던 사람이 책임을 맡는 이유","text":"길드의 지휘 체계와 동료들의 행동을 보고 누군가는 가르치고 이끌어야 한다며 공격대장에 지원한다. 책임을 부담스러워하지 않느냐는 질문에는 자신이 싫어한 것은 오지랖 넓어 보이는 일이라고 답한다. 이 자리에서 루체의 아버지라는 사실도 공개된다. 길드가 자신이 드나드는 장소에서, 소중한 사람들과 함께 살아갈 곳으로 바뀌는 흐름이 보인다.","source":"S-4946fe0b8414"},{"title":"이기는 법보다 살아 돌아오는 법을 가르치다","text":"마리우스에게 체격의 차이를 고려하고 힘으로 맞서기보다 공격을 흘리는 방법을 익히게 한다. 첫 유효타를 인정하고 훈련을 마친 뒤에는 죽어서 돌아오지 말라고 당부한다. 다만 진검 대련과 거친 말투에서 드러나듯 가르치는 방식은 엄격하다. 애정이 곧 부드러운 교육 방식으로 나타나는 인물은 아니다.","source":"S-7122ec5d483f"},{"title":"뒤늦게 알게 된 딸 앞의 서툰 아버지","text":"루체의 어머니와 나이를 확인한 순간 평소의 능청스러운 태도가 무너지고, 자신이 아버지라고 밝히며 거듭 사과한다. 티아리엘을 떠난 사정과 이후 소식을 찾지 않았던 일도 인정한다. 딸이 돌아서는 것을 막지 못하고 오래 바라보는 장면은, 아버지라는 사실을 안 것과 그 관계를 쌓는 일이 서로 다르다는 것을 보여준다.","source":"S-0582407b4004"},{"title":"자기 상처를 보여주는 일은 여전히 어렵다","text":"루체에게는 손을 잃은 일을 농담처럼 이야기하지만, 마리우스가 돌아오자 부상을 숨기려고 피해 다닌다. 새로운 의수를 찾고 생활을 이어가는 대응력과 별개로, 가까운 사람에게 약한 모습을 알리는 일에는 서툶이 남아 있다. 다른 사람에게 도움을 받으라고 가르치는 선배도 자신의 상처 앞에서는 망설일 수 있다.","source":"S-8ca678b50564"},{"title":"가까워지는 것이 불편해도 따라 나서는 선택","text":"화를 내며 길드를 나선 숀을 따라가 먼저 이야기를 듣는다. 예전에는 사람에게 곁을 주기 싫어 떠돌았다는 지적에도 수긍하지만, 지금은 동료들이 스스로 포기하지 않는 한 계속 가르치겠다고 말한다. 신입들의 문제를 가볍게 보지는 않으면서도, 관계를 끊기 전에 자신이 할 일을 남겨두는 쪽으로 태도가 바뀐다.","source":"S-30114b2c856b"},{"title":"위험 앞에서 선택하는 믿음","text":"티아멧의 유해를 찾고 돌아온 뒤, 죽은 이를 위해 살아 있는 사람이 위험을 감수하는 일을 아카쿠와 이야기한다. 션은 죽음을 각오했다기보다 함께 싸우는 동료를 믿었다고 설명한다. 결과를 확신할 수 없고 자신도 늘 남을 믿지는 못한다는 점까지 인정한다. 그의 신뢰는 위험이 없다는 판단보다, 불확실한 순간에 누구와 함께 설 것인가에 관한 선택에 가깝다.","source":"S-7ac67eae8ee4"}],"traits":{"social":{"score":4,"text":"농담으로 말을 걸고, 화가 나 떠나는 숀을 따라가거나 아카쿠의 고민을 듣는 등 대화의 접점을 먼저 만든다. 다만 스스로도 가까워지는 것을 피했던 시기를 인정하며, 거친 농담이 누구에게나 편안한 것은 아니다. 쉽게 대화하는 능력과 깊이 곁을 내주는 어려움을 함께 읽었다.","source":"S-30114b2c856b","supportingSources":["S-7ac67eae8ee4","S-2f903333f52b"]},"emotion":{"score":4,"text":"평소에는 장난과 능청스러운 말로 감정을 감추지만, 루체가 친딸임을 알게 되자 크게 동요하고 사과한다. 마리우스에게 부상을 숨기거나 동료를 잃은 뒤 신뢰를 이야기하는 장면에서도 애정과 상실이 행동을 움직인다. 표현을 눌러두는 것과 감정의 영향이 작은 것은 구분했다.","source":"S-0582407b4004","supportingSources":["S-8ca678b50564","S-7ac67eae8ee4"]},"altruism":{"score":4,"text":"동료의 검술을 가르치고 고아원을 방문하며, 길드원이 숲에서 길을 잃지 않도록 울타리를 직접 만든다. 도움은 위기 속의 전투뿐 아니라 반복되는 교육과 생활의 수고로도 나타난다. 엄격한 판단과 거친 언행도 있어 언제나 다정하게 받아주는 인물로 보지는 않았다.","source":"S-37be20581475","supportingSources":["S-7122ec5d483f","S-726de945e654","S-b8ac904d6442"]},"initiative":{"score":5,"text":"공격대장에 먼저 지원하고 훈련과 생활 문제를 직접 손본다. 토르번에게는 길드 대표로 나가 지휘 경험을 쌓을 기회를 권한다. 자신이 앞장서는 것뿐 아니라 다른 사람이 역할을 맡도록 방향을 정하는 주도성도 있다.","source":"S-4946fe0b8414","supportingSources":["S-37be20581475","S-9e680c435366","S-7122ec5d483f"]},"caution":{"score":4,"text":"입회를 원하는 엘레나에게 모험의 부상과 죽음, 다른 동료에게 미칠 책임을 구체적으로 설명한다. 싸움의 승패도 힘만이 아니라 상황과 전략에 달렸다고 본다. 다만 자기 부상은 숨기고 중요한 순간에는 동료를 믿으며 위험에 나서는 면이 있어, 언제나 안전을 최우선으로 고르는 성향은 아니다.","source":"S-b8ac904d6442","supportingSources":["S-1c64575c73ba","S-8ca678b50564","S-7ac67eae8ee4"]},"bonds":{"score":5,"text":"루체에게 책과 고향의 말을 가르치며 뒤늦게 시작한 부녀의 일상을 쌓는다. 마리우스와 함께할 시간을 약속하고, 떠나려는 숀을 찾아가며, 티아멧의 유해를 되찾은 경험도 오래 이야기한다. 가까운 사람을 붙잡고 기억하며 관계를 이어가는 일이 현재의 선택에서 큰 비중을 차지한다.","source":"S-407e4ad91cf4","supportingSources":["S-52bdfe838e84","S-9c050760b1e6","S-30114b2c856b","S-7ac67eae8ee4"]}},"relations":[{"name":"루체 루멘","text":"티아리엘과의 사이에서 태어났지만 뒤늦게 존재를 알게 된 친딸. 책을 읽어주고 용돈을 약속하는 일상 속에서 아버지와 딸로 함께하는 시간을 쌓는다.","source":"S-407e4ad91cf4","characterId":"P-d8e7afee7c51"},{"name":"마리우스","text":"검술을 가르치는 첫 제자이자 연인. 처음의 거절과 다시 나눈 대화를 거쳐 함께하기로 하며, 스승으로서의 책임과 개인적인 애정이 겹친다.","source":"S-9c050760b1e6","characterId":"P-b6d81d634c6e"},{"name":"라이아흐 아카쿠","text":"티아멧을 찾는 여정 뒤 삶의 가치와 신뢰를 논한 친구. 서로의 생각이 다름을 인정하면서 함께 위험을 감수한 이유를 풀어간다.","source":"S-7ac67eae8ee4","characterId":"P-96ab98d2591c"},{"name":"숀","text":"이름이 비슷하지만 별개의 동료. 길드에 실망해 떠나려는 숀을 따라가, 신입을 가르치는 일과 등을 맡길 수 있는 믿음에 관해 이야기한다.","source":"S-30114b2c856b","characterId":"P-5c88d36f51cd"},{"name":"토르번 팔켄하인","text":"운영과 지휘를 나누어 맡는 동료. 길드 대표로 나설 기회를 권하며 사람을 이끄는 경험을 쌓도록 밀어준다.","source":"S-9e680c435366","characterId":"P-7ba611cf90be"},{"name":"스텔라 스타라이트","text":"공격대장 지원을 받아주고 길드의 책임을 함께 논의한 부길드장. 루체의 존재를 알리는 자리에서도 가족과 운영의 사정이 함께 드러난다.","source":"S-4946fe0b8414","characterId":"P-e6655a038328"},{"name":"티아멧","text":"새 무기를 연습할 때 조언과 농담을 나누던 동료. 길드에서 누가 강한지를 따지는 대화에 상황과 전략의 중요성을 짚어준다.","source":"S-1c64575c73ba","characterId":"P-22fdf8486544"}],"scenes":[{"source":"S-a72740846b02","text":"샤르니르의 어린 시절과 가혹한 아버지에 관한 회상. 현재의 모습 이전에 남은 상처를 보여준다."},{"source":"S-0582407b4004","text":"루체가 친딸이라는 사실을 처음 깨닫고 아버지라고 밝히는 모닥불의 밤."},{"source":"S-7122ec5d483f","text":"마리우스가 첫 유효타를 넣고, 션이 살아 돌아오라고 당부하는 대련."},{"source":"S-4946fe0b8414","text":"공격대장 지원과 부녀 관계의 공개가 함께 이루어지는 봄비의 하루."},{"source":"S-ce784d71660f","text":"손을 잃은 아버지에게 루체가 건네는 나무손과 새 의수를 마련할 계획."},{"source":"S-20364a689e31","text":"티아멧의 무기에서 행방을 추적해 유해를 되찾는 칼잡이의 노래."},{"source":"S-407e4ad91cf4","text":"모험이 담긴 책을 딸에게 읽어주며 다시 일상으로 이어지는 이야기."}],"asOf":"2026-09-24","sources":["S-a72740846b02","S-53ef21358683","S-c581cc4a6d67","S-39cc952fac30","S-9c050760b1e6","S-7122ec5d483f","S-259a89931e65","S-4946fe0b8414","S-0582407b4004","S-8ca678b50564","S-30114b2c856b","S-7ac67eae8ee4","S-2f903333f52b","S-37be20581475","S-726de945e654","S-b8ac904d6442","S-9e680c435366","S-1c64575c73ba","S-407e4ad91cf4","S-52bdfe838e84","S-ce784d71660f","S-20364a689e31"]},"P-558bf53bd08b":{"name":"린토와인드 크라우베드","updatedAt":"2026-10-01","mode":"stories","tagline":"옛 동료를 그리워하고, 새로운 모험가에게 선한 의지를 이야기한 검객.","tags":[],"profileNote":"직접 등장한 두 기록만 확인되어 지속적인 성격과 성향을 분석하기는 어렵다. 아래에는 등장 장면에서 확인되는 정보와 이야기만 정리했다. 성향 점수와 핵심 성향은 부여하지 않았다.","facts":[{"label":"이름","value":"길드를 찾아왔을 때는 린토 크라우베드로 서술되고, 술자리에서는 자신을 린토와인드 크라우베드라고 소개한다.","source":"S-3e59f21bc371"},{"label":"모습","value":"페디안을 찾아온 장면에서는 보라색 벨벳 망토를 걸친 해골 모습의 언리빙으로 묘사된다.","source":"S-635e24afaa2b"},{"label":"출신과 나이","value":"남부에서 태어나 어린 시절 중부로 옮겼다고 말한다. 현재 연도를 물어본 뒤 술자리에서 계산한 나이는 백마흔다섯이다.","source":"S-3e59f21bc371"},{"label":"지난 모험","value":"클램시를 따라 모험했다고 회상한다. 서술자는 일곱 영웅 중에서도 강한 의지를 지녔으며 선함을 추구한 검객으로 소개한다.","source":"S-3e59f21bc371"}],"evaluation":[],"traits":{},"relations":[{"name":"페디안 1세","text":"모닥불에 찾아와 젊은이들을 겁주지 말라고 말을 건넨 옛 동료. 변하지 않은 길드를 둘러본 뒤 그의 어깨에 손을 얹고 떠난다.","source":"S-635e24afaa2b","characterId":"P-53bbaf9d6e52"},{"name":"델타인","text":"좋은 친구를 사귀고 있는지 묻고, 무엇이 선한지 고민하는 대화를 나눈다. 델타인을 여전히 좋아하고 싶다는 마음을 의지의 예로 들어 설명한다.","source":"S-3e59f21bc371","characterId":"P-c93f55c91873"},{"name":"거베라 데이시","text":"술자리에서 이름과 출신을 소개하며 만난 인물. 거베라에게 잔을 권하고 서로의 이야기를 듣는다.","source":"S-3e59f21bc371","characterId":"P-2a0e01fe8908"}],"scenes":[{"source":"S-635e24afaa2b","text":"페디안의 모닥불에 잠시 들른 린토는 오래된 길드를 바라본다. 떠나기 전 스텔라의 얼굴을 한 번 봤으면 좋았겠다고 말한다. 이 장면에서 스텔라와 실제로 재회한 것은 아니다."},{"source":"S-3e59f21bc371","text":"거베라와 동료들에게 술을 권하며 자기소개를 한다. 대화는 고향과 나이, 클램시의 모험으로 이어지고, 델타인에게 유명해서 용감한 것이 아니라 용감하게 살아 이름을 남기는 것이라는 취지로 조언한다. 선악에 관한 질문에는 상황과 자신이 바라는 것을 살피라고 답한다."}],"asOf":"2026-08-22","sources":["S-3e59f21bc371","S-635e24afaa2b"]},"P-7ca1485d4525":{"name":"바키르 리온하르트","updatedAt":"2026-10-01","tagline":"함께 살아남는 법을 가르치고, 자유로운 선택으로 동료의 곁을 지키는 노련한 사자.","tags":["협동을 가르치는","사려 깊은","동료를 아끼는"],"profileNote":"바키르가 직접 말하거나 행동한 장면을 중심으로 정리했다. 같은 프로필이 진행한 훈련의 적군·다른 동료들의 행동은 바키르의 성격 근거로 삼지 않았다. 공격대장 직책은 해당 시점의 기록이다.","facts":[{"label":"길드에서의 역할","value":"전쟁 준비 훈련에서 어설픈 용맹의 공격대장으로 소개된다. 사자회의 젊은 사자들을 데려와 길드원들과 합동 훈련을 진행한다.","source":"S-d5208e350565"},{"label":"전쟁 이후의 생활","value":"전쟁 뒤 사자회에서 젊은 사자들을 가르쳤다고 말한다. 에레모시스와는 전쟁에서 서로 다른 편에 섰지만, 개인적인 증오로 싸웠던 것은 아니라고 돌아본다.","source":"S-4e5e48794fe9"},{"label":"길드에 온 이유","value":"클램시가 남긴 것을 지켜달라는 스텔라의 편지를 받고 길드에 왔다. 함께 지내며 길드원들이 좋아졌고, 이제는 자신만의 이유로 이들을 지키고 싶다고 설명한다.","source":"S-4e5e48794fe9"},{"label":"대외 업무","value":"길드의 사절로 조합 회의에 출석하고 정세를 전한다. 전쟁에 인원을 보내야 할 가능성을 옛 전우들과 의논하고, 논의 내용을 스텔라에게 문서로 전달한다.","source":"S-41c4ebe066e0"},{"label":"대장간","value":"직접 풀무질과 단조를 한다. 쇠의 상태를 살피며 반복해서 달구고 두드리는 일에 익숙하고, 그 부지런한 작업 속에서 삶의 자세를 생각한다.","source":"S-15896c086c5d"},{"label":"휴식과 취미","value":"새해 모닥불에서 폴라리스의 옛 이야기를 기억하며 합주를 제안하고 피리를 분다. 서툰 합주도 즐거워하며 잠시 행정 일을 잊는다.","source":"S-633df491d0a9"},{"label":"이후의 행방","value":"8월에 숀은 사자회 간부들이 죽었다는 소문을 근거로 바키르도 죽은 것 같다고 션에게 말한다. 숀 스스로도 정확하지 않다고 덧붙이므로, 이 대화만으로 사망을 확정하지 않았다.","source":"S-30114b2c856b"}],"evaluation":[{"title":"내 방패만으로는 살아남을 수 없다","text":"각자 다른 방패를 가져온 길드원들에게 먼저 서로 의논하지 않은 점을 지적한다. 방패의 모양부터 높이, 보폭까지 옆 사람과 맞추게 하는 훈련은 전투 실력의 합만으로 공동체가 움직이지 않는다는 것을 보여준다. 엄격한 말투의 목적은 개인의 멋진 승리보다 동료가 함께 살아남는 데 있다.","source":"S-d5208e350565"},{"title":"과거의 적과도 선택을 존중하며 함께 서다","text":"에레모시스가 클램시에게서 신성을 이야기할 때 바키르는 한 인간이 스스로 내린 선택을 본다. 같은 영웅을 다른 방식으로 기억해도 신앙을 통일하려 하지 않는다. 서로 적이었던 과거를 지운 것이 아니라, 현재 무엇을 지킬지 각자 고른다는 점에서 동행의 이유를 찾는다.","source":"S-4e5e48794fe9"},{"title":"강한 사람과 전장에 보낼 사람을 구분하다","text":"전쟁에 차출할 인원을 논할 때 나이, 경험, 체격과 대형, 지휘할 사람을 차례로 살핀다. 아이다가 어리다는 점도 짚는다. 유능한 모험가라는 이유만으로 전쟁에 적합하다고 판단하지 않으며, 결정권자에게 논의를 넘기는 절차도 지킨다.","source":"S-41c4ebe066e0"},{"title":"실패해도 되는 자리의 가치를 아는 선배","text":"훈련에서는 전쟁에 다음 시도가 없을 수 있음을 경고하며 지금 시험해 보라고 한다. 새해 합주에서는 완벽하지 않아 즐겁다는 태도로 웃는다. 상황에 맞는 엄격함을 요구하면서도, 배움과 놀이의 실수까지 모두 실패로 취급하지는 않는다.","source":"S-c69c8caba981"},{"title":"부활 앞에서도 멈춰 생각하다","text":"진저가 돌아온 일을 직접 보았지만 테론의 부활에 곧바로 찬성하지는 않는다. 알 수 없는 위험을 이유로 시도를 거부하는 쪽에 선다. 동료를 아끼는 마음과 무엇이든 해보겠다는 행동 사이에 거리를 둘 수 있는 인물이다.","source":"S-c5e3e7fd297d"}],"traits":{"social":{"score":4,"text":"차를 나누며 옛 전우의 안부를 묻고, 새해 모닥불에서는 합주를 먼저 제안한다. 편안한 자리에서 상대의 말을 듣고 교류를 이어가는 장면이 반복된다.","source":"S-633df491d0a9","supportingSources":["S-41c4ebe066e0"]},"emotion":{"score":3,"text":"길드원들이 좋아졌다는 마음과 이루지 못한 평범한 생활의 아쉬움을 담담하게 말한다. 감정을 숨기지는 않지만, 그리움이 곧바로 충동적인 결론으로 이어지지는 않는다.","source":"S-4e5e48794fe9","supportingSources":["S-c5e3e7fd297d"]},"altruism":{"score":4,"text":"동료의 생존을 위해 시간을 들여 훈련시키고, 어린 인물을 전장에 보내는 판단에도 신중하다. 보호의 의지는 추상적인 다짐보다 교육과 배치의 책임으로 나타난다.","source":"S-d5208e350565","supportingSources":["S-41c4ebe066e0"]},"initiative":{"score":4,"text":"훈련을 마련하고 조합에서 얻은 정보를 모아 회담을 연다. 필요한 행동은 먼저 시작하되 길드의 최종 결정을 혼자 대신하지 않는다.","source":"S-41c4ebe066e0","supportingSources":["S-d5208e350565"]},"caution":{"score":5,"text":"전쟁과 개인 전투의 차이를 구체적으로 따지고, 훈련에서 위험을 미리 경험하게 한다. 이미 부활을 본 경험이 있어도 다른 부활의 안전까지 보장된다고 생각하지 않는다.","source":"S-c5e3e7fd297d","supportingSources":["S-41c4ebe066e0","S-d5208e350565"]},"bonds":{"score":4,"text":"클램시의 유산을 지켜달라는 부탁으로 시작한 동행이 현재의 동료들에 대한 애정으로 이어진다. 오래된 전우의 기억과 새롭게 생긴 관계를 함께 소중히 여긴다.","source":"S-4e5e48794fe9","supportingSources":["S-633df491d0a9"]}},"relations":[{"name":"에레모시스","text":"과거 전쟁에서 반대편에 섰던 상대. 클램시를 바라보는 관점은 다르지만, 각자의 자유로운 선택을 인정하며 함께 길드를 지킬 이유를 나눈다.","source":"S-4e5e48794fe9","characterId":"P-d6e0d1eb8b63"},{"name":"폴라리스","text":"이십 년 전부터 이야기를 기억하는 음유시인. 새해의 모닥불에서 무용담과 합주를 즐기며 오랜 기억을 나눈다.","source":"S-633df491d0a9","characterId":"P-5d0c306440d0"},{"name":"션","text":"전쟁에 나설 인원의 조건과 지휘 문제를 함께 논하는 옛 전우. 이 자리의 션은 숀 사우스풋과 다른 인물이다.","source":"S-41c4ebe066e0","characterId":"P-3bbc4a823df9"},{"name":"라이아흐 미샤","text":"방패벽 훈련에서 대형을 정리하고 명령을 내리는 역할을 맡긴 동료. 실제로 말하고 움직여 보게 하며 협동의 요령을 익히도록 한다.","source":"S-d5208e350565","characterId":"P-41ba4c5736e6"},{"name":"스텔라 스타라이트","text":"테론의 부활 시도를 두고 같은 신중한 입장에 선 동료. 길드의 손실 앞에서도 남은 사람들에게 닥칠 위험을 함께 고려한다.","source":"S-c5e3e7fd297d","characterId":"P-e6655a038328"}],"scenes":[{"source":"S-4e5e48794fe9","text":"에레모시스에게 전쟁 이후의 삶과 길드를 지키고 싶은 이유를 말하는 밤."},{"source":"S-633df491d0a9","text":"폴라리스의 이야기와 서툰 합주를 즐기는 새해 모닥불."},{"source":"S-41c4ebe066e0","text":"전쟁에 보낼 사람과 그들을 이끌 사람을 함께 고민하는 회담."},{"source":"S-d5208e350565","text":"서로 다른 방패를 고른 데서 시작해 함께 보폭을 맞추기까지 이어지는 훈련."},{"source":"S-15896c086c5d","text":"달군 쇠를 부지런히 돌보며 일상 속의 깨달음을 얻는 단조."},{"source":"S-c5e3e7fd297d","text":"테론을 잃은 뒤, 부활의 가능성과 위험을 앞에 두고 내리는 판단."}],"asOf":"2026-08-15","sources":["S-d5208e350565","S-4e5e48794fe9","S-41c4ebe066e0","S-15896c086c5d","S-633df491d0a9","S-30114b2c856b","S-c69c8caba981","S-c5e3e7fd297d"]},"P-c1b3ef30b227":{"name":"안케트와","updatedAt":"2026-10-01","mode":"stories","tagline":"클램시의 계약과 길드의 비밀에 얽혀, 소원 거래와 쿠키 소동 사이를 오가는 악마.","tags":[],"profileNote":"직접 등장한 기록은 네 이야기로 연결했다. 분량에는 진행자의 서술과 다른 인물의 행동이 많이 포함되어 있으며, 계약과 정체도 아직 설명되지 않은 부분이 있다. 지속적인 성격을 점수로 분석하기보다 확인된 이야기와 본인이 밝힌 내용을 구분해 소개한다.","facts":[{"label":"정체와 옛 인연","value":"서술자는 크아킨과 맞서 어설픈 용맹 편에서 싸운 악마로 소개한다. 안케트와 자신도 최초의 일곱 인물 중 하나였다고 말한다. 귀환 당시에는 작고 검은 털뭉치 같은 모습으로 나타난다.","source":"S-1ff6f3a007ea"},{"label":"클램시와의 계약","value":"클램시가 자신의 심장을 가져갔으며 일기를 교환했다고 주장한다. 몸을 되찾을 단서를 찾기 위해 클램시의 방에 들어가려 한다. 이 대화만으로 클램시의 현재 생사나 심장의 행방이 확인된 것은 아니다.","source":"S-1ff6f3a007ea"},{"label":"소원 거래","value":"클램시가 이미 대가를 치렀다고 말하며 한 사람당 하나의 소원을 제시한다. 아카쿠가 인간과 드라고니안 사이에서 아이를 가질 방법을 묻자 불가능하다고 답한다. 질문에 답하는 장면과 모든 소원을 실현하는 능력은 구분할 필요가 있다.","source":"S-1ff6f3a007ea"},{"label":"갈래 세계","value":"이름을 불러 찾는 일행 앞에 나타나 푸른 공간을 갈래 세계라고 설명한다. 그 세계의 주인이 자신을 반기지 않는다며 모습이 사라지는 등, 자유롭게 무엇이든 해결하는 존재로 묘사되지는 않는다.","source":"S-49fb545a282d"}],"evaluation":[],"traits":{},"relations":[{"name":"에레모시스","text":"귀환한 안케트와의 정체를 알아보고 클램시의 방으로 들어가는 것을 경계한다. 옛 사건과 현재의 길드, 소원 거래를 두고 격하게 다툰다.","source":"S-1ff6f3a007ea","characterId":"P-d6e0d1eb8b63"},{"name":"라이아흐 아카쿠","text":"아이를 가질 방법을 소원으로 질문한 상대. 안케트와의 장난스러운 모습과 거대한 악마의 모습이 겹쳐 보이는 대화를 나눈다.","source":"S-1ff6f3a007ea","characterId":"P-96ab98d2591c"},{"name":"루체 루멘","text":"갈래 세계에서 이름을 불러 도움을 구하고, 길드에서는 쿠키를 둘러싸고 다툰다. 서로 다른 사건에서 반복해서 마주한다.","source":"S-49fb545a282d","characterId":"P-d8e7afee7c51"},{"name":"모카","text":"쿠키를 가져가려다 소동이 벌어진 상대. 안케트와는 집의 물건이 모두 자기 것이라고 우기며 가구를 움직인다.","source":"S-546fa49489ac","characterId":"P-f400f584340f"}],"scenes":[{"source":"S-1ff6f3a007ea","text":"길드로 돌아와 클램시를 찾는다. 방에 걸린 마법과 자신의 몸을 이야기하며 길드원들에게 소원을 제안하고, 에레모시스의 불신과 맞선다. 악마의 주장과 길드원들이 기억하는 과거가 충돌하는 이야기다."},{"source":"S-49fb545a282d","text":"똑딱이는 우물에서 갈래 세계로 이어진 사건. 안케트와는 루체에게 돌아가야 한다고 경고하고, 이후 세계의 성격을 설명한다. 귀환 과정에는 델타인과 머독의 행동도 함께 작용한다."},{"source":"S-546fa49489ac","text":"모카의 쿠키를 가져가려다 루체와 실랑이를 벌인다. 서랍과 의자를 움직이고 건물을 떨리게 한 뒤 사라진다. 이후 등장해 소동을 묻는 숀의 대사는 안케트와의 행동이 아니다."},{"source":"S-6cf9541f9b6f","text":"히프노스의 초대로 꿈에 갇힌 루체를 찾는 이야기에서 호출된다. 꿈속 안케트와의 정체를 두고 진행 중 문답이 오간다. 일행이 초대의 계약을 깨뜨리고 돌아오는 과정에 등장하며, 꿈속 묘사를 모두 현실의 확정 설정으로 옮기지는 않았다."}],"asOf":"2026-05-23","sources":["S-1ff6f3a007ea","S-49fb545a282d","S-546fa49489ac","S-6cf9541f9b6f"]},"P-41ba4c5736e6":{"name":"라이아흐 미샤","updatedAt":"2026-10-01","tagline":"자신을 지키며 살아온 드루이드가, 반려자 밖으로 가족의 의미를 넓혀가는 이야기.","tags":["현실적인","관계를 돌보는","자기 선택이 분명한"],"profileNote":"어린 시절의 회상과 길드에서 생활하는 현재를 구분했다. 아케오의 가르침은 미샤의 말과 같지 않으며, 드루이드 수행·생존 경험·반려 관계가 현재의 선택에 어떻게 이어지는지를 읽었다.","facts":[{"label":"종족과 배경","value":"인간으로, 어린 시절 드라고니안 사회에서 아카쿠의 반려인간으로 취급받으며 자랐다. 열두 살의 회상에는 다른 시종들의 괴롭힘과 보호받기 어려웠던 생활이 나온다.","source":"S-9b6c1cd9a44e"},{"label":"드루이드 수련","value":"아케오에게 배우고 여러 지역을 유랑하며 자연과 사회를 함께 관찰했다. 열여섯 무렵의 이야기에서 종족과 문화의 관계, 자신이 속할 곳을 고민한다.","source":"S-dce433af06f4"},{"label":"아카쿠와의 관계","value":"스카일라를 떠나 함께 골기아로 향한 반려자. 서로 다른 차별과 생존 경험을 털어놓고, 아카쿠가 미샤의 외로움도 함께 짊어지겠다고 약속한다.","source":"S-7ab1c252d917"},{"label":"길드에서의 행동","value":"동료의 고민을 듣고 식사에 데려가거나 말동무가 되어주겠다고 한다. 아도니스에게는 가족과의 관계를 달라진 모습으로 다시 맺을 수도 있다고 권한다.","source":"S-96cb07f9f25a"},{"label":"보호와 복수","value":"아카쿠가 습격당하자 간호하면서 가해자의 신상을 알아낸다. 직접 보복할 수 있다고 생각하지만 길드의 존재를 고려해 동료들에게 도움을 청하기로 한다.","source":"S-219ce0b71190"},{"label":"넓어지는 가족","value":"엘라의 장례 뒤, 아카쿠와 스승 이외의 사람을 잃는 일도 자신의 마음을 흔든다는 것을 깨닫는다. 모카의 위로를 받으며 길드에 친구가 생겨가고 있음을 말한다.","source":"S-f215d5fe131a"}],"evaluation":[{"title":"다정함 뒤에 있는 생존의 경험","text":"미샤는 아카쿠를 보살피지만 그 역할만으로 자신을 설명하게 두지 않는다. 사막을 건넌 뒤에는 살인과 차별을 겪어온 자신을 숨기지 않고 이야기한다. 순종적인 보호 대상이었던 과거에서 벗어나, 상대가 자신의 거친 면까지 알아주기를 요구하는 사람이다.","source":"S-7ab1c252d917"},{"title":"언제나 어른이고 싶지는 않다","text":"길드 바닥에 누워 칭찬을 요구하는 장면은 우스우면서도 요구가 분명하다. 책임을 지는 어른이어도 응석부릴 시간이 필요하다는 것이다. 아카쿠를 돌보는 역할이 아닌 미샤 자신에 대한 칭찬을 원한다는 말에서, 타인을 챙기는 사람도 독립된 관심과 휴식을 바란다는 마음이 보인다.","source":"S-06f88fc7d320"},{"title":"정답을 주기보다 곁에 머무르는 상담","text":"아도니스가 변화와 버림받는 일을 두려워하자 당장 목표를 정하거나 가족을 찾아가라고 몰아붙이지 않는다. 쉬어가고 관계를 새로 맺을 가능성을 이야기하며 말동무를 자청한다. 자연을 배운 경험이 사람도 변하며 살아갈 수 있다는 여유로 이어지는 장면이다.","source":"S-96cb07f9f25a"},{"title":"애정이 곧 온순함을 뜻하지는 않는다","text":"아카쿠를 해친 사람들에게 보복하려는 마음과 자신의 살인에 대한 태도를 명확하게 드러낸다. 다만 길드의 규칙과 동료들을 떠올리며 혼자 처리하는 대신 도움을 청한다. 배려와 냉혹한 판단이 공존하고, 관계가 그 행동을 조정하기 시작한다는 점이 중요하다.","source":"S-219ce0b71190"},{"title":"가족이 늘어나면서 생기는 슬픔","text":"엘라를 보내며 이전에는 예상하지 못했던 상실을 느낀다. 아카쿠만 가족이라고 생각하던 경계가 느슨해진 만큼 상처받을 가능성도 커진 것이다. 모카에게 친구가 생긴다고 말하는 장면은 길드에 익숙해졌다는 설명보다 그 변화를 선명하게 보여준다.","source":"S-f215d5fe131a"}],"traits":{"social":{"score":4,"text":"동료를 찾아 식사와 대화를 권하고, 말동무가 되어주겠다고 먼저 제안한다. 늘 밝게 어울리기보다 상대의 상태를 살피며 접점을 만드는 쪽이다.","source":"S-96cb07f9f25a","supportingSources":["S-06f88fc7d320"]},"emotion":{"score":4,"text":"억울했던 과거와 아카쿠에 대한 마음을 직접 말하며, 엘라의 죽음 앞에서는 공허함과 두려움을 느낀다. 평소의 침착함 아래 감정이 보호와 관계의 선택을 강하게 움직인다.","source":"S-f215d5fe131a","supportingSources":["S-7ab1c252d917","S-219ce0b71190"]},"altruism":{"score":4,"text":"반려자를 간호하고 아도니스의 불안을 들으며 시간을 내준다. 도움은 가까운 사람을 중심으로 나타나고, 적대하는 사람에게까지 같은 다정함을 적용하지는 않는다.","source":"S-96cb07f9f25a","supportingSources":["S-219ce0b71190"]},"initiative":{"score":4,"text":"필요한 정보를 직접 모으고 동료에게 의뢰할 방향을 정한다. 작은 휴식도 칭찬을 요청하는 행동으로 만들어내며, 자신이 원하는 대우를 분명히 말한다.","source":"S-219ce0b71190","supportingSources":["S-06f88fc7d320"]},"caution":{"score":4,"text":"위험한 환경에서 상대와 사회의 눈치를 살피며 살아왔고, 보복에 앞서 길드에 미칠 영향을 고민한다. 신중함이 폭력을 꺼린다는 뜻은 아니며, 행동의 조건과 결과를 계산하는 경향으로 평가했다.","source":"S-219ce0b71190","supportingSources":["S-9b6c1cd9a44e"]},"bonds":{"score":5,"text":"아카쿠와 삶을 함께하는 관계가 선택의 중심에 있다. 이후 동료의 죽음을 슬퍼하고 새로운 가족을 받아들이며, 지키고 싶은 관계의 범위가 넓어진다.","source":"S-7ab1c252d917","supportingSources":["S-f215d5fe131a"]}},"relations":[{"name":"라이아흐 아카쿠","text":"함께 스카일라를 떠난 반려자. 보호하고 돌보는 데서 나아가 자신이 겪은 차별과 거친 생존 경험까지 나누며 대등한 동행을 요구한다.","source":"S-7ab1c252d917","characterId":"P-96ab98d2591c"},{"name":"아도니스","text":"변해가는 자신과 가족에게 버림받을 가능성을 걱정할 때 대화를 나눈 동료. 미샤는 다시 관계를 맺을 가능성과 쉬어갈 여유를 권한다.","source":"S-96cb07f9f25a","characterId":"P-6eeed2b4661f"},{"name":"모카","text":"엘라의 장례 뒤 토끼풀을 건네 위로한 동료. 미샤가 길드에서 새롭게 생긴 애착을 인정하는 순간을 함께한다.","source":"S-f215d5fe131a","characterId":"P-f400f584340f"},{"name":"하일로 조바","text":"길드 바닥에 누운 미샤와 어른의 책임을 이야기한 상대. 책임을 지면서도 응석부릴 수 있는지 묻는 일상의 대화가 남아 있다.","source":"S-06f88fc7d320","characterId":"P-f6ccefd2c259"},{"name":"아리차","text":"미샤에게 스스로를 돌아보는 태도를 칭찬해 준 동료. 미샤도 아리차가 남몰래 길드원들의 물건을 챙기는 행동을 알아보고 말한다.","source":"S-06f88fc7d320","characterId":"P-0322eff604c2"}],"scenes":[{"source":"S-9b6c1cd9a44e","text":"괴롭힘을 피해 달아난 열두 살 미샤가 아케오를 만나는 날."},{"source":"S-dce433af06f4","text":"유랑 수련과 아카쿠를 향한 마음, 인간 역시 자연의 일부라는 질문."},{"source":"S-7ab1c252d917","text":"사막의 첫 살인 뒤, 감춰졌던 차별과 외로움을 나누는 두 사람."},{"source":"S-06f88fc7d320","text":"책임지는 어른도 칭찬받고 쉬고 싶다는 길드 바닥의 작은 반항."},{"source":"S-219ce0b71190","text":"보복하려는 마음과 길드의 규칙 사이에서 동료에게 도움을 청하기로 하는 밤."},{"source":"S-f215d5fe131a","text":"엘라의 장례 뒤 길드에도 가족 같은 이들이 생겼음을 깨닫는 시간."}],"asOf":"2026-06-26","sources":["S-9b6c1cd9a44e","S-dce433af06f4","S-7ab1c252d917","S-96cb07f9f25a","S-219ce0b71190","S-f215d5fe131a","S-06f88fc7d320"]},"P-92738ae601c0":{"name":"머챈트 마이아","updatedAt":"2026-10-01","tagline":"남의 마음을 생활 속에서 돌보면서, 자신의 그리움과 흔들림도 놓아보려는 상인.","tags":["친근한","생활로 돌보는","그리움을 간직한"],"profileNote":"머챈트·마이아·마이어 표기로 등장한 동일 인물의 기록을 정리했다. 남에게 건네는 성숙한 조언뿐 아니라 무리한 거래와 전투 뒤의 두려움도 함께 반영했다. 손 떨림에 임의의 의학적 진단을 붙이지 않았다.","facts":[{"label":"생업","value":"상업지구에서 활동하며 자기 사업자금을 운용하는 상인. 쓰리스타 채권을 사는 이야기에서는 사업자금을 담보로 빌린 돈까지 투자한다.","source":"S-08395d0222da"},{"label":"가족과 과거","value":"전쟁으로 가족을 잃고 가족을 찾으며 여러 일을 했다고 진저에게 말한다. 어릴 때는 위험을 피하려 남장을 했으며, 지금은 어설픈 용맹을 새로운 가족으로 받아들인다.","source":"S-fbf4efe527ad"},{"label":"길드 업무","value":"스텔라가 휴가로 자리를 비운 동안 부길드장 직무를 대행했다. 익숙하지 않은 서류를 처리하고 폴라리스의 휴가 신청을 받는다.","source":"S-27c0a9d1c80d"},{"label":"손재주와 생활","value":"실과 바늘을 가지고 다니며 아도니스의 돌고래 인형을 꿰매준다. 물건을 고치는 일에 기억과 관계의 의미를 담아 이야기한다.","source":"S-6e662f70b831"},{"label":"생일","value":"션에게 생일 선물로 금연 파이프를 건네며 자신의 생일은 10월 17일이라고 말한다.","source":"S-a4eb77cbe063"},{"label":"전투 이후","value":"하마이잔의 트롤 전투 뒤 피아노를 칠 때 손끝이 떨린다. 의사를 찾아가야겠다고 이야기하면서도 일하러 돌아간다.","source":"S-37c38d208e0e"}],"evaluation":[{"title":"상대가 지금 할 수 있는 일부터 돕다","text":"편지를 못 쓰는 하일로에게 멋진 작품을 쓰려 하지 말고 눈앞의 풍경과 마음부터 적어보라고 한다. 감정을 대신 규정하기보다 본인의 말로 표현할 발판을 마련한다. 장난스러운 놀림과 실질적인 도움이 한 대화 안에서 자연스럽게 이어진다.","source":"S-58aa7a9520f8"},{"title":"배려를 물건으로 건네는 사람","text":"몸이 달라진 티아멧에게 속옷과 리넨을 챙겨주며 당황할 수 있는 생활의 변화를 설명한다. 상대를 구경거리로 삼기보다 실제로 필요한 준비를 떠올리고, 자기답게 지내기를 바란다. 머챈트의 다정함에는 생활을 직접 겪어본 사람의 구체성이 있다.","source":"S-9f8ed85097f2"},{"title":"현명한 조언과 흔들리는 자기 판단","text":"다른 사람의 고민에는 차분하게 조언하지만, 자신의 채권 가격이 떨어지자 더 싸게 살 기회라며 빚을 늘린다. 유능한 상인이라는 인상이 모든 판단의 안전을 보장하지는 않는다. 이 과장된 소동은 기대와 불안을 다루는 데에는 그 역시 허술할 수 있음을 드러낸다.","source":"S-08395d0222da"},{"title":"수선하면서 기억을 붙잡다","text":"처음에는 낡은 인형을 보내주라고 하지만 아도니스의 반응을 보고 직접 고쳐주기로 한다. 이름이 기억을 붙잡는다는 이야기는 추상적인 설교가 아니라 한 땀씩 인형을 꿰매는 행동과 함께 나온다. 자신의 첫 판단보다 상대에게 그 물건이 무엇인지를 다시 살피는 태도가 좋다.","source":"S-6e662f70b831"},{"title":"어른이어도 이별의 답은 모른다","text":"옛 연인의 편지를 태우려다가 미련의 주체가 자신인지 편지인지 고민한다. 어른이란 정답을 아는 사람이 아니라 흔들리며 덜 후회하려 애쓰는 사람이라고 이야기한다. 결국 아이다와 달리며 편지를 바람에 놓는 결말은 그리움을 부정하기보다 작별하는 방식을 스스로 찾는 장면이다.","source":"S-d5d8afd68213"}],"traits":{"social":{"score":5,"text":"먼저 술병을 들고 다가가 농담을 나누거나 막힌 대화에 말을 보탠다. 진저의 과거를 듣고 자신의 경험도 털어놓아 서로 이야기할 수 있는 자리를 만든다.","source":"S-fbf4efe527ad","supportingSources":["S-58aa7a9520f8"]},"emotion":{"score":4,"text":"동료의 출발을 떠올리며 쓸쓸해하고 옛 편지를 쉽게 버리지 못한다. 투자에서는 기대와 불안이 크게 표출되는 등, 감정이 대화와 행동에 분명히 드러난다.","source":"S-d5d8afd68213","supportingSources":["S-75e8e522e6c7","S-08395d0222da"]},"altruism":{"score":4,"text":"인형을 수선하고 필요한 생활용품을 건네며 상대의 표현을 돕는다. 자신의 기술과 시간을 쓰는 반복적인 돌봄이 확인된다.","source":"S-6e662f70b831","supportingSources":["S-9f8ed85097f2","S-58aa7a9520f8"]},"initiative":{"score":4,"text":"필요한 도움을 먼저 제안하고, 낯선 부길드장 대직 업무도 맡아 처리한다. 감정의 정리가 어려운 순간에도 마지막에는 직접 작별의 행동을 택한다.","source":"S-27c0a9d1c80d","supportingSources":["S-d5d8afd68213","S-6e662f70b831"]},"caution":{"score":3,"text":"상대의 생활에서 생길 문제는 미리 챙기지만 자기 투자에서는 소문과 기대에 기대어 위험을 늘린다. 상황에 따라 신중함의 차이가 뚜렷해 하나의 높은 점수로 묶지 않았다.","source":"S-08395d0222da","supportingSources":["S-9f8ed85097f2"]},"bonds":{"score":5,"text":"잃어버린 가족의 빈자리에 길드라는 가족을 받아들이고, 떠나는 동료와 옛 연인을 오래 생각한다. 서로의 이름을 기억하겠다는 약속과 생일 선물에도 관계를 이어가려는 마음이 나타난다.","source":"S-fbf4efe527ad","supportingSources":["S-6e662f70b831","S-d5d8afd68213","S-a4eb77cbe063"]}},"relations":[{"name":"진저브레이브","text":"전쟁과 가족을 잃은 과거를 서로 털어놓은 동료. 농담으로 시작한 모닥불 대화가 새 가족을 받아들였다는 고백으로 이어진다.","source":"S-fbf4efe527ad","characterId":"P-11b5c9c4a5f1"},{"name":"폴라리스","text":"처음 만난 때를 기억하며 휴가 신청을 받는 친구. 대직 중인 머챈트의 책임과 반가움이 함께 드러나는 상대다.","source":"S-27c0a9d1c80d","characterId":"P-5d0c306440d0"},{"name":"하일로 조바","text":"마리아에게 쓸 편지를 어려워할 때 조언한 동료. 거창한 표현보다 지금의 마음을 자기 말로 쓰게 돕는다.","source":"S-58aa7a9520f8","characterId":"P-f6ccefd2c259"},{"name":"티아멧","text":"달라진 몸으로 생활하는 데 필요한 물건과 조언을 건넨 동료. 그 변화 속에서도 자기답게 지내기를 바란다.","source":"S-9f8ed85097f2","characterId":"P-22fdf8486544"},{"name":"아도니스","text":"돌고래 인형을 고쳐주며 서로 이름을 기억하자고 약속한 동료. 작은 물건에 담긴 애착을 존중한다.","source":"S-6e662f70b831","characterId":"P-6eeed2b4661f"},{"name":"스나가와 아이다","text":"이별과 어른의 책임을 이야기하다 함께 숲으로 달린 동료. 편지를 놓아주는 순간을 함께한다.","source":"S-d5d8afd68213","characterId":"P-4a533e2105f8"}],"scenes":[{"source":"S-fbf4efe527ad","text":"진저에게 가족을 잃은 과거와 새 가족이 된 길드를 말하는 모닥불."},{"source":"S-58aa7a9520f8","text":"잘 쓴 작품 대신 마음이 전해지는 편지를 쓰도록 돕는 대화."},{"source":"S-9f8ed85097f2","text":"티아멧에게 생활용품과 자기답게 살아가라는 말을 건네는 빨래터."},{"source":"S-08395d0222da","text":"떨어지는 채권을 할인으로 받아들이며 돈을 더 거는 소동."},{"source":"S-6e662f70b831","text":"돌고래 인형 맥시를 꿰매며 이름과 기억을 이야기하는 시간."},{"source":"S-d5d8afd68213","text":"옛 편지를 태우려던 밤, 아이다와 달리며 바람에 보내는 작별."}],"asOf":"2026-09-07","sources":["S-08395d0222da","S-fbf4efe527ad","S-27c0a9d1c80d","S-6e662f70b831","S-a4eb77cbe063","S-37c38d208e0e","S-58aa7a9520f8","S-9f8ed85097f2","S-d5d8afd68213","S-75e8e522e6c7"]},"P-4a533e2105f8":{"name":"스나가와 아이다","updatedAt":"2026-10-01","tagline":"죽음을 가볍게 뒤집는 세계에 반발하면서도, 살아 있는 동료들과 자신의 이야기를 만드는 소녀.","tags":["죽음을 깊이 생각하는","탐구적인","관계를 배워가는"],"profileNote":"아이다와 스나가와 아이다는 같은 인물이다. 초기의 격한 부활 거부와 이후의 철학적 질문을 모두 담았다. 유령화 능력과 유령이라는 별명을 실제 사망이나 언데드 종족으로 단정하지 않았다.","facts":[{"label":"입회 무렵","value":"돌아가신 어머니에게 쓴 첫 편지에서 열일곱이라고 밝힌다. 어머니의 무덤을 가꾸던 생활을 떠나 길드에 들어왔으며, 사람과 이야기하거나 편지를 쓰는 일이 아직 낯설다고 말한다.","source":"S-fb18ba8397d3"},{"label":"유령화","value":"몸을 투명하게 하거나 물체를 통과하는 모습을 보인다. 다락방 이야기의 서술은 실제 유령은 아니라고 구분한다.","source":"S-ba459d7cb73a"},{"label":"무기","value":"삽을 무기로 사용한다. 처음에는 먹고살기 위해 들었지만 이후 임무를 위해 휘둘렀다고 돌아보며, 새 삽을 어떤 용도로 쓸지 고민한다.","source":"S-e6786249352d"},{"label":"흑주술에 대한 관심","value":"배블스에게 어떤 존재에게 힘을 받았는지, 어떤 계기로 흑마법을 쓰게 됐는지 묻는다. 모호한 답에도 탐구하고 싶다며 질문을 이어간다.","source":"S-ba7d88a56d6f"},{"label":"조사와 공부","value":"도리안의 후견자에 관한 정보를 찾으려고 책과 자료를 뒤진다. 성과가 없자 본가에 편지를 쓰는 다른 접근을 택한다.","source":"S-399dbb7649db"},{"label":"일상의 연습","value":"케이크 만들기에 실패한 뒤 몰래 요리를 연습하고, 직접 만든 초콜릿을 누군가에게 전한다. 받은 사람이 누구인지는 기록에 공개되지 않는다.","source":"S-403d34a88c18"}],"evaluation":[{"title":"부활을 미워하는 마음의 출발점","text":"진저가 돌아오자 자신이 묻은 이들도 누군가에게 소중했다는 생각에 분노한다. 어머니는 돌아오지 않았는데 다른 사람에게는 기적이 허락되었다는 불공평함이 실제 공격으로 이어진다. 상실을 이해하는 것과 그 공격을 정당화하는 것은 별개이며, 이 장면은 아이다가 그 감정을 위험하게 표출한 초기의 모습을 보여준다.","source":"S-ea2ae8e0f6a1"},{"title":"분노가 사라지지 않은 채 질문은 깊어진다","text":"마리아가 되살아난 뒤에는 돌아온 존재가 같은 이름을 이어받아도 되는지, 기억으로 달라진 이야기가 원래의 사람인지 묻는다. 어머니가 돌아와도 같은 질문이 남는다고 생각한다. 부활을 쉽게 받아들이게 됐다고 정리할 수는 없지만, 반감에 정체성과 기억의 문제가 더해지는 변화가 있다.","source":"S-66fd5ba99930"},{"title":"자신과 닮은 고립을 알아보다","text":"다락방의 데이지에게 장난을 걸다가 빵만 먹고 숨어 지낸다는 사정을 듣고 함께 먹고 운동하자고 권한다. 자신의 길드 생활에서 배운 것을 다른 사람에게 돌려주는 모습이다. 다소 짓궂게 밖으로 끌어내려 하면서도 마지막에는 안아도 되는지 묻고 친구가 생긴 것을 기뻐한다.","source":"S-ba459d7cb73a"},{"title":"모르는 것을 그냥 두기 어렵다","text":"흑마법의 힘을 어디서 얻는지 따져 묻고, 단서가 부족한 후견자 조사에서도 다른 경로를 찾는다. 탐구에는 순수한 호기심과 자신에게 일어나는 일을 이해하려는 욕구가 함께 있다. 다만 가설을 말하거나 편지를 쓰는 단계가 곧 수수께끼의 해결을 뜻하지는 않는다.","source":"S-399dbb7649db"},{"title":"혼자였던 인물이 동료에게 느끼는 고마움","text":"입회 초기에는 사람들과 말을 섞는 것도 낯설다고 했지만, 별을 보며 누군가와 만났기 때문에 이야기가 생긴다고 생각하게 된다. 동료들에게 고마움을 전하고 싶다는 독백은 모든 갈등을 극복했다는 결말이 아니다. 그럼에도 현재의 길드 생활을 좋아하고, 관계 속의 자신을 상상하게 된 변화는 분명하다.","source":"S-0041a65e4a82"}],"traits":{"social":{"score":3,"text":"처음에는 말을 섞는 일이 낯설다고 하지만 데이지를 찾아가 이름을 묻고 함께 외출하자고 권한다. 적극적인 장난과 낯가림이 함께 남아 있는, 배워가는 사교성으로 보았다.","source":"S-ba459d7cb73a","supportingSources":["S-fb18ba8397d3"]},"emotion":{"score":5,"text":"어머니를 잃은 마음과 부활의 불공평함이 공격적인 행동까지 이끌며, 이후에도 죽음과 기억을 생각하는 중심에 그리움이 있다. 겉으로 담담한 독백에서도 감정의 영향이 크다.","source":"S-ea2ae8e0f6a1","supportingSources":["S-66fd5ba99930"]},"altruism":{"score":3,"text":"데이지의 식사와 건강을 챙기고 다른 사람을 위해 요리를 연습한다. 동시에 진저에게는 자신의 상처에서 나온 적대감을 가하므로, 가까운 이에게 보이는 배려를 보편적인 헌신으로 넓히지 않았다.","source":"S-ba459d7cb73a","supportingSources":["S-403d34a88c18","S-ea2ae8e0f6a1"]},"initiative":{"score":4,"text":"소문을 직접 확인하러 가고 흑주술의 단서를 조사한다. 원하는 무기를 찾거나 편지를 쓰는 등 궁금증과 필요를 실제 행동으로 옮긴다.","source":"S-399dbb7649db","supportingSources":["S-e6786249352d","S-ba459d7cb73a"]},"caution":{"score":3,"text":"정보가 부족할 때는 질문하고 조사 경로를 바꾸지만, 죽음과 관련된 감정 앞에서는 위험한 행동에 나서기도 한다. 학구적인 생각의 깊이와 행동의 신중함을 같은 것으로 보지는 않았다.","source":"S-ba7d88a56d6f","supportingSources":["S-399dbb7649db","S-ea2ae8e0f6a1"]},"bonds":{"score":4,"text":"어머니를 계속 기억하고 자신의 삶을 그 기억과 연결한다. 이후에는 친구를 사귀고 동료 덕분에 자기 이야기가 생겼다고 느끼며, 길드라는 현재의 관계에도 애착을 갖는다.","source":"S-0041a65e4a82","supportingSources":["S-fb18ba8397d3","S-ba459d7cb73a","S-056353a983bb"]}},"relations":[{"name":"진저브레이브","text":"부활을 받아들이지 못해 공격했던 동료. 아이다의 상실감이 다른 사람과의 갈등으로 드러나는 관계다. 이 사건만으로 이후의 화해까지 단정하지 않았다.","source":"S-ea2ae8e0f6a1","characterId":"P-11b5c9c4a5f1"},{"name":"데이지","text":"다락방에서 찾아낸 뒤 함께 먹고 밖에 나가자고 권한 친구. 고립된 모습을 자신의 예전 모습과 겹쳐 보며 다가간다.","source":"S-ba459d7cb73a","characterId":"P-dec9a5f1b430"},{"name":"코블스톤 크리처 라티오","text":"묘지기의 삽과 나침반을 가공해 아이다의 무기를 만들어 준 동료. 사용하는 도구를 바꾸는 여정의 마지막에 도움을 받는다.","source":"S-0a30de2e6979","characterId":"P-b3929f308454"},{"name":"토르번 팔켄하인","text":"도리안의 죽음과 흑주술에 관해 면담한 동료. 확정되지 않은 가설과 남아 있는 단서를 주고받는다.","source":"S-9fd59966de6c","characterId":"P-7ba611cf90be"},{"name":"머챈트 마이아","text":"그리움과 작별을 이야기하고 함께 숲으로 달린 동료. 머챈트가 옛 편지를 놓아주는 밤을 함께한다.","source":"S-d5d8afd68213","characterId":"P-92738ae601c0"}],"scenes":[{"source":"S-fb18ba8397d3","text":"무덤을 떠나 길드에 들어온 열일곱 아이다가 어머니에게 쓰는 첫 편지."},{"source":"S-ea2ae8e0f6a1","text":"진저의 부활을 받아들이지 못해 삽을 휘두르고 중재를 받는 충돌."},{"source":"S-ba459d7cb73a","text":"다락방의 데이지에게 함께 먹고 운동하자고 권하며 친구가 되는 밤."},{"source":"S-e6786249352d","text":"앞으로 삽을 어떻게 쓸지 생각하며 특별한 무기를 찾는 여정."},{"source":"S-0041a65e4a82","text":"별을 보며 만남이 이야기를 만든다고 생각하고 동료에게 고마워하는 독백."},{"source":"S-66fd5ba99930","text":"되살아난 마리아를 계기로 이름과 기억, 돌아온 사람의 정체성을 묻는 독백."}],"asOf":"2026-09-07","sources":["S-fb18ba8397d3","S-ba459d7cb73a","S-e6786249352d","S-ba7d88a56d6f","S-399dbb7649db","S-403d34a88c18","S-ea2ae8e0f6a1","S-66fd5ba99930","S-0041a65e4a82","S-056353a983bb","S-0a30de2e6979","S-9fd59966de6c","S-d5d8afd68213"]},"P-1ba0b80ec424":{"name":"피에르","updatedAt":"2026-10-01","tagline":"검과 농사에는 익숙하지만 마음을 전하는 일은 서툴러, 동료의 도움으로 한 걸음씩 다가가는 사람.","tags":["순박한","몸으로 실천하는","배움을 시작하는"],"profileNote":"피에르 본인의 행동과 같은 프로필이 맡은 탐정·진행자 등의 역할을 구분했다. 아카쿠와의 첫 만남은 과거 회상이며, 클로에에게 청혼한 기록을 이미 혼례를 마친 상태로 확대하지 않았다.","facts":[{"label":"출신과 이름","value":"스스로 농부라 성이 없다고 소개한다. 부모가 병으로 세상을 떠난 뒤 집과 농지를 잃고 마을을 나와 모험가로 지냈다고 아카쿠에게 이야기한다.","source":"S-113d7bcc34db"},{"label":"검술","value":"재능을 알아본 스승에게 검술을 배웠다고 말한다. 아카쿠와 처음 만난 회상에서는 곰과 싸워 그를 돕고 숲에서 나가는 길을 안내한다.","source":"S-113d7bcc34db"},{"label":"농사와 약초","value":"길드의 밭을 가꾸며 작물과 약초를 구분할 줄 안다. 무를 잡초로 알고 뽑은 모카에게 식물의 차이를 가르친다.","source":"S-b41edec9d71f"},{"label":"글공부","value":"고백 편지를 준비하던 시점에는 글을 읽고 쓰기 어려워 동료들의 도움을 받는다. 다음에는 자기 힘으로 마음을 전할 수 있는 사람이 되고 싶다고 적는다.","source":"S-bfa01050bc9b"},{"label":"클로에와의 관계","value":"깨뜨린 삽을 새로 선물하며 가까워지고, 이후 직접 찾아가 청혼한다. 마음을 받아들인 클로에와 서로를 더 알아가기로 하는 연인 관계로 이어진다.","source":"S-bfa01050bc9b"},{"label":"두려워하는 것","value":"검으로 벨 수 없는 귀신을 특히 두려워한다. 오드리와 밤 숲에 갇힌 사건에서 공포와 혼란을 겪고, 오드리의 도끼에 다친 채 남는다.","source":"S-004cdeda48f4"}],"evaluation":[{"title":"서툰 말투와 실제 능력은 다르다","text":"낯선 종족과 사회의 말에는 익숙하지 않아도 곰의 약점을 알고 싸우며 숲길을 안내한다. 농사와 약초도 자신의 경험으로 다룬다. 피에르의 무지는 모든 분야에 걸친 무능함이 아니라 교육과 경험의 편차로 읽는 것이 정확하다.","source":"S-113d7bcc34db"},{"title":"미안함을 손에 잡히는 선물로 갚다","text":"클로에의 삽을 깨뜨린 일을 잊지 않고 새 삽에 리본을 묶어 찾아간다. 빚은 갚아야 한다는 어머니의 말을 떠올리는 동시에 좋아하는 사람을 만날 구실도 찾는다. 책임감과 설렘이 함께 담긴, 피에르다운 실용적인 선물이다.","source":"S-c6b374fa5d44"},{"title":"도움을 받는 사람에서 스스로 전하는 사람으로","text":"길드원들에게 편지 작성을 맡기면서도 이상한 내용이 들어가지 않는지 확인해 달라고 한다. 결국 자기 마음을 자기 힘으로 전하고 싶다는 바람을 적고 직접 클로에를 찾아간다. 글공부의 필요성이 체면이 아니라 관계를 위해 해주고 싶은 일에서 생긴다는 점이 인상적이다.","source":"S-bfa01050bc9b"},{"title":"무서워도 옆 사람을 먼저 붙잡는 순간","text":"밤 숲에서는 자신이 무너지면 오드리도 무너질 것이라 생각하고 용기를 낸다. 호숫가로 향하는 오드리를 막고 앞장서지만, 이후에는 본인도 공포에 압도된다. 용기는 두려움이 없거나 끝까지 혼자 해결한다는 뜻이 아니라, 무서운 중에도 잠시 타인을 붙드는 행동으로 나타난다.","source":"S-004cdeda48f4"},{"title":"배우는 사람도 가르칠 것은 있다","text":"모카가 밭을 망가뜨리자 크게 화를 내고 끌고 가서 식물을 가르친다. 분명 친절하기만 한 수업은 아니지만, 자기 경험을 전달할 수 있다는 자신감은 뚜렷하다. 글을 모른다는 한 특징만으로 피에르를 늘 가르침을 받는 위치에 두어서는 안 되는 이유다.","source":"S-b41edec9d71f"}],"traits":{"social":{"score":4,"text":"처음 만난 아카쿠의 손을 잡고 함께 식사하며 자기 이야기를 나눈다. 길드에서도 먼저 인사를 건네지만 연애 감정이 앞서는 상대에게는 크게 긴장한다.","source":"S-113d7bcc34db","supportingSources":["S-c6b374fa5d44"]},"emotion":{"score":4,"text":"밭이 망가졌을 때의 분노, 클로에 앞에서의 설렘, 밤 숲의 두려움이 몸과 말에 그대로 나타난다. 감정을 잘 감추는 인물은 아니다.","source":"S-c6b374fa5d44","supportingSources":["S-b41edec9d71f","S-004cdeda48f4"]},"altruism":{"score":4,"text":"위험에 처한 아카쿠를 돕고 길을 안내하며, 자신도 무서운 상황에서 오드리의 안전을 생각한다. 대단한 선언보다는 바로 곁에 있는 사람을 돕는 행동이 근거다.","source":"S-113d7bcc34db","supportingSources":["S-004cdeda48f4"]},"initiative":{"score":4,"text":"새 삽을 준비해 찾아가고 마지막에는 직접 고백한다. 낯선 일에는 도움을 받지만, 필요한 행동까지 다른 사람에게 모두 맡기지는 않는다.","source":"S-bfa01050bc9b","supportingSources":["S-c6b374fa5d44"]},"caution":{"score":3,"text":"경험이 있는 싸움과 숲에서는 위험을 알아차리지만 사회적 거래와 낯선 상황에는 판단이 흔들린다. 편지 내용을 다른 동료에게 확인해 달라고 하는 등 모르는 부분을 보완하려는 행동도 있다.","source":"S-bfa01050bc9b","supportingSources":["S-113d7bcc34db","S-004cdeda48f4"]},"bonds":{"score":4,"text":"어머니의 가르침을 기억하고, 클로에에게 더 많은 것을 해줄 수 있는 사람이 되고자 한다. 동료들의 도움을 떠올려 고백할 용기를 얻는 모습에서도 관계가 행동을 뒷받침한다.","source":"S-bfa01050bc9b","supportingSources":["S-c6b374fa5d44"]}},"relations":[{"name":"클로에","text":"농사와 약초, 선물과 대화를 통해 가까워진 연인. 자기 힘으로 마음을 전하고 싶다는 변화의 중요한 계기가 된다.","source":"S-bfa01050bc9b","characterId":"P-ad57d7b4ca68"},{"name":"라이아흐 아카쿠","text":"과거 숲에서 곰에게 쫓기던 것을 도운 인연. 이후 식사를 함께하며 부모와 고향, 모험가 생활을 이야기한다.","source":"S-113d7bcc34db","characterId":"P-96ab98d2591c"},{"name":"모카","text":"작물을 잡초로 잘못 뽑아 식물 공부를 시킨 상대. 갈등과 교육이 유쾌하면서도 거칠게 겹치는 일상이다.","source":"S-b41edec9d71f","characterId":"P-f400f584340f"},{"name":"오드리","text":"밤 숲의 공포 속에서 서로 의지한 동료. 피에르가 위험을 막아주다가 나중에는 자신도 무너지며, 서로를 위협으로 오인할 만큼 상황이 뒤틀린다.","source":"S-004cdeda48f4","characterId":"P-59654965b99f"},{"name":"존 (마법사)","text":"글을 배우고 직접 마음을 전하도록 조언한 동료. 이 장면의 존은 탐정 존 마커스와 별개다.","source":"S-bfa01050bc9b","characterId":"P-79263e0865dd"},{"name":"핀 머독","text":"편지를 준비하는 모닥불에서 조언한 선배. 다른 동료들과 함께 피에르에게 자신감을 보탠다.","source":"S-bfa01050bc9b","characterId":"P-87b04eb56606"}],"scenes":[{"source":"S-113d7bcc34db","text":"아카쿠를 돕고 고향과 부모, 모험가 생활을 이야기하는 첫 만남의 회상."},{"source":"S-b41edec9d71f","text":"망가진 무밭 앞의 분노가 모카의 식물 공부로 이어지는 소동."},{"source":"S-c6b374fa5d44","text":"리본을 묶은 삽을 선물하고 클로에에게 사랑이 무엇인지 묻는 방문."},{"source":"S-bfa01050bc9b","text":"길드원들의 편지 조언 끝에 직접 마음을 전하고 클로에의 응답을 받는 날."},{"source":"S-004cdeda48f4","text":"용기를 내어 오드리를 돕다가 자신도 공포에 휩싸이는 밤 숲."},{"source":"S-4883e8639520","text":"거베라와 오목을 두며 마법 상추를 심어보자고 이야기하는 일상."}],"asOf":"2026-09-06","sources":["S-113d7bcc34db","S-b41edec9d71f","S-bfa01050bc9b","S-004cdeda48f4","S-c6b374fa5d44","S-4883e8639520"]},"P-5c88d36f51cd":{"name":"숀","updatedAt":"2026-10-01","tagline":"툴툴거리며 거리를 두어도, 동료를 잃는 일을 누구보다 무겁게 받아들이는 작은 검객.","tags":["직설적인","경험으로 가르치는","상실에 민감한"],"profileNote":"숀 사우스풋·숀 사우스 풋·숀 카리엔으로 등장하는 쥐 데미간이다. 인간 검객 션(샤르니르), 별도 캐릭터 카리엔과 합치지 않았다. 마우스가드 시절 이야기는 입회 전의 회상이며 바키르의 죽음은 이 대화 시점에는 확인되지 않은 소문이다.","facts":[{"label":"종족과 이전 소속","value":"쥐 데미간. 어설픈 용맹에 오기 전 마을의 파발대인 마우스가드에서 일했으며, 사자회와 함께 임무를 수행한 경험을 말한다.","source":"S-30114b2c856b"},{"label":"과거의 작별","value":"마우스가드 마지막 임무를 다룬 회상에서 동료들과 폭포를 탈출한다. 함께 출발했던 열둘 중 다섯이 남은 상황에서 은퇴를 선언하고 남은 이들과 서로를 끌어안는다.","source":"S-0ca4cf109c61"},{"label":"길드에 남은 이유","value":"스텔라의 부탁으로 길드원들에게 검을 쥐는 법을 가르치게 됐다고 말한다. 새 동료들의 태도와 실제 전장에서 믿고 싸울 수 있는지를 심각하게 고민한다.","source":"S-30114b2c856b"},{"label":"검술 지도","value":"하일로에게 힘을 빼고 검을 잡는 법, 팔꿈치와 손의 움직임을 가르친다. 낚싯줄을 던지거나 주먹을 쥐는 감각으로 설명하며 몸에 익힐 것을 요구한다.","source":"S-c61348f1a184"},{"label":"일상","value":"숲에 간식을 따로 보관해 두는 장소가 있다. 그곳에서 만난 마리우스의 불안을 듣고, 음식처럼 감정도 쌓아두지 말고 나누라는 말을 건넨다.","source":"S-08db8164bc36"},{"label":"동료 수색","value":"티아멧을 찾기 위해 장비를 갖추고 서쪽으로 떠난다. 피에르에게 행선지와 돌아오겠다는 말을 편지로 남긴다.","source":"S-434fbd22f1a8"}],"evaluation":[{"title":"신뢰를 말하기 전에 생존을 떠올린다","text":"마우스가드 회상에서는 동료의 목숨을 운에 맡기기 싫어 돌파구를 찾고, 결국 자신도 동료의 도움으로 살아난다. 이런 경험을 지닌 숀에게 등을 맡긴다는 말은 가벼운 친목의 표현이 아니다. 길드원들과 전장에 설 자신이 없다는 불만에는 실제 상실에 대한 두려움이 함께 있다.","source":"S-30114b2c856b"},{"title":"거친 말 사이에 생기는 상담의 자리","text":"간식을 숨긴 것이 들켜 당황하면서도 마리우스가 울었다는 것을 알아본다. 션과 자신을 비교하는 조급함을 짚고, 꿈과 남의 말만으로 불안해야 하는 것은 아니라고 말한다. 놀림과 오해도 많지만 결국 상대가 말할 자리를 비워주는 것이 이 대화의 핵심이다.","source":"S-08db8164bc36"},{"title":"남에게 했던 조언이 자신에게는 무겁다","text":"마리우스에게 감정을 털어내라고 말했던 숀은 헬리오스가 떠난 대장간 앞에서 그 말이 쉽지 않음을 느낀다. 먼지를 닦고 다시 오겠다고 하는 작은 행동에는 쉽게 보내지 못하는 마음이 남는다. 조언이 능숙하다고 이별까지 능숙한 인물은 아니다.","source":"S-4db98fd3c08f"},{"title":"쓴소리 끝에 상대의 선택을 남겨둔다","text":"루체에게 칭찬만 듣는 위험을 이야기하지만 무엇을 믿어야 하는지를 대신 정하지는 않는다. 신을 믿는다면 그 선택을 하는 자신도 믿으라고 권한다. 말투는 거칠어도 상대가 자기 판단을 지닐 수 있기를 바라는 가르침이다.","source":"S-83428fdbf92c"},{"title":"도망친 뒤에도 살아갈 방향은 남아 있다","text":"이별 편지를 받고 폴라리스와 이야기하면서 도망치는 일을 무조건 나쁘다고 보지 않는다. 더 잘 살아보려는 반응일 수 있지만 결국 자신에게서 달아날 수는 없다고 말한다. 남을 위로하며 자기 상황도 함께 인정하는 점에서, 숀의 조언은 완성된 정답보다 경험 중인 사람의 말에 가깝다.","source":"S-86aad3711659"}],"traits":{"social":{"score":3,"text":"사람들과 농담하고 고민도 듣지만 지나치게 가까운 관계와 무분별한 말에 피로를 느낀다. 누구에게나 쉽게 곁을 내주기보다 상대와 상황을 고른다.","source":"S-30114b2c856b","supportingSources":["S-08db8164bc36"]},"emotion":{"score":4,"text":"화가 나 길드를 나가고, 떠난 친구의 대장간에서 그리움을 느끼며 이별 편지 앞에서는 괜한 욕도 한다. 무심한 말투와 달리 상실과 불안이 행동에 강하게 드러난다.","source":"S-4db98fd3c08f","supportingSources":["S-30114b2c856b","S-86aad3711659"]},"altruism":{"score":4,"text":"배우겠다는 하일로를 가르치고 울던 마리우스의 이야기를 듣는다. 동료를 찾으러 직접 떠나는 수고도 감수하지만 모든 신입을 무조건 받아주는 태도는 아니다.","source":"S-c61348f1a184","supportingSources":["S-08db8164bc36","S-434fbd22f1a8"]},"initiative":{"score":4,"text":"위기에서 탈출할 방법을 찾고, 검술 수업과 동료 수색을 실제 행동으로 옮긴다. 불만이 쌓이면 직접 자리를 떠나는 등 경계를 정하는 행동도 분명하다.","source":"S-0ca4cf109c61","supportingSources":["S-434fbd22f1a8","S-30114b2c856b"]},"caution":{"score":4,"text":"동료를 운에 맡기지 않으려 하고 전장에서 믿을 수 있는지를 따진다. 바키르에 관한 소문도 확실하지 않으니 퍼뜨리지 말라고 한다. 다만 화가 난 순간의 언행에는 날카로움이 남는다.","source":"S-30114b2c856b","supportingSources":["S-0ca4cf109c61"]},"bonds":{"score":5,"text":"옛 동료의 이름을 기억하고 빈 대장간을 다시 찾으며 티아멧 수색에 나선다. 친밀함이 불편하다고 말하면서도 이미 맺은 인연이 현재의 선택을 크게 움직인다.","source":"S-4db98fd3c08f","supportingSources":["S-0ca4cf109c61","S-434fbd22f1a8"]}},"relations":[{"name":"션","text":"길드를 떠나려는 숀을 따라와 이야기를 들은 인간 검객. 교육과 책임, 동료에게 등을 맡길 믿음을 두고 솔직하게 다툼과 걱정을 나눈다.","source":"S-30114b2c856b","characterId":"P-3bbc4a823df9"},{"name":"마리우스","text":"헬리오스에게 딸 같은 존재이므로 자신에게도 그와 같다고 말한 동료. 숲의 간식 창고에서 연애와 수련의 불안을 듣는다.","source":"S-08db8164bc36","characterId":"P-b6d81d634c6e"},{"name":"루체 루멘","text":"재능을 경계하면서도 자신을 믿는 법을 말해준 어린 동료. 무조건적인 칭찬과 스스로 고른 믿음의 차이를 설명한다.","source":"S-83428fdbf92c","characterId":"P-d8e7afee7c51"},{"name":"하일로 조바","text":"검술을 가르친 동료. 손과 팔의 움직임을 구체적으로 교정하고 반복해서 감각을 익히게 한다.","source":"S-c61348f1a184","characterId":"P-f6ccefd2c259"},{"name":"폴라리스","text":"각자의 연애와 거절, 도망친 이후의 방향을 나눈 친구. 남의 선택을 인정하면서 자기 이별도 털어놓는다.","source":"S-86aad3711659","characterId":"P-5d0c306440d0"},{"name":"린 (길드원)","text":"티아멧 수색길에서 명예와 상실을 이야기한 동료. 아카쿠가 뒤처지면 도와달라고 부탁한다.","source":"S-2c8f392dc137","characterId":"P-deff0d294482"}],"scenes":[{"source":"S-0ca4cf109c61","text":"마우스가드 시절의 폭포 탈출과 은퇴, 동료들의 이름을 남기는 작별."},{"source":"S-08db8164bc36","text":"숨겨둔 간식과 쌓아둔 감정을 나누는 마리우스와의 새벽 대화."},{"source":"S-4db98fd3c08f","text":"헬리오스 없는 대장간에서 조언의 무게를 되돌려 받는 밤."},{"source":"S-83428fdbf92c","text":"루체에게 자기 선택을 믿을 힘을 갖추라고 말하는 훈련장."},{"source":"S-30114b2c856b","text":"화를 내고 길드를 나선 뒤 션에게 불신과 바키르의 소문을 털어놓는 시간."},{"source":"S-434fbd22f1a8","text":"피에르에게 편지를 남기고 티아멧을 찾으러 출발하는 날."}],"asOf":"2026-09-13","sources":["S-30114b2c856b","S-0ca4cf109c61","S-c61348f1a184","S-08db8164bc36","S-434fbd22f1a8","S-4db98fd3c08f","S-83428fdbf92c","S-86aad3711659","S-2c8f392dc137"]},"P-87b04eb56606":{"name":"핀 머독","updatedAt":"2026-10-01","tagline":"큰 웃음과 튼튼한 몸으로 사람을 돕고, 웃음 뒤의 상실도 함께 품고 사는 동료.","tags":["호탕한","행동으로 돕는","상실을 품은"],"profileNote":"머독의 직접 행동과 회상을 중심으로 정리했다. 본인이 말하는 마법 솥과 장수 이야기는 발언의 맥락을 남겼고, 웃긴 장면을 모두 너그러운 배려로 포장하지 않았다.","facts":[{"label":"이름과 나이","value":"핀 머독. 흰 코털을 발견하는 7월의 장면에서 마흔한 살로 소개된다.","source":"S-56bb874bb8ba"},{"label":"힘과 성장","value":"어렸을 때 마법 솥에 빠진 뒤 힘이 달라졌다는 은사의 설명을 전한다. 특별한 운동 없이도 힘이 좋아 짐꾼으로 일하고 싸우며 자랐다고 회상한다.","source":"S-56bb874bb8ba"},{"label":"전투 방식","value":"주로 맨손으로 싸우지만 의자나 책상도 필요에 따라 쓴다고 말한다. 싸움에서는 거리와 상대의 발, 호흡을 살피며 등을 맡길 동료를 중요하게 여긴다.","source":"S-2ea37fcffe10"},{"label":"은사","value":"사잔을 삼백 년 넘게 살아온 인간 드루이드인 은사로 소개한다. 자신에게 마법 솥 이야기를 해주었던 스승이다.","source":"S-56bb874bb8ba"},{"label":"보육원","value":"은사가 마련한 숲의 보육원을 자주 찾아가, 차별로 바깥 생활이 어려운 아이들과 시간을 보낸다.","source":"S-081f7fb3f726"},{"label":"딸의 기억","value":"같은 보육원에서 자신의 딸도 길렀다고 미샤에게 말한다. 딸에게 있었던 병을 회상하며, 아이에게 사랑을 전하던 말을 들려준다.","source":"S-081f7fb3f726"},{"label":"혼인 서약의 증인","value":"피를 흘리며 돌아온 하일로 곁에서 도움을 구하고 마리아의 치유를 지켜본다. 이후 두 사람의 서약을 묻고, 서로 진실하게 약속했음을 증언하며 부부가 되었음을 선언한다.","source":"S-ec1616980738"}],"evaluation":[{"title":"자기 연민까지 돌아보는 돌봄","text":"보육원에서 아이들을 신나게 놀아주지만, 함께 밥을 먹을 때는 자신에게도 동정심이 남아 있음을 인정한다. 오히려 서로를 자연스럽게 받아들이는 아이들에게 배운다고 말한다. 돌보는 사람인 자신을 완벽한 선인으로 놓지 않는 이 고백이 머독의 따뜻함에 깊이를 더한다.","source":"S-081f7fb3f726"},{"title":"사명을 거창한 보상과 바꾸지 않는다","text":"앞에서 싸우는 사람에게 언제나 칭송이 돌아오지는 않으며, 그 일을 해야 할 사람이 하는 것이라고 설명한다. 한편 직접 행동하는 것이 어렵다는 점을 알아보고 존을 응원한다. 자신의 힘을 과시하는 데서 그치지 않고, 다른 방식으로 책임을 맡는 동료의 용기도 인정한다.","source":"S-2ea37fcffe10"},{"title":"위로를 다음 약속으로 이어가다","text":"부상당한 동료들과 냇가에 앉아 오래된 친구와 일상을 이야기하고, 상처가 아물면 함께 꽃구경을 가자고 한다. 잃은 것을 되돌릴 수 있다고 장담하기보다 함께 보낼 시간을 남겨둔다. 거창한 해결책 없이도 관계가 계속된다는 감각을 건네는 방식이다.","source":"S-9c5be8e75504"},{"title":"유쾌함에는 곤란한 장난도 섞인다","text":"잠든 동료들의 문을 두드리며 가짜 공습경보를 외치고 크게 웃는다. 머독의 활력과 장난기가 길드 일상을 만드는 것은 분명하지만, 놀란 사람에게도 편안한 행동은 아니다. 다정한 선배라는 이미지와 타인의 경계를 가볍게 넘는 순간을 함께 보아야 한다.","source":"S-b4e5d288c8e9"},{"title":"축하와 걱정을 한꺼번에 품다","text":"마리아와 하일로의 서약을 이끌면서도 두 사람이 앞으로 받을 시선을 떠올린다. 그 걱정을 결혼을 막는 말로 바꾸지 않고 짧은 축하를 남긴다. 경험으로 예상하는 고통과 당사자들이 고른 행복을 동시에 존중하려는 모습이다.","source":"S-ec1616980738"}],"traits":{"social":{"score":5,"text":"아이들과 몸을 움직여 놀고 동료를 먼저 부르며 함께 밥과 술을 나눈다. 이름을 엉뚱하게 부르고 크게 농담하는 방식은 친근하지만 때로 상대를 당황하게도 한다.","source":"S-081f7fb3f726","supportingSources":["S-b4e5d288c8e9"]},"emotion":{"score":4,"text":"기쁨과 장난을 크게 표현하고, 위독한 하일로 앞에서는 초조함과 안도를 숨기지 못한다. 딸과 오래된 동료에 대한 기억에서는 호탕한 모습 뒤의 슬픔도 드러난다.","source":"S-ec1616980738","supportingSources":["S-081f7fb3f726","S-b38099bf9e25"]},"altruism":{"score":5,"text":"보육원을 반복해서 찾고 동료의 청소를 도우며 위급한 사람에게 달려간다. 한 번의 큰 선언보다 자기 시간과 몸을 꾸준히 쓰는 행동이 근거다.","source":"S-081f7fb3f726","supportingSources":["S-b38099bf9e25","S-ec1616980738"]},"initiative":{"score":4,"text":"필요를 느낀 사람이 먼저 하면 된다고 말하며 동료에게 교육을 제안한다. 부상자들을 밖으로 데려가고 다음 나들이를 약속하는 등 공동의 행동을 시작하는 편이다.","source":"S-2ea37fcffe10","supportingSources":["S-9c5be8e75504"]},"caution":{"score":3,"text":"위급한 출혈과 전투의 조건은 살피지만 일상에서는 요리에 보이는 재료를 모두 넣거나 경보 장난을 벌인다. 경험에서 나온 판단과 즉흥적인 행동이 함께 있다.","source":"S-ec1616980738","supportingSources":["S-000404a1d715","S-b4e5d288c8e9"]},"bonds":{"score":5,"text":"딸과 옛 동료의 이름을 기억하고 보육원과 길드를 가족처럼 돌아본다. 부상 뒤의 나들이, 서로 그리워할 일이 없기를 바라는 농담에도 오래 함께하고 싶은 마음이 담긴다.","source":"S-081f7fb3f726","supportingSources":["S-b38099bf9e25","S-9c5be8e75504"]}},"relations":[{"name":"라이아흐 미샤","text":"보육원을 함께 방문하고 딸의 이야기를 털어놓은 동료. 돌봄과 동정, 가족에 관해 속마음을 나눈다.","source":"S-081f7fb3f726","characterId":"P-41ba4c5736e6"},{"name":"에스텔 벨라시타","text":"각자 부상을 겪은 뒤 냇가에서 함께 시간을 보낸 동료. 상처가 아물면 꽃구경을 가자며 앞으로의 약속을 건넨다.","source":"S-9c5be8e75504","characterId":"P-b522cca806d0"},{"name":"델타인","text":"청소 내기를 하고 오래된 동료들의 안부를 묻는 친구. 장수에 관한 우스갯소리로 서로 헤어질 걱정을 덜어주려 한다.","source":"S-b38099bf9e25","characterId":"P-c93f55c91873"},{"name":"존 (마법사)","text":"길드의 책임과 교육을 논한 동료. 말처럼 행동이 쉽지 않다는 것을 인정하고 먼저 움직이는 용기를 응원한다.","source":"S-2ea37fcffe10","characterId":"P-79263e0865dd"},{"name":"라이아흐 아카쿠","text":"앞에서 싸우는 이의 사명과 동료의 중요성을 이야기한 상대. 힘만이 아니라 등을 맡길 사람이 필요하다고 말한다.","source":"S-2ea37fcffe10","characterId":"P-96ab98d2591c"},{"name":"마리아 아나이스 에스더","text":"하일로를 살리기 위해 치유하는 모습을 곁에서 지켜보고, 이후 혼인 서약을 받은 동료. 기쁨과 앞날의 걱정을 함께 품는다.","source":"S-ec1616980738","characterId":"P-c9505ea97ebc"}],"scenes":[{"source":"S-081f7fb3f726","text":"아이들과 해적놀이를 한 뒤 딸과 돌봄을 이야기하는 보육원의 저녁."},{"source":"S-9c5be8e75504","text":"부상당한 동료들과 냇가에서 앉아 다음 꽃구경을 약속하는 시간."},{"source":"S-b4e5d288c8e9","text":"동료들의 낮잠을 깨우는 가짜 공습경보와 식사 소동."},{"source":"S-56bb874bb8ba","text":"흰 코털 하나에 노화를 고민하며 자신의 성장과 은사를 이야기하는 날."},{"source":"S-2ea37fcffe10","text":"누군가는 해야 할 일을 맡는다는 사명과 동료의 용기를 이야기하는 밤."},{"source":"S-ec1616980738","text":"하일로의 생환을 기뻐하고 마리아와의 서약을 증언하는 순간."}],"asOf":"2026-09-26","sources":["S-56bb874bb8ba","S-2ea37fcffe10","S-081f7fb3f726","S-ec1616980738","S-9c5be8e75504","S-b4e5d288c8e9","S-b38099bf9e25","S-000404a1d715"]},"P-1ebd61bdfafd":{"name":"딘 로안","updatedAt":"2026-10-01","tagline":"대단해지고 싶은 조급함을 안고, 사랑과 배움을 반복되는 노력으로 바꾸기 시작한 청년.","tags":["감정에 솔직한","인정을 갈망하는","노력으로 옮기는"],"profileNote":"딘 로안의 기록이다. 젊은 딘의 현재와 기억 공간의 늙은 딘을 구분했고, 훈련 장면의 “사망·활부”는 어제의 약한 자신을 버린다는 익살스러운 표현으로 읽었다. 스노우가 반지를 받은 사실을 청혼 승낙이나 혼인으로 바꾸지 않았다.","facts":[{"label":"이름과 나이","value":"9월 훈련 장면에서 래빗 풋, 딘 로안으로 소개되며 나이는 스무 살이다.","source":"S-b93795650dcc"},{"label":"마법에 대한 열망","value":"테론의 장례 때 부활을 주장하고, 정식으로 배운 적이 없다고 하면서도 바키르의 노트에서 찾은 주문으로 의식을 시도한다. 서술자는 슬픔뿐 아니라 마법에 대한 갈망과 자격지심도 동기라고 짚는다.","source":"S-c5e3e7fd297d"},{"label":"기억 공간의 사건","value":"솔과 니콜라스는 기억 속 길드에서 늙은 딘을 만난다. 솔이 그를 대신해 남은 뒤 현실로 돌아온 젊은 딘은 사건을 기억하지 못하는 모습이다. 기억 공간의 긴 세월을 현재 육체의 나이로 더하지 않았다.","source":"S-2101b42c14eb"},{"label":"문학 공부","value":"기본적인 읽기와 쓰기는 할 줄 안다. 스노우에게 마음을 전하고 싶어 사이먼을 찾아가, 예쁜 단어를 나열하기보다 자기 마음을 정리하는 문학을 배우겠다고 한다.","source":"S-73732fc8d2b9"},{"label":"훈련","value":"달리기와 맨몸운동을 다시 시작한다. 스스로 오십 일째라고 부르는 훈련에서는 통나무를 끌지 못하지만 붙기 시작한 근육을 확인하고 다시 시도한다.","source":"S-b93795650dcc"},{"label":"스노우에게 준 선물","value":"은반지를 감사의 표시로 건네며 손에 끼지 않아도 된다고 말한다. 좋아하는 마음은 분명히 밝히지만, 이 선물 자체에는 감사 외의 뜻을 담지 않겠다고 설명한다.","source":"S-de4617626822"}],"evaluation":[{"title":"선한 목표에도 자기 욕망이 섞인다","text":"테론을 살려야 한다고 외치는 딘은 동료를 잃은 슬픔과 함께 마법을 가진 사람들에 대한 열등감을 드러낸다. 이해하지 못한 주문으로 일행을 모으는 행동은 적극적이지만 위험하다. 진심을 가진다는 것과 그 진심이 안전하고 타당한 방법을 보장한다는 것은 다르다.","source":"S-c5e3e7fd297d"},{"title":"사랑이 생활을 바꾸는 계기가 되다","text":"스노우에게 반한 뒤 강해지겠다는 다짐은 달리기와 운동, 문학 공부로 이어진다. 거창한 목표와 우스운 실패가 함께 나오지만, 오십 일째에도 통나무에 다시 매달린다. 이미 뛰어난 전사가 됐다는 성과보다 반복해서 돌아오는 습관에서 성장을 읽을 수 있다.","source":"S-b93795650dcc"},{"title":"번지르르한 말보다 자기 마음을 배우려 한다","text":"사이먼에게 글자 대신 문학을 배우고 싶다고 명확히 말한다. 청혼이 목적이지만 예쁜 표현만 얻으려는 것은 아니며, 먼저 자기 감정을 정리하고 싶어한다. 자신에게 부족한 것이 무엇인지 구체적으로 말하고 배움을 요청하는 태도가 이전의 막연한 힘에 대한 갈망과 다른 지점이다.","source":"S-73732fc8d2b9"},{"title":"응답을 바라는 마음과 감사의 구분","text":"반지를 주기 전에는 빠른 연애 전개를 혼자 상상하지만 실제 대화에서는 감사의 표시라고 설명하고 착용을 요구하지 않는다. 반복해서 청혼하겠다는 조급함은 여전히 남아 있다. 그 안에서도 선물을 받은 상대가 부담을 느낄 수 있음을 생각하기 시작한다는 변화가 보인다.","source":"S-de4617626822"},{"title":"웃음이 슬픔을 다 보여주지는 않는다","text":"사이먼의 죽음을 들은 딘은 속으로 약속을 남긴 선배에게 화를 내지만 겉으로는 밝게 웃는다. 시안에게도 낙엽 청소 농담으로 답해 서로의 슬픔을 알아보지 못한다. 표현이 풍부한 인물이라도 감당하기 힘든 상실 앞에서는 마음과 말이 갈라질 수 있다는 장면이다.","source":"S-1a7d7f547838"},{"title":"설득의 실패 뒤에도 남는 질문","text":"우물을 오염시킨 루카에게 남겨둔 해독제를 보이며 스스로와 세상을 용서하라고 설득한다. 설득과 해독 시도가 모두 뜻대로 되지는 않아 사건은 왕국에 넘겨진다. 딘은 귀환길에서 자신들도 같은 고통을 겪으면 무엇으로 견딜지 묻는다. 해결한 영웅담보다 실패 뒤에 남은 질문이 인물을 설명한다.","source":"S-e8ad1cc5cc64"}],"traits":{"social":{"score":4,"text":"선배를 찾아 도움을 청하고 처음 마음이 움직인 상대에게도 적극적으로 다가간다. 다만 들뜬 말과 빠른 청혼이 상대의 속도와 늘 맞는 것은 아니다.","source":"S-73732fc8d2b9","supportingSources":["S-9db8a463da4d","S-de4617626822"]},"emotion":{"score":5,"text":"사랑이 훈련을 다시 시작하게 하고, 열등감이 위험한 의식의 동기가 되며, 상실은 감춘 분노로 남는다. 밝은 표현뿐 아니라 선택을 움직이는 감정의 비중이 크다.","source":"S-c5e3e7fd297d","supportingSources":["S-b93795650dcc","S-1a7d7f547838"]},"altruism":{"score":3,"text":"루카에게 해독제를 내밀고 용서할 길을 찾으려 하지만 테론의 부활 시도에는 자신의 열망도 섞여 있다. 타인을 위하는 마음과 인정받고 싶은 욕구가 공존한다.","source":"S-e8ad1cc5cc64","supportingSources":["S-c5e3e7fd297d"]},"initiative":{"score":5,"text":"동료를 모아 의식을 시도하고, 스스로 공부를 청하며 반복해서 운동한다. 옳은 결과를 보장하는 점수가 아니라 생각을 실제 행동으로 옮기는 빈도와 강도를 나타낸다.","source":"S-73732fc8d2b9","supportingSources":["S-c5e3e7fd297d","S-b93795650dcc"]},"caution":{"score":2,"text":"정체를 충분히 이해하지 못한 주문을 감으로 골라 시도할 만큼 조급하다. 이후 반지가 상대에게 줄 부담을 생각하는 장면도 있지만, 확인한 대표 장면에서는 숙고보다 열망이 먼저 나서는 경향이 강하다.","source":"S-c5e3e7fd297d","supportingSources":["S-de4617626822"]},"bonds":{"score":4,"text":"스노우와의 만남에 삶을 바꾸는 의미를 부여하고, 사이먼과의 배움 약속이 끊기자 크게 흔들린다. 관계에 거는 기대가 높고 그 연결이 자신의 목표를 지탱한다.","source":"S-de4617626822","supportingSources":["S-73732fc8d2b9","S-1a7d7f547838"]}},"relations":[{"name":"스노우 글로우","text":"반한 뒤 훈련과 공부를 다시 시작하게 된 상대. 감사의 반지를 건네지만 이 장면에서 결혼이 성사된 것은 아니다.","source":"S-de4617626822","characterId":"P-2bd2e06457e6"},{"name":"사이먼 피터 포레스트","text":"자기 마음을 표현할 문학을 배우고자 찾아간 선배. 이후 그를 잃었다는 소식은 지켜지지 못한 약속과 분노로 남는다.","source":"S-73732fc8d2b9","characterId":"P-3ea4affc20fd"},{"name":"솔 세크메트","text":"기억 속 길드에서 늙은 딘을 대신해 남기로 선택한 인물. 현재의 딘이 그 사건을 기억하지 못한다는 점까지 함께 보아야 하는 인연이다.","source":"S-2101b42c14eb","characterId":"P-e2f54d3db7fa"},{"name":"션","text":"우물 사건을 함께 조사하고 귀환길에 고통을 견디는 방법을 물은 선배. 훗날 사이먼의 소식도 전해 듣는다.","source":"S-e8ad1cc5cc64","characterId":"P-3bbc4a823df9"},{"name":"시안 던 브링어","text":"사이먼의 죽음을 전해 들은 직후 말을 걸어온 동료. 농담하는 딘의 겉모습 때문에 속에 있는 슬픔이 충분히 전해지지 않는다.","source":"S-1a7d7f547838","characterId":"P-77d4478f4f51"},{"name":"바키르 리온하르트","text":"테론의 부활을 두고 부딪친 선배. 딘은 그의 신중한 판단을 따르지 않고 노트의 주문으로 별도 의식을 시도한다.","source":"S-c5e3e7fd297d","characterId":"P-7ca1485d4525"}],"scenes":[{"source":"S-c5e3e7fd297d","text":"테론을 살리겠다는 주장과 마법에 대한 갈망이 뒤얽힌 부활 시도."},{"source":"S-2101b42c14eb","text":"기억 공간의 늙은 딘과 솔의 선택, 사건을 기억하지 못하는 젊은 딘의 귀환."},{"source":"S-73732fc8d2b9","text":"사이먼에게 글자가 아니라 마음을 정리하는 문학을 배우겠다고 청하는 방문."},{"source":"S-de4617626822","text":"냇가에서 스노우에게 감사의 은반지를 건네는 대화."},{"source":"S-1a7d7f547838","text":"사이먼의 부재를 알게 된 뒤 밝은 말과 속마음이 갈라지는 순간."},{"source":"S-b93795650dcc","text":"끌리지 않는 통나무 앞에서도 다시 시도하는 오십 일째의 훈련."}],"asOf":"2026-09-23","sources":["S-b93795650dcc","S-c5e3e7fd297d","S-2101b42c14eb","S-73732fc8d2b9","S-de4617626822","S-1a7d7f547838","S-e8ad1cc5cc64","S-9db8a463da4d"]},"P-b6d81d634c6e":{"name":"마리우스","updatedAt":"2026-10-01","tagline":"잃은 사람을 붙잡던 검사가, 후회를 배움으로 바꾸며 살아갈 내일을 고른다.","tags":["변화를 배우는","애정이 깊은","스스로를 돌아보는"],"profileNote":"투구 뒤에 숨던 초기와 동료들에게 자신의 변화를 설명하는 후기의 차이를 함께 읽었다. 분노·자책·상실은 해당 장면의 표현이며 현실의 진단이 아니다. 션과 숀은 서로 다른 인물로 구분했다.","facts":[{"label":"초기의 모습","value":"고양이 투구를 쓰고 지내다가 벗기 시작한다. 새로운 길드원들과 친해지고 싶어도 사람이 한꺼번에 몰릴까 두려워하던 시기가 있다.","source":"S-820686cae6d9"},{"label":"검과 훈련","value":"몸과 마음이 뜻대로 따라주지 않자 분노로 검을 휘두른다. 션에게 스스로에 대한 과도한 기대를 지적받고, 의뢰와 훈련을 통해 다시 배우기로 한다.","source":"S-b16ae0671ee9"},{"label":"대장간의 배움","value":"첫 스승 헬리오스가 남긴 손글씨 공책을 보며 검을 만든다. 준비물을 확인하라는 조언과 자신을 믿는다는 말을 오래 간직한다.","source":"S-522181b5091f"},{"label":"션과의 관계","value":"검술을 배우는 관계에서 연인 관계로 이어진다. 고백이 처음부터 순조롭게 받아들여진 것은 아니며, 거절과 재확인을 거친 기록이 남아 있다.","source":"S-9c050760b1e6"},{"label":"부활 시도와 책임","value":"테론이 언데드로 깨어났다고 션에게 알리며, 자신들의 의식이 직접 원인인지는 모른다고 답한다. 같은 시도를 반복하지 않겠다고 약속하고 후속 문제를 함께 감당하기로 한다.","source":"S-cfdd5c8342cf"},{"label":"최근의 상실","value":"탑에서 돌아온 뒤 존재를 미처 알지 못했던 아이를 잃었다고 독백한다. 슬픔 속에서도 스승의 말을 떠올리며 미안함만이 아니라 고마움을 전하고 살아가려 한다.","source":"S-897809bb70f3"}],"evaluation":[{"title":"잘해야 한다는 마음이 자신을 다치게 할 때","text":"초기 훈련에서는 실패가 곧 자신의 부족함을 증명하는 것처럼 받아들인다. 션이 어설프게 시작해도 된다고 말하는 장면은 기술 지도인 동시에, 완벽하지 않은 자신을 허락하는 연습의 출발점이다.","source":"S-b16ae0671ee9"},{"title":"사랑하는 마음과 옳은 판단은 별개다","text":"테론을 되찾고 싶은 마음은 강하지만 부활의 결과와 책임을 충분히 알지는 못했다. 이 일을 단순한 헌신으로 칭찬하기보다, 상대를 잃기 싫은 마음이 위험한 선택으로 이어지고 이후 책임을 배워가는 장면으로 읽었다.","source":"S-cfdd5c8342cf"},{"title":"원망하던 상대의 이야기를 듣는 변화","text":"테이레시아스를 다시 만났을 때 이전의 원망을 되풀이하기보다 그가 떠났던 사정을 듣는다. 자신이 벗어나온 어둠을 상대도 벗어나기를 바라는 반응은, 자신의 상처만으로 관계를 판단하지 않으려는 변화다.","source":"S-622ccf92f57a"},{"title":"후회와 자책을 구분하기 시작하다","text":"후회를 없애겠다고 선언하지 않는다. 잘못을 돌아보되 끝없이 자신을 미워하는 방향으로 내려가지 않겠다는 선택이다. 헬리오스의 말을 자신의 언어로 다시 이해하는 과정에서, 오래된 가르침이 현재의 생활 방식이 된다.","source":"S-ed2594aca09d"},{"title":"자신이 배운 것을 다른 사람에게 건네다","text":"라이티티아와 시안 앞에서 과거의 두려움을 말하며 잘못했어도 달라질 수 있다고 전한다. 곧이어 엘레나의 머리맡에 사탕을 놓는 행동은 긴 조언을 작은 돌봄으로 이어준다. 성장의 결과가 강해졌다는 자평에만 머무르지 않는다.","source":"S-37a221a475ef"}],"traits":{"social":{"score":3,"text":"처음에는 낯선 동료에게 말을 거는 일을 두려워하지만, 이후에는 자신의 경험을 먼저 꺼내 대화를 연다. 처음부터 외향적이었다기보다 안전한 관계 안에서 교류의 폭을 넓혔다.","source":"S-37a221a475ef","supportingSources":["S-820686cae6d9"]},"emotion":{"score":5,"text":"분노와 그리움, 애정과 상실이 독백과 행동에 강하게 드러난다. 후기의 성장은 감정이 줄었다기보다 그것을 판단의 전부로 삼지 않으려는 방향이다.","source":"S-897809bb70f3","supportingSources":["S-b16ae0671ee9","S-ed2594aca09d"]},"altruism":{"score":4,"text":"상처 입은 동료의 사정을 듣고 작은 선물을 놓아준다. 다만 사람을 되찾으려는 행동에는 자신의 상실을 견디기 어려운 마음도 섞여 있으므로 모든 희생을 무조건적인 이타성으로 보지는 않았다.","source":"S-37a221a475ef","supportingSources":["S-cfdd5c8342cf"]},"initiative":{"score":4,"text":"검술과 단조를 반복해서 배우고, 잘못한 일도 직접 찾아가 설명한다. 도움을 받는 위치에서 출발했어도 자신의 생활과 관계를 바꾸기 위해 행동하는 장면이 이어진다.","source":"S-522181b5091f","supportingSources":["S-cfdd5c8342cf"]},"caution":{"score":3,"text":"초기에는 분노와 부활에 대한 바람이 판단을 앞서지만, 후기에는 과거의 선택을 구분해 살피고 현재에 집중하려 한다. 신중함이 이미 완성되었다기보다 배워가는 과정이다.","source":"S-ed2594aca09d","supportingSources":["S-cfdd5c8342cf","S-622ccf92f57a"]},"bonds":{"score":5,"text":"스승의 공책과 말, 연인과의 약속, 떠나보낸 사람의 기억을 오래 간직한다. 유대는 한때 자신을 몰아붙이는 이유였고, 이후에는 살아갈 이유와 타인을 돌보는 근거가 된다.","source":"S-522181b5091f","supportingSources":["S-897809bb70f3","S-9c050760b1e6"]}},"relations":[{"name":"션","text":"검술을 가르치던 스승이자 연인. 부활의 책임을 두고 충돌하면서도 함께 후속 문제를 감당할 길을 찾는다.","source":"S-cfdd5c8342cf","characterId":"P-3bbc4a823df9"},{"name":"테이레시아스","text":"과거의 원망을 내려놓고 상대의 생존 경험을 듣기 시작한 동료. 관계를 다시 이해하려는 변화가 드러난다.","source":"S-622ccf92f57a","characterId":"P-ca9ea162ed1b"},{"name":"라이티티아","text":"자신이 달라진 과정을 먼저 들려준 동료. 지나간 잘못 때문에 앞으로도 변하지 못하는 것은 아니라고 전한다.","source":"S-37a221a475ef","characterId":"P-fae6af716ea2"},{"name":"엘레나 레지아노","text":"상실로 지친 모습을 걱정하고 머리맡에 사탕을 놓아준 동료. 말없는 배려가 남는다.","source":"S-37a221a475ef","characterId":"P-89d5e8c6329e"}],"scenes":[{"source":"S-b16ae0671ee9","text":"분노로 내려치던 검과 어설프게 시작해도 된다는 션의 지도."},{"source":"S-cfdd5c8342cf","text":"테론의 귀환을 알린 뒤 죽음과 선택의 책임을 묻는 대화."},{"source":"S-522181b5091f","text":"스승의 손글씨를 읽으며 검을 만드는 대장간."},{"source":"S-622ccf92f57a","text":"원망하던 동료의 사정을 끝까지 듣는 재회."},{"source":"S-37a221a475ef","text":"후배들에게 변할 수 있다고 말하고 사탕을 놓아주는 밤."},{"source":"S-897809bb70f3","text":"이름조차 알지 못했던 아이에게 남기는 작별의 독백."}],"asOf":"2026-09-26","sources":["S-820686cae6d9","S-b16ae0671ee9","S-522181b5091f","S-9c050760b1e6","S-cfdd5c8342cf","S-897809bb70f3","S-622ccf92f57a","S-ed2594aca09d","S-37a221a475ef"]},"P-c93f55c91873":{"name":"델타인","updatedAt":"2026-10-01","tagline":"어둠대왕을 꿈꾸며, 사람의 감정과 함께 살아가는 규칙을 서툴게 배운다.","tags":["호기심이 많은","표현을 배우는","생활력이 있는"],"profileNote":"흑마도사라는 자기소개와 어둠대왕이라는 장래의 꿈을 구분했다. 감정을 모르겠다는 본인의 말, 실제로 드러나는 감정, 무례하거나 잔혹한 행동을 함께 살폈다. 현실의 심리 진단이나 오너 평가는 아니다.","facts":[{"label":"자기소개와 꿈","value":"자신을 흑마도사라고 부른다. 빛의 축복을 받지 못하는 어둠 속 사람들을 살피는 왕이 되고 싶다고 아마이 조에게 설명한다.","source":"S-037884b8974e"},{"label":"감정을 이해하는 방식","value":"세드릭에게 즐거움 같은 감정을 거의 느끼지 못해 잘 모르겠다고 말한다. 이후에는 호감과 사랑의 의미를 직접 묻고 자신의 반응을 관찰한다.","source":"S-6a625d8c8464"},{"label":"길드의 일상","value":"요리와 청소를 자주 맡는다. 닭 요리와 볶음밥을 여러 사람에게 나누고, 진지한 대화를 마친 뒤에도 남은 청소를 챙긴다.","source":"S-9cf4a6f61025"},{"label":"도구","value":"의뢰에 쓸 긴 장대를 직접 깎는다. 쇠로 만들었다가 너무 무거워 실패한 경험도 말하며 실용적인 시행착오를 반복한다.","source":"S-2f6e4935173f"},{"label":"엘레나와의 관계","value":"처음에는 소중한 친구로 남기로 했지만 이후 연인이 된다. 사랑의 의미와 원치 않는 행동을 서로 말하며 관계를 배워간다.","source":"S-250c1e1d96d1"},{"label":"친구의 기준","value":"친구 명부를 적어 관계를 구체적으로 구분한다. 에스텔의 요청을 받고 이름을 올리며 악수하는 기록이 남아 있다.","source":"S-2f6e4935173f"}],"evaluation":[{"title":"어둠이라는 말에 담긴 보호의 꿈","text":"큰소리와 과장된 호칭 뒤에는 세상에서 밀려난 사람을 살피고 싶다는 목적이 있다. 그러나 같은 대화에서 생물을 잔혹하게 다루는 행동도 보인다. 좋은 왕이 되고 싶다는 선언과 현재의 윤리적 판단 사이에는 아직 채워야 할 거리가 있다.","source":"S-037884b8974e"},{"title":"모른다고 말한 뒤 질문을 시작하다","text":"다른 사람을 불쾌하게 만든 일을 겪고 엘레나에게 자신이 잘못한 점을 묻는다. 무례함을 개성으로만 밀어붙이지 않고, 모르겠다는 상태에서 배우려는 행동으로 옮겨간다는 점이 변화의 핵심이다.","source":"S-52aac036c503"},{"title":"감정이 서툴러도 관계를 고를 수 있다","text":"연애를 시작한 뒤에도 기분이 좋은 이유를 쉽게 설명하지 못한다. 그래도 엘레나와 함께 알아가려 하고, 사랑이 자신에게 어려울 수 있음을 받아들인다. 감정을 정확히 정의하는 것보다 상대와 이야기를 이어가는 선택이 먼저 생긴다.","source":"S-250c1e1d96d1"},{"title":"기이한 말과 든든한 생활이 공존하다","text":"상대의 이름을 엉뚱하게 부르고 짓궂은 말을 하지만 식탁에서는 사람 수에 맞춰 음식을 나눈다. 눈에 띄는 기행만으로 보면 놓치기 쉬운 생활의 기여가 있으며, 동시에 남을 불편하게 하는 말까지 선의로 지워서는 안 된다.","source":"S-9cf4a6f61025"},{"title":"친구를 적는 행위의 무게","text":"에스텔을 명부에 올리는 일은 우스운 절차처럼 보이지만, 관계를 당연히 아는 것으로 처리하지 않는 델타인의 방식이다. 상실을 듣고 위로하고 도움을 이야기하는 대화 안에서, 친구라는 말에 실제 행동을 붙여간다.","source":"S-2f6e4935173f"}],"traits":{"social":{"score":4,"text":"처음 보는 사람과도 말을 섞고 식사와 청소로 접점을 만든다. 대화를 시작하는 힘은 크지만 이름을 틀리거나 상대의 경계를 놓치는 일도 있어 매끄러운 사교와는 구별된다.","source":"S-9cf4a6f61025","supportingSources":["S-52aac036c503"]},"emotion":{"score":2,"text":"기쁨과 슬픔을 이해하기 어렵다는 설명이 반복된다. 다만 호감과 서운함이 실제로 나타나므로 감정이 없다고 단정하지 않고, 표현과 자각이 제한적이라는 뜻으로 읽었다.","source":"S-6a625d8c8464","supportingSources":["S-250c1e1d96d1"]},"altruism":{"score":3,"text":"소외된 사람을 돕고 싶어 하고 음식을 나누지만, 잔혹한 행동과 상대를 불편하게 하는 말도 있다. 보호의 꿈과 실제 배려의 일관성 사이에 차이가 남아 있다.","source":"S-037884b8974e","supportingSources":["S-9cf4a6f61025"]},"initiative":{"score":5,"text":"청소·요리·도구 제작을 스스로 시작하고, 관계에서도 직접 질문하거나 연애 의사를 밝힌다. 서툴러도 행동을 멈추지 않는 편이다.","source":"S-52aac036c503","supportingSources":["S-2f6e4935173f"]},"caution":{"score":2,"text":"호기심과 먼저 해보려는 마음이 강해 상대의 감정과 말의 영향을 뒤늦게 살피는 일이 있다. 잘못한 뒤 묻고 수정하는 태도는 있으나 사전 판단은 아직 불안정하다.","source":"S-52aac036c503","supportingSources":["S-250c1e1d96d1"]},"bonds":{"score":4,"text":"친구 명부를 만들고 동료가 자신을 찾지 않는 일을 서운해한다. 엘레나와의 관계를 오래 두고 이해하려는 마음도 드러나며, 감정의 서툶이 유대에 대한 무관심은 아니다.","source":"S-2f6e4935173f","supportingSources":["S-250c1e1d96d1"]}},"relations":[{"name":"엘레나 레지아노","text":"사과와 호감의 표현을 배우고, 친구에서 연인으로 관계를 이어간 상대. 서로 싫은 행동을 말하며 가까워진다.","source":"S-250c1e1d96d1","characterId":"P-89d5e8c6329e"},{"name":"아마이 조","text":"어둠대왕의 꿈과 자신의 과거를 들려준 동료. 장난과 청소 잔소리 사이로 진지한 목적을 밝힌다.","source":"S-037884b8974e","characterId":"P-5d58655d55ce"},{"name":"에스텔 벨라시타","text":"친구 명부에 이름을 올리고 상실과 도움받는 일을 이야기한 동료.","source":"S-2f6e4935173f","characterId":"P-b522cca806d0"},{"name":"니콜라스 플린트","text":"야식을 권하고 책의 지식을 묻는 상대. 연체료를 음식으로 대신하려다 거절당하는 등 배움과 잔꾀가 함께 드러난다.","source":"S-9cf4a6f61025","characterId":"P-216ccc194078"}],"scenes":[{"source":"S-9cf4a6f61025","text":"닭 요리와 볶음밥을 나누는 겨울 야식."},{"source":"S-6a625d8c8464","text":"세드릭의 즐거움에 자신은 잘 모르겠다고 답하는 도서관."},{"source":"S-037884b8974e","text":"어둠 속 사람들을 위한 왕을 꿈꾼다고 말하는 밤."},{"source":"S-52aac036c503","text":"자신의 무례함을 묻고 친구라는 관계를 확인하는 대화."},{"source":"S-250c1e1d96d1","text":"연인이 된 뒤 사랑의 감정을 함께 알아가려는 시간."},{"source":"S-2f6e4935173f","text":"새 장대를 깎으며 친구 명부에 에스텔의 이름을 적는 저녁."}],"asOf":"2026-09-23","sources":["S-037884b8974e","S-6a625d8c8464","S-9cf4a6f61025","S-2f6e4935173f","S-250c1e1d96d1","S-52aac036c503"]},"P-f6ccefd2c259":{"name":"하일로 조바","updatedAt":"2026-10-01","tagline":"음악과 배움을 좋아하는 청년이, 사랑을 지키는 일과 진실을 나누는 책임을 배운다.","tags":["꾸준히 배우는","애정이 깊은","솔직함을 배우는"],"profileNote":"조바 본인의 행동과 같은 모습을 한 사념의 언행을 구분했다. 관계의 갈등, 저주와 그 해결의 대가를 함께 다루며, 고통을 감수했다는 이유로 앞선 거짓말과 상처 주는 말까지 정당화하지 않았다.","facts":[{"label":"음악가","value":"길드에서 활동하는 음악가라고 소개하며 바이올린을 연주한다. 낯선 배블스와도 음악을 계기로 이름과 경험을 나눈다.","source":"S-e964710abc47"},{"label":"마법 수련","value":"책을 읽고 파동과 장벽 마법을 연습한다. 한 번 성공한 주문도 다시 실패하며, 복습과 재시도 끝에 푸른 파동으로 나무를 흔드는 장면이 있다.","source":"S-a2101946ab19"},{"label":"가문과 선택","value":"마리아에게 정략혼인을 거부해 재산과 귀족 신분을 잃었다고 설명한다. 부재의 진짜 이유를 의뢰라고 둘러댄 일이 갈등을 키웠다.","source":"S-e3d90d94ce36"},{"label":"그림자의 정체","value":"자신을 닮은 존재는 실현되지 못한 혼인과 미래의 가능성에 얽힌 사념으로 드러난다. 그 존재의 도발을 조바 자신의 일관된 생각으로 읽지는 않았다.","source":"S-d1572856bee3"},{"label":"저주의 대가","value":"아델린을 죽이지 않고 마리아를 지키기 위해 후손의 가능성을 없애는 신체적 대가를 치렀다고 밝힌다. 해결 뒤에도 이를 말하기 어려워하는 모습이 남는다.","source":"S-2c944c9d494c"},{"label":"혼인과 이후","value":"큰 부상을 입고 돌아와 마리아의 치료를 받은 뒤, 머독 앞에서 서로를 배우자로 맞겠다고 서약한다. 이후 함께 살 집과 모험을 줄이는 생활을 의논한다.","source":"S-ec1616980738"}],"evaluation":[{"title":"재능보다 재시도로 보이는 배움","text":"성공한 마법을 다시 확인하고, 안 되면 책을 펼친다. 조바의 성장은 항상 멋진 돌파구로 나타나지 않는다. 손만 아픈 연습과 답답함을 견디며 몸에 익히려는 반복이 음악가의 일상과 연결된다.","source":"S-a2101946ab19"},{"title":"버림받을 두려움이 만든 비밀","text":"재산을 잃은 자신을 마리아가 떠날까 두려워 사실을 숨긴다. 그러나 보호하려던 관계가 그 거짓말 때문에 더 크게 다친다. 다급한 사과만큼, 상대가 나중에 이야기하겠다는 뜻을 받아들이는 일도 필요한 장면이다.","source":"S-e3d90d94ce36"},{"title":"다른 사람의 죽음을 해답으로 삼지 않다","text":"저주를 해결하는 과정에서 아델린을 죽이는 길을 택하지 않는다. 자신이 치른 대가는 크지만 이를 사랑의 크기를 재는 기준으로 일반화할 수는 없다. 이 이야기에서 조바가 타인을 살려두는 해결을 골랐다는 점에 의미가 있다.","source":"S-2c944c9d494c"},{"title":"상처 입은 채 돌아와 다시 약속하다","text":"혼인 서약은 완벽한 상태에서의 축하가 아니라 치료와 화해 속에서 이루어진다. 다시 함께하기로 한 뒤에도 맛을 느끼는 마법 같은 작은 생활의 가능성을 이야기한다. 극적인 고난의 끝이 일상에 대한 관심으로 이어진다.","source":"S-ec1616980738"},{"title":"혼자 감당하던 일을 말로 나누다","text":"저주를 푼 일을 마리아에게 설명하는 대화는 숨겼던 사정을 다시 공유하는 장면이다. 이전에는 두려움 때문에 거짓말했다면 이번에는 부끄럽고 아픈 내용도 말한다. 관계의 변화는 희생 자체보다 이런 소통에서 확인된다.","source":"S-2c944c9d494c"}],"traits":{"social":{"score":4,"text":"연주와 자기소개로 낯선 상대와 대화를 이어간다. 가까운 사람에게도 함께할 일을 먼저 제안하지만 상대의 뜻을 섬세하게 읽는 데에는 서툰 순간이 있다.","source":"S-e964710abc47","supportingSources":["S-2c944c9d494c"]},"emotion":{"score":5,"text":"사랑과 불안, 후회가 행동에 크게 작용한다. 버림받을 두려움 때문에 사실을 숨기고, 재회에는 기쁨과 눈물을 숨기지 않는다.","source":"S-e3d90d94ce36","supportingSources":["S-ec1616980738"]},"altruism":{"score":4,"text":"소중한 사람을 지키려 움직이고 다른 사람을 죽이지 않는 해결을 고른다. 다만 상대를 위해서라는 마음이 언제나 상대의 의사에 맞는 행동으로 이어지는 것은 아니다.","source":"S-2c944c9d494c","supportingSources":["S-e3d90d94ce36"]},"initiative":{"score":4,"text":"마법을 반복 수련하고 저주의 근원을 직접 찾아간다. 갈등 뒤에도 다시 설명하고 관계를 회복하려 나서는 힘이 있다.","source":"S-a2101946ab19","supportingSources":["S-d1572856bee3"]},"caution":{"score":2,"text":"훈련에서는 복습하지만 관계의 위기에서는 숨김과 격한 말로 상황을 악화시킨다. 사랑하는 마음에 비해 위험과 소통의 결과를 차분히 조절하는 능력은 흔들린다.","source":"S-e3d90d94ce36","supportingSources":["S-a2101946ab19"]},"bonds":{"score":5,"text":"가문의 기대와 재산보다 마리아와 함께할 삶을 고른다. 갈등과 상실을 겪은 뒤에도 관계를 다시 맺고 미래의 생활을 이야기하려 한다.","source":"S-ec1616980738","supportingSources":["S-e3d90d94ce36","S-2c944c9d494c"]}},"relations":[{"name":"마리아 아나이스 에스더","text":"연인이자 혼인 서약을 나눈 배우자. 서로를 지키려는 마음, 비밀 때문에 생긴 갈등, 치료와 화해를 함께 겪는다.","source":"S-ec1616980738","characterId":"P-c9505ea97ebc"},{"name":"핀 머독","text":"큰 부상을 입고 돌아온 자신을 걱정하고 혼인 서약을 지켜본 동료. 치료를 시행한 인물은 마리아다.","source":"S-ec1616980738","characterId":"P-87b04eb56606"},{"name":"배블스 크린드","text":"시냇가에서 음악을 계기로 교류한 동료. 연주가 다른 사람과 관계를 여는 수단이 된다.","source":"S-e964710abc47","characterId":"P-4e086d6985d3"},{"name":"숀","text":"검술을 배우면서 마리아와 결혼하고 싶다는 뜻도 밝힌 선배. 공격대장 션과는 별개 인물이다.","source":"S-c61348f1a184","characterId":"P-5c88d36f51cd"}],"scenes":[{"source":"S-e964710abc47","text":"시냇가의 바이올린과 낯선 동료와의 음악 이야기."},{"source":"S-a2101946ab19","text":"여러 번 실패하고 다시 성공하는 파동 마법 연습."},{"source":"S-e3d90d94ce36","text":"의뢰라고 숨겼던 집안일이 드러나며 크게 다투는 귀환."},{"source":"S-d1572856bee3","text":"자신의 그림자와 실현되지 못한 미래, 저주의 해결을 다룬 연속 이야기."},{"source":"S-ec1616980738","text":"치료와 재회 끝에 이루어진 혼인 서약."},{"source":"S-2c944c9d494c","text":"저주를 푼 대가를 털어놓고 위로를 받는 신혼의 대화."}],"asOf":"2026-09-28","sources":["S-e964710abc47","S-a2101946ab19","S-e3d90d94ce36","S-d1572856bee3","S-2c944c9d494c","S-ec1616980738","S-c61348f1a184"]},"P-6a1a99e98a44":{"name":"가델랏 허그","updatedAt":"2026-10-01","tagline":"혼자 사냥하던 티플링이, 돌아올 동료와 모험담을 나눌 사람을 얻어간다.","tags":["몸으로 부딪치는","정이 깊은","모험을 즐기는"],"profileNote":"호탕한 말투와 장난만큼 동료를 잃을 두려움도 살폈다. 캠프의 투서는 상대측 주장으로, 허그의 반박과 진행 중인 조사와 구분했다. 다른 프로필이 조종한 인물을 허그와 합치지 않았다.","facts":[{"label":"종족과 어린 시절","value":"티플링으로 서술된다. 어린 시절 아버지 가버른과 떠돌다가 아버지가 돌아오지 않아 혼자 버티고, 지나가던 이들에게 발견된 기억이 남아 있다.","source":"S-114f145201f8"},{"label":"길드에 온 계기","value":"혼자 마물을 사냥하던 중 다른 사냥꾼들과의 협동을 경험한다. 단독 사냥의 한계를 느낀 뒤 스텔라의 면접을 거쳐 길드에 들어온다.","source":"S-fdccc9797152"},{"label":"생활과 장비","value":"철퇴와 도끼를 생활 속에서도 활용하며 불을 피우고 음식을 나눈다. 모닥불과 육포, 다음 의뢰 이야기가 동료를 만나는 접점이 된다.","source":"S-ea0a6dbb8f71"},{"label":"뻬르난떼와의 인연","value":"거미 동굴에서 그가 남아 일행을 지킨 이유를 직접 묻는다. 자신을 믿고 구조를 맡겼다는 설명을 듣고 망토를 선물하며 다시 신뢰하기로 한다.","source":"S-ef5e379367d6"},{"label":"직접 만드는 선물","value":"여러 번 실패한 뒤 큰 덩굴 망토를 만들어 뻬르난떼에게 건넨다. 물건을 만드는 수고와 서로의 모험을 들려주는 시간을 함께 선물한다.","source":"S-e148fc888f2b"},{"label":"최근의 갈등","value":"캠프의 항의를 받은 스텔라에게 원정 동료들이 보수와 소재를 빼앗았다고 설명한다. 조사와 항의를 약속받으며, 낙타 사육에는 필요성을 증명할 유예 기간이 주어진다.","source":"S-041849dc9b6b"}],"evaluation":[{"title":"용기보다 먼저 배우는 협동","text":"길드 입문은 혼자서도 충분히 강하다는 증명이 아니다. 사냥의 한계를 겪고 동료가 필요하다고 인정하는 과정이다. 이후 관계에 애착을 갖는 모습은 이 시작과 연결해 읽을 수 있다.","source":"S-fdccc9797152"},{"title":"죽을 뻔한 친구에게 직접 묻다","text":"거미 동굴 이후 머릿속으로만 이유를 짐작하지 않고 뻬르난떼의 방을 찾아간다. 무모해 보였던 행동이 자신에 대한 신뢰였음을 들으며 감정이 바뀐다. 다 이해하지 못해도 상대에게 묻고 다시 믿기로 하는 능력이 보인다.","source":"S-ef5e379367d6"},{"title":"두려운 사람에게 용기를 강요하지 않다","text":"모험이 무섭다는 라이티티아에게 안 해도 괜찮다고 말한다. 자신이 모험을 계속한다고 상대도 같은 답을 내야 한다고 밀어붙이지 않는다. 호탕한 인상 아래에 선택을 남겨두는 배려가 있다.","source":"S-ea0a6dbb8f71"},{"title":"말보다 손이 오래 머무는 애정","text":"망토를 만들다 실패해도 재료를 다시 가져온다. 선물을 건네고 모험담을 나누는 시간은 허그에게 동료가 단순한 전력 이상의 존재가 되었음을 보여준다. 서투른 제작 과정 자체에 상대를 생각한 시간이 남는다.","source":"S-e148fc888f2b"},{"title":"자유로운 생활이 공동체의 규칙을 만나다","text":"캠프 문제에서는 자기 입장을 설명하고 길드의 도움을 받는다. 낙타를 기르는 일에는 다른 사람의 부담과 운영의 판단이 따른다. 소속은 보호받는 권리뿐 아니라 자신의 생활을 설명하고 조정하는 책임도 요구한다.","source":"S-041849dc9b6b"}],"traits":{"social":{"score":5,"text":"모닥불과 음식, 술 약속으로 동료들을 자연스럽게 끌어들인다. 말을 먼저 걸고 함께할 즐거움을 찾는 행동이 반복된다.","source":"S-ea0a6dbb8f71","supportingSources":["S-e148fc888f2b"]},"emotion":{"score":4,"text":"동료의 중상에 느낀 절망과 재회의 안도, 선물을 줄 때의 기대를 숨기지 않는다. 웃음이 많다는 것이 두려움이 없다는 뜻은 아니다.","source":"S-ef5e379367d6","supportingSources":["S-ea0a6dbb8f71"]},"altruism":{"score":4,"text":"위험에서 사람들을 데리고 나오고, 동료를 위해 손수 물건을 만든다. 두려움을 털어놓는 사람에게도 자신의 답을 강요하지 않는다.","source":"S-ef5e379367d6","supportingSources":["S-e148fc888f2b","S-ea0a6dbb8f71"]},"initiative":{"score":5,"text":"사냥과 새 관계에 적극적으로 나서고 궁금한 일은 직접 찾아가 묻는다. 제작에 실패해도 다시 손을 움직이는 실행력이 강하다.","source":"S-e148fc888f2b","supportingSources":["S-fdccc9797152"]},"caution":{"score":2,"text":"먼저 몸으로 부딪치고 생활의 뒷문제를 나중에 조정하는 모습이 있다. 위험을 모르기보다는 모험과 하고 싶은 일의 추진력이 앞서는 편으로 읽힌다.","source":"S-041849dc9b6b","supportingSources":["S-fdccc9797152"]},"bonds":{"score":5,"text":"동료가 살아 돌아온 이유를 오래 생각하고 아끼던 망토와 직접 만든 선물로 마음을 전한다. 함께할 사람이 생긴 것이 모험의 의미를 바꾼다.","source":"S-ef5e379367d6","supportingSources":["S-e148fc888f2b"]}},"relations":[{"name":"돈 뻬르난떼 데 일리아","text":"위험한 모험을 함께하고 신뢰와 망토를 주고받는 가까운 동료. 직접 만든 선물과 긴 모험담으로 친밀함을 표현한다.","source":"S-e148fc888f2b","characterId":"P-1a1afae9c8db"},{"name":"라이티티아","text":"모험의 두려움을 듣고 그만두는 선택도 괜찮다고 말해준 동료. 함께 술을 마실 약속을 잡는다.","source":"S-ea0a6dbb8f71","characterId":"P-fae6af716ea2"},{"name":"시안 던 브링어","text":"모험을 이어가는 이유와 두려움을 같은 모닥불에서 나눈 동료.","source":"S-ea0a6dbb8f71","characterId":"P-77d4478f4f51"},{"name":"스텔라 스타라이트","text":"입회와 길드 생활의 규칙을 안내한 운영자. 캠프 문제를 조사하고 낙타 사육에도 조건을 제시한다.","source":"S-041849dc9b6b","characterId":"P-e6655a038328"}],"scenes":[{"source":"S-fdccc9797152","text":"협동의 필요를 배워 길드의 문을 두드리는 사냥꾼."},{"source":"S-ef5e379367d6","text":"거미 동굴 이후 서로를 믿는 이유를 묻고 망토를 건네는 밤."},{"source":"S-ea0a6dbb8f71","text":"모험이 무서워도 괜찮다고 말하는 모닥불."},{"source":"S-e148fc888f2b","text":"여러 번 실패해 완성한 덩굴 망토와 긴 모험담."},{"source":"S-114f145201f8","text":"돌아오지 않는 아버지를 기다렸던 어린 시절의 기억."},{"source":"S-041849dc9b6b","text":"캠프의 투서에 답하고 길드의 도움과 규칙을 확인하는 면담."}],"asOf":"2026-09-27","sources":["S-114f145201f8","S-fdccc9797152","S-ea0a6dbb8f71","S-ef5e379367d6","S-e148fc888f2b","S-041849dc9b6b"]},"P-5d0c306440d0":{"name":"폴라리스","updatedAt":"2026-10-01","tagline":"빌린 이름과 잊혀가는 기억 사이에서, 인연을 고르고 자유롭게 떠날 길을 찾는다.","tags":["다정하게 다가가는","자유를 바라는","기억을 붙드는"],"profileNote":"폴라리스·리스·제이는 같은 인물로 연결했다. 과거의 이름 주인과 현재 이 이름을 쓰는 인물의 사연은 구분하고, 이름을 빼앗은 존재와 진행 NPC의 대사를 본인의 성격으로 옮기지 않았다.","facts":[{"label":"이름","value":"신입 시절에는 폴라리스라고 소개하며 리스라고 불러달라고 한다. 훗날 휴가를 떠나는 마차 안에서 제이라는 새 이름을 고른다.","source":"S-d36152d5b46c"},{"label":"이야기와 음악","value":"스스로 이야기꾼이라고 소개한다. 피리와 노래로 사람들과 어울리며, 새해에는 바키르와 합주한 기록이 있다.","source":"S-abfd697cbf5a"},{"label":"정령과의 감각","value":"머독과 사잔을 찾아가 어린 시절의 기억을 마주하고 정령의 소리를 되찾는다. 서술은 막혀 있던 감각과 과거 마법사의 개입을 연결한다.","source":"S-343371fb42bc"},{"label":"북행과 실명","value":"이름을 빼앗은 존재를 찾아 북쪽으로 향한다. 나이아데스가 있는 섬에서 시력을 잃고, 귀항 중 고래에게 삼켜졌다가 아키라와 탈출한다.","source":"S-ecb01a94d7e0"},{"label":"빌린 이름의 무게","value":"폴라리스가 본래 자기 이름은 아니라고 생각한다. 자신이 그 이름마저 잊을까 두려웠던 마음을 돌아보며 다시 과거를 마주하려 한다.","source":"S-1baf3801bd9a"},{"label":"오즈월드에서의 선택","value":"어린 모습과 기억으로 돌아간 모험 끝에, 모든 기억을 잊는 길 대신 현실로 돌아가는 길을 고른다. 이후 휴가 쪽지를 남기고 새 이름으로 여행을 시작한다.","source":"S-03bc3273f41a"}],"evaluation":[{"title":"웃으며 다가가지만 처음부터 중심에 서지는 않는다","text":"길드에 처음 왔을 때 구석에서 분위기를 즐기다가 인사를 받으면 웃고 손을 내민다. 상대의 일에 관심을 보이며 실례가 아닌지도 묻는다. 친화력은 무조건 활발한 행동보다 상대에게 공간을 남기는 대화에서 드러난다.","source":"S-abfd697cbf5a"},{"title":"이름을 기억하는 일이 자신을 지키는 일이 되다","text":"빌린 이름을 놓지 못하는 이유를 스스로 묻는다. 잃은 사람과 이름의 기억이 사라질까 두려워하는 마음은 정체성을 단순한 호칭 이상의 문제로 만든다. 과거를 다시 마주하겠다는 다짐은 그 기억에 끌려다니는 상태를 바꾸려는 시도다.","source":"S-1baf3801bd9a"},{"title":"도움을 받으며 되찾는 감각","text":"정령을 느끼지 못하는 문제를 혼자 재능 부족으로 결론내리지 않고 머독과 사잔의 도움을 받는다. 어린 시절의 기억을 거쳐 정령과 다시 연결되는 경험은 관계를 통해 자신에게 남아 있던 가능성을 발견하는 이야기다.","source":"S-343371fb42bc"},{"title":"잊어서 편해지는 길 앞에서 돌아오다","text":"오즈월드는 괴로운 기억과 감정을 모두 두고 갈 가능성을 내민다. 폴라리스는 그 길을 택하지 않고 현실로 돌아가려 한다. 슬픔을 이겼다고 단정하기보다, 남아 있는 인연과 미련도 자신의 삶에 포함시키는 선택으로 읽었다.","source":"S-03bc3273f41a"},{"title":"돌아올 생각을 품고 떠나는 자유","text":"휴가 쪽지는 짧고 떠남은 갑작스럽지만, 독백은 이전과 달리 돌아올 생각을 했다고 짚는다. 인연을 매듭처럼 부담스러워하는 마음과 그것을 완전히 버리고 싶지는 않은 마음이 함께 있다. 자유와 관계 사이의 갈등이 사라진 것이 아니라 달라진 형태로 남는다.","source":"S-d36152d5b46c"}],"traits":{"social":{"score":4,"text":"낯선 사람의 인사에 웃으며 응하고 직업과 생활에 관심을 보인다. 자연스럽게 교류하지만 처음부터 군중의 중심으로 들어가려 하지는 않는다.","source":"S-abfd697cbf5a","supportingSources":["S-633df491d0a9"]},"emotion":{"score":4,"text":"잊혀가는 이름과 기억을 두려워하고, 인연에 얽힌 그리움과 부담을 독백으로 드러낸다. 겉의 부드러운 태도 아래 선택을 움직이는 감정이 깊다.","source":"S-1baf3801bd9a","supportingSources":["S-d36152d5b46c"]},"altruism":{"score":4,"text":"북행에서 나이아데스에게 도움을 약속하고 탈출에도 힘을 보탠다. 다만 돕겠다는 약속이 언제나 상황을 해결해주는 것은 아니며 자신도 위험에 놓인다.","source":"S-ecb01a94d7e0","supportingSources":["S-633df491d0a9"]},"initiative":{"score":4,"text":"감각을 되찾으러 길을 나서고, 이름의 과거를 마주하려 하며 새 여행도 직접 고른다. 고민이 길어져도 중요한 전환에는 행동으로 답한다.","source":"S-343371fb42bc","supportingSources":["S-1baf3801bd9a","S-d36152d5b46c"]},"caution":{"score":3,"text":"자기 마음을 오래 살피지만 북행에서는 예상치 못한 저주와 위험에 놓인다. 성찰의 깊이와 모험에서 결과를 미리 헤아리는 능력은 구별했다.","source":"S-ecb01a94d7e0","supportingSources":["S-1baf3801bd9a"]},"bonds":{"score":4,"text":"잃은 이름과 정령, 현재의 동료들을 쉽게 놓지 않는다. 동시에 인연의 무게에서 벗어나려 떠나는 마음도 있어, 관계에 머무는 방식은 유동적이다.","source":"S-03bc3273f41a","supportingSources":["S-d36152d5b46c"]}},"relations":[{"name":"핀 머독","text":"정령의 감각을 되찾을 수 있도록 사잔에게 데려간 동료. 긴 여정을 함께하고 돌아오는 길에는 나란히 잠든다.","source":"S-343371fb42bc","characterId":"P-87b04eb56606"},{"name":"아키라 베르데미켄","text":"고래 속에서 만나 탈출을 함께 준비한 동료. 서로 다른 힘과 방식으로 같은 난관을 통과한다.","source":"S-ecb01a94d7e0","characterId":"P-ee0c9d156dde"},{"name":"모나 델핀","text":"오즈월드에서 함께 어린 모습이 되어 모험한 동료. 기억이 달라진 폴라리스 곁에 현실의 인연이 남아 있다.","source":"S-03bc3273f41a","characterId":"P-48cca58d02b2"},{"name":"바키르 리온하르트","text":"새해의 이야기와 합주를 함께 즐긴 오랜 인연. 완벽하지 않아도 즐거운 교류를 나눈다.","source":"S-633df491d0a9","characterId":"P-7ca1485d4525"}],"scenes":[{"source":"S-abfd697cbf5a","text":"구석에서 길드의 분위기를 즐기던 신입 이야기꾼의 첫 인사."},{"source":"S-343371fb42bc","text":"사잔을 찾아가 어린 기억 너머 정령의 소리를 되찾는 여정."},{"source":"S-ecb01a94d7e0","text":"잃은 이름과 실명, 거대한 고래의 내부를 지나는 북행."},{"source":"S-1baf3801bd9a","text":"빌린 이름의 의미를 다시 묻는 독백."},{"source":"S-03bc3273f41a","text":"모든 것을 잊는 길 대신 현실을 택하는 오즈월드."},{"source":"S-d36152d5b46c","text":"휴가 쪽지를 남기고 제이라는 이름으로 시작하는 여행."}],"asOf":"2026-05-06","sources":["S-d36152d5b46c","S-abfd697cbf5a","S-343371fb42bc","S-ecb01a94d7e0","S-1baf3801bd9a","S-03bc3273f41a","S-633df491d0a9"]},"P-fec1db60d51e":{"name":"레마 캐롤라인","updatedAt":"2026-10-01","tagline":"버려졌던 기억을 가진 궁수가, 함께 먹고 배우며 자기 몫의 자리를 만든다.","tags":["꾸준히 수련하는","생활로 돌보는","관계를 배우는"],"profileNote":"말을 더듬는 표현 자체를 능력이나 성격의 약점으로 평가하지 않았다. 초기의 거친 가족관, 활을 다루는 숙련, 동료에게 음식을 나누는 이후의 모습을 함께 읽었다.","facts":[{"label":"종족과 나이","value":"길드 입회 당시 자신을 스물한 살 레마 캐롤라인이라고 소개하는 티플링. 분홍빛 피부와 뿔이 묘사된다.","source":"S-d4077642fb3c"},{"label":"성장 배경","value":"부모에게 버려졌으며 얼굴도 보지 못했다고 말한다. 고향에서 마귀할멈이라고 부르는 인물에게 활을 배웠고, 그 양육을 일꾼처럼 길러진 경험으로 설명하기도 한다.","source":"S-7e7798beffb4"},{"label":"궁술","value":"통아와 짧은 솔레나리온 화살을 사용한다. 마리우스에게는 처음부터 어려운 화살을 주지 않고 기본 자세와 짧은 거리 사격부터 가르친다.","source":"S-023d1f373376"},{"label":"요리","value":"길러준 마녀의 조리법을 잊지 않으려 반복해서 요리한다. 혼자 먹을 양으로 시작했다가 동료가 찾아오는 것이 좋아 함께 먹을 음식을 만들게 된다.","source":"S-6940f4e80cb0"},{"label":"상실 이후","value":"엘라를 잃은 의뢰를 돌아보며 살아 돌아온 사람이 시신 수습과 다른 동료의 구조에 기여했다는 점을 짚는다. 슬픔과 모험심이 함께 남을 수 있다고 생각한다.","source":"S-358331196441"},{"label":"길드에서의 교류","value":"개구리 담요를 두르고 장난을 치거나 엘레나와 생활 이야기를 나눈다. 길드의 생활에 자신도 점차 익숙해졌다고 말한다.","source":"S-4b40f764ade7"}],"evaluation":[{"title":"자기 경험이 세상의 전부였던 때","text":"버림받았으니 자신도 아이를 버리겠다는 말에는 배워온 돌봄의 범위가 드러난다. 그 발언이 상처를 줄 수 있다는 점과, 꾸중과 폭력 앞에서 레마가 겁먹는 모습은 함께 남겨야 한다. 거친 생각을 지적하는 것과 두려움에 복종하게 만드는 것은 같은 일이 아니다.","source":"S-7e7798beffb4"},{"title":"자신 있는 분야에서는 정확한 선배가 된다","text":"활을 처음 잡는 마리우스에게 자세와 거리를 조정해주고 무엇이 어려운지를 설명한다. 평소의 주저하는 말투만으로 수동적인 사람이라 판단하기 어려운 이유다. 익힌 기술을 상대의 수준에 맞춰 나눌 줄 안다.","source":"S-023d1f373376"},{"title":"함께 먹는 시간이 만드는 소속감","text":"남이 찾아와 같이 먹자고 하는 것이 좋다는 말은 요리의 목적이 바뀌었음을 보여준다. 배를 채우는 생존 기술이 누군가와 머무르는 방법이 된다. 레시피에는 과거를 기억하는 마음과 현재의 관계가 함께 담긴다.","source":"S-6940f4e80cb0"},{"title":"살아남았다는 사실의 의미를 돌려주다","text":"도망쳤다는 죄책감을 느끼는 조니에게 귀환 덕분에 가능했던 구조와 수습을 말한다. 죽음을 가볍게 여기기보다 살아남은 사람이 한 일을 다시 보게 한다. 비극 뒤의 모험심까지 부정하지 않는 현실적인 위로다.","source":"S-358331196441"},{"title":"배려받은 경험을 이해하려는 사람","text":"자신이 무례하게 굴었는데도 동료들이 포기하지 않았던 이유를 고민한다. 단숨에 모든 가치관이 바뀌었다고 말할 수는 없지만, 당연하게 여기던 행동을 돌아보는 질문이 생겼다. 활을 반복해 쏘는 사이 관계에 대한 학습도 이어진다.","source":"S-358331196441"}],"traits":{"social":{"score":3,"text":"초면에는 주저하지만 음식과 활을 매개로 먼저 교류한다. 익숙해진 사람에게는 담요 장난과 농담을 보여주는 등 관계에 따라 표현이 달라진다.","source":"S-023d1f373376","supportingSources":["S-4b40f764ade7"]},"emotion":{"score":4,"text":"거절과 꾸중에 대한 두려움, 동료를 잃은 뒤의 혼란이 분명하게 나타난다. 불편한 감정을 숨기기만 하기보다 생각하고 말로 풀어보려 한다.","source":"S-7e7798beffb4","supportingSources":["S-358331196441"]},"altruism":{"score":4,"text":"사격을 가르치고 음식을 나누며 동료의 죄책감을 덜어주려 한다. 초기의 부족한 돌봄 경험과 이후의 구체적인 배려를 함께 반영했다.","source":"S-023d1f373376","supportingSources":["S-6940f4e80cb0","S-358331196441"]},"initiative":{"score":4,"text":"궁술을 꾸준히 연습하고 먼저 가르치겠다고 제안한다. 스스로 식사를 준비하고 다른 사람을 초대하는 생활의 주도성이 있다.","source":"S-023d1f373376","supportingSources":["S-6940f4e80cb0"]},"caution":{"score":3,"text":"사격 자세와 조리 순서에는 세심하지만 사람에게 하는 말은 경험의 한계로 거칠어질 때가 있다. 숙련된 일과 관계의 판단을 구별했다.","source":"S-023d1f373376","supportingSources":["S-7e7798beffb4"]},"bonds":{"score":4,"text":"자신을 포기하지 않은 동료들을 오래 생각하고 함께 먹는 시간을 좋아한다. 과거의 양육에 복잡한 감정이 있어도 배운 조리법은 계속 간직한다.","source":"S-358331196441","supportingSources":["S-6940f4e80cb0"]}},"relations":[{"name":"마리우스","text":"가족관 때문에 크게 충돌하기도 했지만, 이후 활을 가르치고 스튜를 나누며 친구가 된다. 한 장면만으로 관계를 고정하지 않았다.","source":"S-023d1f373376","characterId":"P-b6d81d634c6e"},{"name":"조니","text":"엘라를 잃은 모험 뒤 살아남은 사람의 역할과 앞으로의 모험을 이야기한 동료.","source":"S-358331196441","characterId":"P-8b864b607de4"},{"name":"라이아흐 미샤","text":"닭고기와 내장을 나누어 요리하고 차별과 길드의 편안함을 이야기하는 동료.","source":"S-6940f4e80cb0","characterId":"P-41ba4c5736e6"},{"name":"엘레나 레지아노","text":"개구리 담요 장난을 치고 길드 생활에 익숙해지는 이야기를 나눈 후배.","source":"S-4b40f764ade7","characterId":"P-89d5e8c6329e"}],"scenes":[{"source":"S-d4077642fb3c","text":"굶주린 채 찾아와 활을 잘 쏜다고 자신을 소개한 입회."},{"source":"S-7e7798beffb4","text":"자신이 배워온 가족관과 동료들의 반응이 충돌한 대화."},{"source":"S-023d1f373376","text":"활 수업에서 함께 만드는 스튜로 이어진 하루."},{"source":"S-358331196441","text":"새벽 사격 뒤 조니와 나누는 상실과 모험의 의미."},{"source":"S-6940f4e80cb0","text":"마녀의 레시피를 지키며 동료들과 닭 요리를 나눈 오후."},{"source":"S-4b40f764ade7","text":"개구리 담요를 두른 장난과 길드 생활 이야기."}],"asOf":"2026-08-11","sources":["S-d4077642fb3c","S-7e7798beffb4","S-023d1f373376","S-6940f4e80cb0","S-358331196441","S-4b40f764ade7"]},"P-cf2651679b0b":{"name":"엘타리온","updatedAt":"2026-10-01","tagline":"잃은 인연을 돌아보던 엘프가, 잔느라는 이름으로 자기 삶의 다음 장을 고른다.","tags":["유대가 깊은","상실을 오래 품는","홀로서기를 택한"],"profileNote":"엘타리온과 잔느 듀퐁 마르탱은 같은 인물의 기록으로 정리했다. 동료 린의 행동은 별개로 읽었으며, 친밀함을 원하는 마음과 상대의 동의를 침해한 행동을 구분해 평가했다.","facts":[{"label":"모습과 이름","value":"엘프로 서술되며 엘타리온이라는 이름을 오래 써왔다. 훗날 잔느 듀퐁 마르탱이라고 불러달라고 동료들에게 요청한다.","source":"S-65c77895108a"},{"label":"린","value":"늑대 모습으로 동행하는 린을 가족으로 여긴다. 과거를 숨긴 일로 밀어냈다가 자신을 떠나지 말라며 사과하고 서로를 껴안는다.","source":"S-c4f6910396c1"},{"label":"길드의 기억","value":"처음 동료들과 갔던 술집을 다시 찾으며 생기고 사라진 인연들을 돌아본다. 린과 캐너리를 추적했지만 흔적이 끊겨 찾지 못했던 일도 기억한다.","source":"S-cdf981d52895"},{"label":"이름을 바꾸던 날","value":"옹달샘에서 머리를 자르고 민 뒤 잔느라는 이름을 입에 올린다. 서술은 빼앗긴 것의 자리와 공허함을 강조하며 단순한 외모 변화 이상의 전환으로 그린다.","source":"S-8a17f8966781"},{"label":"홀로서기","value":"린을 당분간 임무에 데려가지 않고 자기 일을 찾겠다고 선언한다. 마나 방출 외의 마법 이론을 헤일리에게 배우고 싶다고 한다.","source":"S-65c77895108a"},{"label":"물려받은 이름","value":"한 달 뒤 잔느라는 이름을 준 노파를 떠올리며 고마움을 전한다. 이를 죽은 이름이 아니라 앞으로 살아갈 이름으로 받아들이려 한다.","source":"S-bc5ace55f906"}],"evaluation":[{"title":"버리지 말라는 말에 드러난 유대","text":"린에게 화냈던 일을 사과할 때 관계가 끊길 수 있다는 두려움이 강하게 나타난다. 평소의 동행은 편의만이 아니라 삶을 지탱하는 관계다. 상대를 밀어냈던 자신의 행동을 돌아보는 모습도 함께 보인다.","source":"S-c4f6910396c1"},{"title":"친밀함이 허락을 대신하지는 않는다","text":"폴라리스에게 사과하는 장면에서는 가까워지고 싶은 마음이 상대의 신체적 경계를 넘었다. 이를 귀여운 장난이나 연애의 증거로 포장하지 않았다. 상대가 당부한 선을 이해하고 지키는 일이 관계의 전제라는 문제를 남긴다.","source":"S-0206e11c6f77"},{"title":"장소에 쌓인 사람들의 기억","text":"같은 음식과 술을 고르며 처음의 동료들과 달라진 현재를 떠올린다. 캐너리의 행방을 끝내 알지 못했던 기억은 결말 없는 상실이다. 관계를 중시한다는 평가는 즐거운 교류뿐 아니라 사라진 사람을 돌아보는 장면에서도 나온다.","source":"S-cdf981d52895"},{"title":"붙잡던 관계에서 자기 일로 시선을 돌리다","text":"린과 늘 같이 다니는 방식을 잠시 바꾸고 마법 공부를 청한다. 이름과 머리 모양만 바꾸는 것이 아니라 일상에서 할 일을 고르는 변화다. 홀로서기는 동료를 모두 버리는 것이 아니라 관계 속에서도 자신의 활동을 찾는 방향이다.","source":"S-65c77895108a"},{"title":"지워낸 이름 뒤에 살아갈 이름을 남기다","text":"삭발 장면은 상실과 공허함이 강하지만 이후 독백은 감사와 앞으로의 삶을 말한다. 잔느라는 이름을 과거를 지우는 도구로만 보지 않고, 물려받은 의미를 살아낼 선택으로 읽을 수 있다.","source":"S-bc5ace55f906"}],"traits":{"social":{"score":4,"text":"술자리와 동료의 교류에 익숙하고 새로운 배움을 먼저 청한다. 다만 친근하게 다가가는 능력과 상대의 경계를 읽는 능력에는 차이가 있다.","source":"S-65c77895108a","supportingSources":["S-0206e11c6f77"]},"emotion":{"score":5,"text":"버림받을 두려움, 사라진 동료에 대한 그리움, 이름을 바꿀 때의 공허함이 강하게 드러난다. 감정이 중요한 생활의 전환으로 이어진다.","source":"S-c4f6910396c1","supportingSources":["S-8a17f8966781"]},"altruism":{"score":3,"text":"캐너리를 구하고 행방을 추적하는 등 동료를 위해 움직인다. 반면 가까운 상대의 의사를 침해한 기록도 있어 배려가 항상 일관되었다고 보지는 않았다.","source":"S-cdf981d52895","supportingSources":["S-0206e11c6f77"]},"initiative":{"score":4,"text":"스스로 새 이름을 요청하고 임무 방식과 배울 것을 바꾼다. 상실을 돌아보는 데서 그치지 않고 앞으로 할 일을 찾아 나선다.","source":"S-65c77895108a","supportingSources":["S-bc5ace55f906"]},"caution":{"score":2,"text":"감정과 친밀감이 앞서 관계의 선을 넘는 일이 있다. 이후 자신의 삶을 돌아보는 모습은 있지만, 모든 행동에서 신중함이 확보된 것은 아니다.","source":"S-0206e11c6f77","supportingSources":["S-65c77895108a"]},"bonds":{"score":5,"text":"린을 가족으로 여기고 떠난 동료와 이름을 준 사람의 기억을 간직한다. 홀로서기를 시작해도 관계의 의미 자체를 버리지는 않는다.","source":"S-c4f6910396c1","supportingSources":["S-cdf981d52895","S-bc5ace55f906"]}},"relations":[{"name":"린 (엘타리온의 동료)","text":"오랫동안 함께한 가족 같은 동료. 사과와 재결합을 거치며, 잔느로 홀로서기를 시작한 뒤에는 임무 동행을 잠시 멈추기로 한다.","source":"S-c4f6910396c1","characterId":"P-cf90597a7c66"},{"name":"폴라리스","text":"룸메이트이자 가까워지고 싶었던 상대. 허락 없이 행동한 일로 명확한 경고를 받았으며 관계의 경계가 중요한 문제로 남는다.","source":"S-0206e11c6f77","characterId":"P-5d0c306440d0"},{"name":"션","text":"잔느라는 이름과 홀로서기의 뜻을 밝힌 자리에서 함께 술을 마신 동료.","source":"S-65c77895108a","characterId":"P-3bbc4a823df9"},{"name":"헤일리","text":"마법 이론을 배우고 싶다고 청한 상대. 새 생활을 구체적인 배움으로 옮기는 계기가 된다.","source":"S-65c77895108a","characterId":"P-978c6ca18f92"}],"scenes":[{"source":"S-c4f6910396c1","text":"악몽에서 깨어 린에게 사과하고 붙잡는 아침."},{"source":"S-0206e11c6f77","text":"폴라리스가 관계의 선을 분명히 요구한 대화."},{"source":"S-cdf981d52895","text":"옛 술집과 골목에서 돌아오지 않는 동료를 떠올리는 산책."},{"source":"S-8a17f8966781","text":"머리카락을 밀고 잔느라는 이름을 말하는 옹달샘."},{"source":"S-65c77895108a","text":"홀로서기를 선언하고 마법 수업을 청하는 술자리."},{"source":"S-bc5ace55f906","text":"새 이름을 살아갈 이름으로 받아들이려는 독백."}],"asOf":"2026-06-17","sources":["S-65c77895108a","S-c4f6910396c1","S-cdf981d52895","S-8a17f8966781","S-bc5ace55f906","S-0206e11c6f77"]},"P-79263e0865dd":{"name":"존 (마법사)","updatedAt":"2026-10-01","tagline":"가난과 시행착오 속에서도, 마법으로 한 걸음 더 나아가는 즐거움을 놓지 않는다.","tags":["탐구에 몰두하는","차근차근 가르치는","소박한"],"profileNote":"탐정 존 마커스와 별개의 마법사 존이다. 존이 진행자로 등장하는 세션에서는 NPC와 진행 발화를 성격 근거에서 제외했고, 본인의 연구·수업·대화가 확인되는 장면을 중심으로 분석했다.","facts":[{"label":"전문 분야","value":"정신과 영혼을 탐구하는 학파를 소개하며 염동·환상 계열의 마법을 다룬다. 베스퍼에게 공명이동의 대상 지정과 집중의 원리를 설명한다.","source":"S-cb16fcbde236"},{"label":"학파와 연구","value":"싯다르타 학파의 논문이 인정받아 지원금이 나온다는 소식에 크게 기뻐한다. 자신의 의뢰 보수와 연구 보고, 학파의 형편을 함께 생각한다.","source":"S-5fbcd6985fd3"},{"label":"배움의 시작","value":"스승에게 문자부터 배웠다고 말한다. 첫 제자의 읽기 수준을 확인하고 그에 맞는 책과 수업 내용을 고른다.","source":"S-6a6e702fc91f"},{"label":"첫 제자","value":"베스퍼를 제자로 받아 염동의 기초부터 반복 연습을 시킨다. 익숙해지면 무거운 대상으로 옮기는 등 단계를 나누어 가르친다.","source":"S-6a6e702fc91f"},{"label":"의뢰에서의 역할","value":"카르타헤나 방어를 위해 해안 지형을 조사하고 마법진의 간격·재료·범위를 설계한다. 환영으로 적의 상륙과 함포 조준을 방해할 방법을 고민한다.","source":"S-2781952190ea"},{"label":"마법을 하는 이유","value":"논문을 다시 쓰는 와중에도 마법으로 나아가는 감각 자체를 자신의 별에 빗대어 말한다. 연구와 가르침을 계속할 비용 때문에 의뢰도 이어가려 한다.","source":"S-15a9e2c59ba5"}],"evaluation":[{"title":"결과만큼 알아가는 과정이 좋은 사람","text":"스텔라와 마법이 수단인지 목표인지 이야기하면서 계속 나아가는 감각을 중요하게 말한다. 논문이 엎어져도 관심 자체를 잃지 않는다. 궁핍한 생활과 별개로 탐구가 존의 삶을 움직이는 즐거움이다.","source":"S-15a9e2c59ba5"},{"title":"처음인 스승도 준비한다","text":"베스퍼를 가르칠 자격이 있는지 망설이면서도 여러 책을 꺼내 수준과 순서를 고른다. 완벽한 권위를 연기하기보다 준비하고 반응을 살피는 교사다. 자신의 문자 학습 경험도 초보자를 이해하는 배경이 된다.","source":"S-6a6e702fc91f"},{"title":"학문을 방어 계획으로 옮기다","text":"해안의 지형과 가진 재료를 함께 따지는 장면은 마법이 연구실 밖에서 어떻게 쓰이는지 보여준다. 강력한 주문 하나를 기대하기보다 여러 환상의 역할을 나누어 설계한다. 준비에 시간을 쓰는 실무적인 면이 있다.","source":"S-2781952190ea"},{"title":"제자의 강점에서 출발하는 가르침","text":"대상을 놓친 이유를 설명하고 집중 훈련을 권한다. 베스퍼가 가진 음유시인 경험도 활용하며 성취를 격려한다. 햄찌에게는 마법사만 대단한 것이 아니라 사람마다 다른 강점이 있다고 말해 능력의 우열에 매이지 않는다.","source":"S-cb16fcbde236"},{"title":"기쁨이 드러내는 헌신과 무리","text":"지원금 소식에 구르며 기뻐하고 제자와 학파에 할 일을 쏟아낸다. 그러나 닷새 밤샘 끝에 그대로 잠드는 모습도 있다. 성실함과 몰두는 장점이지만 자신의 몸을 돌보는 균형까지 잘 잡혀 있다는 뜻은 아니다.","source":"S-5fbcd6985fd3"}],"traits":{"social":{"score":3,"text":"학문과 식사를 계기로 대화를 편하게 이어가고 제자의 질문을 받는다. 활발한 교류 자체보다 공통 관심사와 가르침을 통해 관계가 열리는 편이다.","source":"S-15a9e2c59ba5","supportingSources":["S-cb16fcbde236"]},"emotion":{"score":3,"text":"평소에는 원리와 계획을 말하지만 연구가 인정받으면 온몸으로 기뻐한다. 감정이 없거나 냉담하기보다 관심사가 분명한 곳에서 표현이 커진다.","source":"S-5fbcd6985fd3","supportingSources":["S-15a9e2c59ba5"]},"altruism":{"score":4,"text":"제자의 수준에 맞춰 수업을 준비하고 공동 방어에 연구 능력을 쓴다. 학파와 제자를 위한 비용까지 생각하며 의뢰를 계속하려 한다.","source":"S-6a6e702fc91f","supportingSources":["S-2781952190ea","S-5fbcd6985fd3"]},"initiative":{"score":4,"text":"논문을 고쳐 쓰고 방어 도안을 만들며 새로운 수업을 준비한다. 확신이 없는 일도 자료를 모으고 시도하는 방식으로 앞으로 움직인다.","source":"S-2781952190ea","supportingSources":["S-6a6e702fc91f"]},"caution":{"score":4,"text":"마법의 범위와 조건을 따지고 기초를 안정적으로 유지하는 연습을 강조한다. 다만 연구에 몰두해 과로하는 점에서는 자기 관리의 한계가 보인다.","source":"S-cb16fcbde236","supportingSources":["S-2781952190ea","S-5fbcd6985fd3"]},"bonds":{"score":4,"text":"스승에게 배운 과정을 기억하고 제자와 학파의 미래를 자기 일처럼 챙긴다. 유대는 큰 감정 표현보다 가르침과 연구를 이어주는 행동으로 나타난다.","source":"S-6a6e702fc91f","supportingSources":["S-5fbcd6985fd3"]}},"relations":[{"name":"베스퍼 디 하운드","text":"처음 받아들인 제자. 기초 염동부터 집중과 빛 마법까지 단계적으로 가르치고 기존 경험을 수련에 활용한다.","source":"S-cb16fcbde236","characterId":"P-051c3e67e69c"},{"name":"스텔라 스타라이트","text":"야식을 나누며 마법을 시작한 계기와 지금의 목표를 이야기한 동료 마법사.","source":"S-15a9e2c59ba5","characterId":"P-e6655a038328"},{"name":"루체 루멘","text":"학파의 논문 승인과 지원금을 함께 기뻐하고 앞으로의 연구를 이야기한 동료.","source":"S-5fbcd6985fd3","characterId":"P-d8e7afee7c51"},{"name":"도리안 바이덴스","text":"연구 성과와 교수의 길, 제자 교육을 이야기한 동료. 밤샘 뒤 잠든 모습까지 지켜본다.","source":"S-5fbcd6985fd3","characterId":"P-dd70a1273f02"}],"scenes":[{"source":"S-6a6e702fc91f","text":"책더미를 앞에 두고 준비한 첫 제자의 염동 수업."},{"source":"S-15a9e2c59ba5","text":"야식 카레를 먹으며 마음속 별을 이야기하는 두 마법사."},{"source":"S-2781952190ea","text":"해안 지도를 만들고 방어용 환상 마법진을 설계하는 밤."},{"source":"S-cb16fcbde236","text":"집중의 원리와 각자의 강점을 짚어주는 수업."},{"source":"S-5fbcd6985fd3","text":"학파의 성과에 구르며 기뻐하다 잠드는 연구자."}],"asOf":"2026-09-22","sources":["S-cb16fcbde236","S-5fbcd6985fd3","S-6a6e702fc91f","S-2781952190ea","S-15a9e2c59ba5"]},"P-f400f584340f":{"name":"모카","updatedAt":"2026-10-01","tagline":"멋진 마녀를 꿈꾸는 아이가, 놀이와 작은 선물로 사람들을 돌본다.","tags":["호기심이 많은","정이 깊은","손으로 만드는"],"profileNote":"어린 인물의 말과 놀이를 어른의 성숙도 기준으로 재단하지 않았다. 마녀가 되고 싶은 꿈과 이미 숙련된 마법사라는 설정은 구분하며, 약을 가져오는 행동은 로그 속 돌봄으로만 소개한다.","facts":[{"label":"꿈","value":"자신을 마녀라고 부르며 멋진 마녀가 되고 싶어 한다. 다만 어떤 마녀가 멋진지 묻자 아직 모르겠다고 답하기도 한다.","source":"S-281a5b5643e7"},{"label":"성장 배경","value":"마녀가 자신을 주워 길러주었다고 말한다. 함께 약초와 꽃을 따러 다녔던 일을 기억한다.","source":"S-3825d87d4b6a"},{"label":"배우는 중인 지식","value":"피에르의 무를 잡초로 착각해 뽑았다가 작물과 약초를 배운다. 돕고 싶은 마음과 실제 지식 사이에 차이가 있다.","source":"S-b41edec9d71f"},{"label":"스승들","value":"라르손에게 숙제를 받으며 스노우도 마법 스승이라고 소개한다. 요리 대화에서는 물약 만드는 법을 스승에게 배웠다고 말한다.","source":"S-281a5b5643e7"},{"label":"돌봄과 선물","value":"다친 올리브에게 스승의 약과 직접 만든 쿠키를 가져다준다. 도움을 받은 아이에 머물지 않고 자신이 할 수 있는 일을 찾는다.","source":"S-9ac4f33f7d2b"},{"label":"아리차를 찾는 계획","value":"떠난 아리차를 찾아가겠다고 인형들과 작전회의를 한다. 스승과 폴라리스의 도움을 떠올리고 모나에게 모험 준비를 물어보려 한다. 실제 출발이나 재회가 확인된 장면은 아니다.","source":"S-e7cf678cc416"}],"evaluation":[{"title":"선의만으로는 잘할 수 없다는 첫 수업","text":"잡초를 뽑아 선물하려던 일이 작물을 망치는 결과가 된다. 모카의 호기심과 적극성은 분명하지만 지식과 결과를 미리 살피는 힘은 아직 자라는 중이다. 실수 뒤 배우는 장면까지 보아야 일방적인 사고뭉치로 남지 않는다.","source":"S-b41edec9d71f"},{"title":"상실을 모르는 아이가 아니라 배우는 아이","text":"엘라가 돌아오지 않는다는 말을 듣고도 감정을 정돈해 설명하지 못한다. 스노우는 힘들어해도 괜찮다고 말한다. 어린 말투 때문에 슬픔을 가볍게 읽기보다, 이해할 말과 함께 있어줄 사람이 필요한 순간으로 보았다.","source":"S-281a5b5643e7"},{"title":"어른보다 간단히 말하는 친구의 조건","text":"스텔라가 친구를 어떻게 느끼는지 묻자 함께 편히 이야기하고 챙겨주니 친구라고 답한다. 아리차가 곁에 없어도 함께 놀았던 기억은 남는다고 말한다. 복잡한 책임과 역할에 묶인 어른에게 관계의 직접적인 의미를 돌려준다.","source":"S-9b1369260074"},{"title":"작전놀이 속에 남아 있는 그리움","text":"아리차를 잡으러 가겠다는 장난스러운 회의는 떠난 친구를 다시 보고 싶은 마음에서 나온다. 혼자 모든 것을 할 수 있다고 우기기보다 도와줄 사람과 준비할 것을 떠올리는 부분도 있다. 놀이의 형태와 실제 욕구를 함께 읽을 수 있다.","source":"S-e7cf678cc416"},{"title":"배운 것을 곁에 있는 사람에게 쓰다","text":"올리브가 아프다는 말을 듣자 어디가 아픈지 묻고 쿠키와 약을 챙긴다. 자신이 줄 수 있는 것을 떠올리는 반응이 빠르다. 전문적인 치료 능력을 단정하지 않아도, 걱정을 행동으로 옮기는 마음은 분명하다.","source":"S-9ac4f33f7d2b"}],"traits":{"social":{"score":5,"text":"궁금한 일이 있으면 다가가 묻고 말동무를 자청한다. 스텔라에게 고민을 묻거나 다친 동료를 먼저 찾는 등 교류를 자연스럽게 시작한다.","source":"S-9b1369260074","supportingSources":["S-3825d87d4b6a"]},"emotion":{"score":4,"text":"기쁨과 불만, 그리움을 말과 놀이로 바로 드러낸다. 무거운 상실 앞에서는 설명이 짧아지기도 하므로 표현의 양만으로 감정의 깊이를 판단하지 않았다.","source":"S-281a5b5643e7","supportingSources":["S-e7cf678cc416"]},"altruism":{"score":4,"text":"돕겠다고 먼저 나서고 음식과 약을 가져온다. 지식이 부족해 엉뚱한 결과를 내기도 하지만 타인의 상태를 걱정하는 반응은 반복된다.","source":"S-9ac4f33f7d2b","supportingSources":["S-b41edec9d71f"]},"initiative":{"score":4,"text":"선물과 작전놀이를 스스로 시작하고 도움을 구할 사람을 찾는다. 아직 실행 능력은 제한적이어도 생각을 행동으로 바꾸려는 힘이 있다.","source":"S-e7cf678cc416","supportingSources":["S-9ac4f33f7d2b"]},"caution":{"score":2,"text":"호기심에 먼저 행동하고 작물과 잡초를 혼동하기도 한다. 모험 준비를 모나에게 묻겠다는 생각처럼 배우며 보완하는 단계다.","source":"S-b41edec9d71f","supportingSources":["S-e7cf678cc416"]},"bonds":{"score":5,"text":"떠난 아리차를 계속 친구로 여기고 다시 만날 방법을 궁리한다. 엘라의 부재를 묻고 길드에 남겠다고 하는 모습에서도 유대를 붙드는 마음이 드러난다.","source":"S-9b1369260074","supportingSources":["S-281a5b5643e7","S-e7cf678cc416"]}},"relations":[{"name":"스텔라 스타라이트","text":"친구의 뜻을 묻는 어른에게 자신의 기준으로 답하고 위로한 상대.","source":"S-9b1369260074","characterId":"P-e6655a038328"},{"name":"레마 캐롤라인","text":"마녀에게 길러진 공통점을 발견하고 수프를 함께 먹은 동료.","source":"S-3825d87d4b6a","characterId":"P-fec1db60d51e"},{"name":"브라그니르 라르손","text":"배움과 숙제를 주는 스승. 스노우와 함께 모카의 마녀 꿈 곁에 있는 어른이다.","source":"S-281a5b5643e7","characterId":"P-b551ad21c43a"},{"name":"스노우 글로우","text":"엘라의 부고 뒤 힘들어해도 괜찮다고 말해주고, 모카가 바라는 마녀가 무엇인지 묻는 스승.","source":"S-281a5b5643e7","characterId":"P-2bd2e06457e6"},{"name":"올리브","text":"다친 어깨를 걱정하며 약과 쿠키를 가져다준 동료.","source":"S-9ac4f33f7d2b","characterId":"P-6ba6a097816f"}],"scenes":[{"source":"S-b41edec9d71f","text":"무를 잡초로 착각한 선물에서 시작된 식물 수업."},{"source":"S-281a5b5643e7","text":"엘라가 돌아오지 않는다는 말을 듣는 별구경."},{"source":"S-3825d87d4b6a","text":"수프 곁에서 발견한 마녀에게 길러진 공통점."},{"source":"S-9b1369260074","text":"곁에 없어도 친구라고 스텔라에게 말하는 대화."},{"source":"S-e7cf678cc416","text":"아리차를 찾아가기 위한 인형들의 작전회의."},{"source":"S-9ac4f33f7d2b","text":"아픈 올리브에게 가져온 약과 쿠키."}],"asOf":"2026-09-06","sources":["S-281a5b5643e7","S-3825d87d4b6a","S-b41edec9d71f","S-9ac4f33f7d2b","S-e7cf678cc416","S-9b1369260074"]},"P-0322eff604c2":{"name":"아리차","updatedAt":"2026-10-01","tagline":"약속과 복수에 묶인 고양이가, 돌아갈 집을 얻고도 동료를 지키려 다시 떠난다.","tags":["능청스러운","약속에 엄격한","속정을 감추는"],"profileNote":"가벼운 장난과 가면 뒤의 가족 상실, 복수심을 함께 읽었다. 같은 프로필의 모나·페트라와는 다른 인물이다. 길드를 떠난 뒤의 기록에서도 아리차와 페트라의 선택을 구분했다.","facts":[{"label":"배경","value":"사막에서 살아온 고양이 데미간으로, 장대를 만드는 독백에서 서른세 해의 삶을 돌아본다. 금빛 털과 가면, 검은 옷으로 몸을 감추는 모습이 묘사된다.","source":"S-f5f061ddfc45"},{"label":"기술","value":"창과 장대를 다루며 함정과 자물쇠 기술에도 익숙하다. 레마에게 도적의 기술을 가르치고 사이먼의 옛 상자를 열어준다.","source":"S-cb7bdb9e3756"},{"label":"약속의 기억","value":"어린 시절 약속한 시간에 돌아오지 못했다는 이유로 가족이 살해되는 기억을 꿈꾼다. 이를 현재의 시간과 약속에 대한 강한 집착과 연결해 서술한다.","source":"S-62db450f7c53"},{"label":"복수의 대상","value":"만스라는 인물을 찾으려 칼그람에 몸담았다고 말한다. 과거를 다시 본 뒤에도 살아 있다면 죽이겠다는 결심을 유지한다.","source":"S-e28edb0cc081"},{"label":"길드라는 집","value":"장대를 다듬다가 길드를 자연스럽게 집이라고 부른다. 오래 떠돌던 끝에 동료와 돌아갈 장소가 생겼음을 자각한다.","source":"S-f5f061ddfc45"},{"label":"떠난 뒤","value":"동료들을 앞으로의 일에 끌어들이지 않으려 모카와 스텔라에게 쪽지를 남긴다. 사막에서 페트라를 만나 칼그람 대신 길드로 가도록 추천장을 써준다.","source":"S-cdd0637b76ce"}],"evaluation":[{"title":"정확한 시간 뒤에 남아 있는 공포","text":"식사 약속에도 정각을 지키는 태도는 단순한 깔끔함 이상이다. 가족을 잃은 기억에서 약속을 어긴 책임을 어린 자신에게 돌렸던 흔적과 연결된다. 신뢰를 중시하는 장점과 과거의 폭력이 남긴 굴레를 함께 보았다.","source":"S-6e24a999db1a"},{"title":"다정함을 놀림으로 감추다","text":"병문안 선물을 받고도 어리숙한 사람이라 놀리지만 과일을 먹으며 길드 사람들을 미워할 수 없다고 생각한다. 애정 표현이 부드럽지 않다고 애정이 없는 것은 아니다. 다만 모든 장난을 배려로 해석하는 대신, 실제 행동과 속생각이 함께 확인되는 장면을 근거로 삼았다.","source":"S-62db450f7c53"},{"title":"기술의 쓰임을 알지만 선을 넘기도 한다","text":"자물쇠를 여는 기술이 남을 도울 수 있다는 점을 보여준다. 동시에 다른 사람의 방문으로 연습하는 일은 사생활 침해다. 유능한 도적이라는 평가와 기술을 언제 정당하게 쓰는지는 별개의 질문으로 남는다.","source":"S-cb7bdb9e3756"},{"title":"새로운 집도 복수의 이유를 지우지는 못하다","text":"길드를 집이라고 느끼는 마음은 진실하지만 만스를 향한 결심도 사라지지 않는다. 과거에 다른 사정이 있을 수 있음을 알아도 복수를 택한다. 동료와의 일상이 곧 과거의 해결을 뜻하지 않는 복합적인 인물이다.","source":"S-e28edb0cc081"},{"title":"함께하고 싶어서 혼자 떠나다","text":"떠나며 미련이 없던 것이 아니라 잃는 게 두려워 아닌 척했다고 인정한다. 동료를 위험에 끌어들이지 않으려는 배려는 있지만 그들에게 선택을 나누지 않는 방식이기도 하다. 페트라에게는 자신이 떠난 집으로 향할 길을 마련해준다.","source":"S-cdd0637b76ce"}],"traits":{"social":{"score":4,"text":"장난과 기술 전수로 동료와 쉽게 접점을 만든다. 속사정을 모두 밝히지는 않지만 식사 약속을 받아들이고 친구라는 말을 주고받을 수 있다.","source":"S-6e24a999db1a","supportingSources":["S-cb7bdb9e3756"]},"emotion":{"score":4,"text":"겉으로는 능청스럽지만 가족의 기억과 복수, 떠날 때의 미련이 선택을 강하게 움직인다. 감정을 감추는 방식과 감정의 영향력을 구별했다.","source":"S-cdd0637b76ce","supportingSources":["S-62db450f7c53"]},"altruism":{"score":3,"text":"동료를 위험에서 떼어놓고 페트라에게 다른 길을 마련하지만, 속임수와 상대의 선택을 대신하는 방식도 쓴다. 돌봄과 통제가 섞인 면을 반영했다.","source":"S-cdd0637b76ce","supportingSources":["S-cb7bdb9e3756"]},"initiative":{"score":5,"text":"필요한 도구를 만들고 기술을 가르치며 자신의 목적을 따라 이동한다. 떠남과 새 동료의 행선지까지 직접 결정하고 실행한다.","source":"S-f5f061ddfc45","supportingSources":["S-cdd0637b76ce"]},"caution":{"score":4,"text":"장비를 꼼꼼히 손질하고 정체와 감정을 쉽게 노출하지 않는다. 다만 복수의 대상 앞에서는 복잡한 사정보다 결심을 우선하므로 모든 판단이 신중한 것은 아니다.","source":"S-f5f061ddfc45","supportingSources":["S-e28edb0cc081"]},"bonds":{"score":5,"text":"가족과 약속의 기억을 오래 품고, 길드에 미련이 있음을 인정하며 쪽지와 선물을 남긴다. 떠난다는 행동 자체가 관계에 무관심하다는 증거는 아니다.","source":"S-cdd0637b76ce","supportingSources":["S-f5f061ddfc45"]}},"relations":[{"name":"포말하우트","text":"부상 뒤 과일과 편지를 보내고 식사를 함께한 친구. 혼자 일하던 삶에서 마음을 나누는 교류로 이어진다.","source":"S-6e24a999db1a","characterId":"P-3ab8153acc27"},{"name":"레마 캐롤라인","text":"자물쇠와 함정 기술을 가르친 후배. 숙련될 때까지 반복하라고 조언한다.","source":"S-cb7bdb9e3756","characterId":"P-fec1db60d51e"},{"name":"사이먼 피터 포레스트","text":"옛 상자를 열어 성직 도구를 되찾아주고 몸을 부축한 동료. 농담과 실질적인 도움이 함께 있다.","source":"S-cb7bdb9e3756","characterId":"P-3ea4affc20fd"},{"name":"페트라","text":"사막에서 함께 일한 뒤 칼그람 대신 어설픈 용맹으로 보내려 한 새 동료. 내기에 속임수를 쓰고 추천장을 건넨다.","source":"S-cdd0637b76ce","characterId":"P-2eca709694d9"}],"scenes":[{"source":"S-f5f061ddfc45","text":"임시 장대를 만들며 처음으로 길드를 집이라 부르는 귀갓길."},{"source":"S-62db450f7c53","text":"가족을 잃은 악몽에서 깨어 발견한 과일 바구니."},{"source":"S-6e24a999db1a","text":"포말하우트와 친구로 잔을 든 첫 레스토랑 식사."},{"source":"S-cb7bdb9e3756","text":"도적 기술을 가르치고 오래된 상자를 열어주는 날."},{"source":"S-e28edb0cc081","text":"만스를 다시 본 뒤 복수를 포기하지 않겠다고 생각하는 독백."},{"source":"S-cdd0637b76ce","text":"조용한 출발과 사막에서 새 동료에게 건넨 추천장."}],"asOf":"2026-08-03","sources":["S-f5f061ddfc45","S-cb7bdb9e3756","S-62db450f7c53","S-e28edb0cc081","S-cdd0637b76ce","S-6e24a999db1a"]},"P-5d58655d55ce":{"name":"아마이 조","updatedAt":"2026-10-01","tagline":"자신의 이름과 몸을 묻는 예술가, 그리고 그 관계를 흉내 내며 돌아온 호프만의 이야기.","tags":["예술을 즐기는","정체성을 고민하는","인연을 소중히 하는"],"profileNote":"사용자 확인에 따라 아마이 조와 호프만을 한 시트에 수록했다. 다만 원문은 플리니오의 영혼, 호프만의 몸, 호프만이 조를 흉내 내는 시기를 구별한다. 아래 6축은 주로 7~8월의 조를 읽은 것이며, 9월 호프만의 행동을 같은 성격의 변화로 단순 합산하지 않았다.","facts":[{"label":"예술가","value":"붓과 캔버스를 들고 다니며 만나는 풍경과 사람에게서 영감을 얻는다. 리키의 얼음 마법에도 조각에 쓸 가능성을 먼저 떠올린다.","source":"S-6308cac02df3"},{"label":"언데드의 몸","value":"자신이 죽었던 날을 세계관 연도로 728년 5월 5일이라고 회상한다. 현재의 뼈만 남은 모습과 과거의 외모를 농담 섞어 비교한다.","source":"S-4e980630470a"},{"label":"마젤란토","value":"소중히 여기는 붓에 마젤란토라는 이름을 붙이고 말을 건다. 잃어버린 붓을 찾으려 소동을 벌일 정도로 애착이 크다.","source":"S-e3bf5c4106ac"},{"label":"몸과 영혼의 기록","value":"고틀리프의 연구 일지에는 플리니오의 영혼을 그를 죽인 호프만의 몸에 담았다는 내용이 나온다. 조는 그 기록과 자신이 누구인지에 혼란을 느낀다.","source":"S-2c3f22f2563c"},{"label":"호프만의 귀환","value":"9월에는 호프만이 조의 몸으로 돌아와 기억과 말투를 흉내 낸다고 서술된다. 허그에게 북부 여행담을 지어내며 정체를 숨긴다.","source":"S-94e3e2d27021"},{"label":"관계의 균열","value":"달라진 말투와 무례한 행동에 동료들이 의심을 품는다. 엘레나는 더 가까이 지내지 않겠다고 선언하고 바니도 선을 넘지 말라고 경고한다.","source":"S-c85df62a7a1d"}],"evaluation":[{"title":"영감이 먼저 보이는 시선","text":"새로운 마법을 보면 강함보다 어떤 작품을 만들 수 있을지 떠올린다. 붓에게 최근의 경험을 들려주는 모습도 모험을 창작과 연결하는 방식이다. 예술가라는 자기소개가 생활의 관심사로 이어진다.","source":"S-6308cac02df3"},{"title":"감사는 자신이 잘하는 것으로 돌려준다","text":"붓을 되찾는 데 허그의 도움을 받은 뒤 초상화를 그려준다. 말로 크게 자랑하는 모습 아래에 도움을 기억하고 응답하는 행동이 있다. 우스운 구조 소동이 두 사람의 인연을 만드는 계기가 된다.","source":"S-e3bf5c4106ac"},{"title":"정답을 들었어도 바로 자신이 되지는 못한다","text":"동료들이 어떤 이름으로 불리고 싶은지가 중요하다고 말해줘도 조는 곧바로 편해지지 않는다. 그 말을 수첩에 적고 언젠가 받아들일 날을 기다린다. 정체성의 문제를 조언 한마디로 해결하지 않는 점이 이 기록의 설득력이다.","source":"S-2c3f22f2563c"},{"title":"이름을 함께 묶어도 행동의 주체는 구별해야 한다","text":"호프만의 귀환은 단순히 여행 후 조가 거칠어진 장면이 아니다. 서술 자체가 조의 기억을 이용해 친구들을 속이는 행동을 보여준다. 앞선 예술가의 친화력과 이후의 무례함을 한 사람의 변덕으로 처리하면 이 이야기의 핵심 갈등을 놓친다.","source":"S-94e3e2d27021"},{"title":"흉내 낸 친밀함은 반응에서 어긋난다","text":"호프만은 말투를 흉내 내도 상대를 대하는 태도에서 차이를 드러낸다. 동료들이 불편함을 말하고 관계의 선을 긋는 장면은, 이름보다 함께 살아온 행동이 인물을 알아보게 한다는 점을 보여준다.","source":"S-c85df62a7a1d"}],"traits":{"social":{"score":4,"text":"초기의 조는 먼저 인사하고 상대의 능력과 작품 이야기를 꺼낸다. 어색한 정적을 느끼기도 하지만 새로운 경험과 교류를 즐긴다. 호프만의 위장된 사교는 이 점수에 합산하지 않았다.","source":"S-6308cac02df3","supportingSources":["S-e3bf5c4106ac"]},"emotion":{"score":4,"text":"과거의 죽음과 붓에 대한 애착, 자신의 몸과 이름을 알게 된 혼란이 드러난다. 농담을 한다고 내면의 동요가 작은 것은 아니다.","source":"S-2c3f22f2563c","supportingSources":["S-4e980630470a"]},"altruism":{"score":3,"text":"도움을 준 허그에게 그림을 선물하고 상대에게 격려를 건넨다. 관찰한 범위에서는 주변 사람에 대한 호의가 중심이며 광범위한 자기희생을 단정할 근거는 적다.","source":"S-e3bf5c4106ac","supportingSources":["S-6308cac02df3"]},"initiative":{"score":4,"text":"원하는 풍경을 찾아 그림을 그리고 모델을 청하며 잃은 붓을 직접 찾는다. 혼란스러운 날에도 훈련으로 생활을 이어가려 한다.","source":"S-e3bf5c4106ac","supportingSources":["S-2c3f22f2563c"]},"caution":{"score":2,"text":"눈앞의 영감과 소중한 붓에 마음이 쏠려 몸 일부까지 나무에 걸리는 소동을 낸다. 반면 정체성 문제에서는 성급히 결론내리지 않고 기록을 남긴다.","source":"S-e3bf5c4106ac","supportingSources":["S-2c3f22f2563c"]},"bonds":{"score":4,"text":"붓과 기억에 애착을 두고 친구의 도움과 조언을 간직한다. 이후 호프만이 이 인연을 흉내 내는 장면은 오히려 조가 쌓은 관계의 존재를 드러낸다.","source":"S-2c3f22f2563c","supportingSources":["S-e3bf5c4106ac"]}},"relations":[{"name":"가델랏 허그","text":"붓을 찾는 소동에서 도움을 받고 초상화를 선물한 친구. 훗날 호프만은 이 친밀함을 이용해 의심을 피한다.","source":"S-e3bf5c4106ac","characterId":"P-6a1a99e98a44"},{"name":"리키","text":"마법과 예술을 이야기한 동료. 성별이 달라 보였던 이유를 듣고 얼음 조각의 가능성을 떠올린다.","source":"S-6308cac02df3","characterId":"P-bb4b9d047737"},{"name":"엘레나 레지아노","text":"호프만의 무례한 언행에 관계를 멀리하겠다고 선언한 동료. 앞선 조와의 인연을 그대로 이어갈 수 없는 갈등이 생긴다.","source":"S-c85df62a7a1d","characterId":"P-89d5e8c6329e"},{"name":"바니 캐시","text":"달라진 행동을 의심하고 선을 넘지 말라고 경고한 상대.","source":"S-c85df62a7a1d","characterId":"P-4da9d3645aad"}],"scenes":[{"source":"S-e3bf5c4106ac","text":"잃은 붓과 나무에 걸린 몸, 초상화로 끝나는 첫 소동."},{"source":"S-6308cac02df3","text":"붓에게 근황을 이야기하다 리키와 예술을 나누는 밤."},{"source":"S-4e980630470a","text":"죽었던 날을 문득 떠올리는 짧은 독백."},{"source":"S-2c3f22f2563c","text":"연구 일지를 통해 몸과 영혼의 사연을 알게 된 조."},{"source":"S-94e3e2d27021","text":"조를 흉내 내며 허그와 술을 마시는 호프만."},{"source":"S-c85df62a7a1d","text":"달라진 말과 행동이 관계의 균열로 드러난 모닥불."}],"asOf":"2026-09-13","sources":["S-6308cac02df3","S-4e980630470a","S-e3bf5c4106ac","S-2c3f22f2563c","S-94e3e2d27021","S-c85df62a7a1d"]},"P-b551ad21c43a":{"name":"브라그니르 라르손","updatedAt":"2026-10-01","tagline":"맥주와 물약으로 길드를 채우는 연금술사, 호기심의 사고와 생활의 쓸모를 함께 만든다.","tags":["실험을 즐기는","호탕한","생활에 가까운"],"profileNote":"위험한 실험도 만드는 즐거움만으로 미화하지 않았다. 다른 세계에서 만난 라르손의 가족사는 현재 라르손의 이력과 구분했다. 물약과 독에 관한 내용은 효능이나 제조법 대신 이야기 속 역할만 소개한다.","facts":[{"label":"일과 생활","value":"길드 공방에서 양조와 연금술을 한다. 물약뿐 아니라 향수와 비누처럼 생활에 쓰는 물건도 만든다.","source":"S-ccb786affece"},{"label":"방패 제작","value":"마인의 뿔을 활용하려다 뒤틀림의 무지개 펜던트로 다른 세계의 자신을 만난다. 그곳의 대장장이 라르손에게 기술을 빌려 방패를 완성한다.","source":"S-cfbe1a405e3d"},{"label":"실험 사고","value":"무한히 늘어나는 초콜릿을 만들려던 실험이 괴물을 낳는다. 동료들이 다치며 구조한 뒤 라르손은 사과하고 보상금을 지급한다.","source":"S-e9c629fbe181"},{"label":"위험 취급","value":"위험한 물약을 만들 때 보호장구를 갖추고 사용한 도구에 해골 표시를 한다. 안전을 전혀 모르는 인물은 아니지만 표지만으로 위험이 완전히 사라지는 것도 아니다.","source":"S-9c3cf237ae44"},{"label":"주문과 조정","value":"멜의 향수 주문을 맞추려 지속성과 향의 균형을 고친다. 마리아의 변화와 사이먼의 부재를 남아 있는 약의 쓰임과 연결해 생각한다.","source":"S-bc5234b4b558"},{"label":"고향","value":"고향 청년 베르겐이 의뢰 중 죽었다는 소식을 듣고 휴가를 내어 요툰헤이멘으로 돌아간다. 부모에게 귀환 인사를 하는 기록이 있다.","source":"S-0038e82a0fce"}],"evaluation":[{"title":"일상이 곧 제작의 소재다","text":"물약의 효능만 좇지 않고 맥주, 향기, 씻는 데 필요한 비누까지 만든다. 동료가 직접 쓰고 반응하는 물건들이 공방과 길드의 생활을 이어준다. 연금술은 라르손에게 특수한 사건과 평범한 하루 모두에 쓰이는 기술이다.","source":"S-ccb786affece"},{"title":"실험의 대가는 옆 사람도 치른다","text":"초콜릿 실험의 실패로 구조에 나선 동료들까지 다친다. 사과와 보상은 책임을 인정하는 행동이지만 이미 생긴 피해를 없애지는 못한다. 호탕하고 유쾌한 모습과 별개로 호기심이 공동체에 부담을 줄 수 있음을 보여준다.","source":"S-e9c629fbe181"},{"title":"조심할 줄 아는 것과 늘 안전한 것은 다르다","text":"보호장구와 도구 표시는 위험을 인식하고 있음을 보여준다. 그 사실이 다른 실험에서의 무리한 판단까지 지워주지는 않는다. 라르손의 신중성은 높거나 낮은 한 단어보다 실험마다 들쭉날쭉한 것으로 읽었다.","source":"S-9c3cf237ae44"},{"title":"남은 물건으로 알아차리는 사람의 부재","text":"마리아가 변하고 사이먼이 보이지 않자 준비한 약이 남는다. 사람을 그리워하는 긴 독백 대신 공방의 재고가 달라진 관계를 알려준다. 주문받은 향수를 고쳐 완성하는 일상은 그 변화 속에서도 이어진다.","source":"S-bc5234b4b558"},{"title":"떠들썩함 밖의 귀향","text":"고향 청년의 죽음을 듣고 실제로 휴가를 내어 돌아간다. 길 위의 전투 흔적과 부모에게 하는 인사가 짧게 이어진다. 늘 농담하는 인상만으로 상실이나 고향에 무심한 사람이라 볼 수 없는 장면이다.","source":"S-0038e82a0fce"}],"traits":{"social":{"score":4,"text":"물건을 권하고 술과 음식을 나누며 쉽게 말을 건다. 공방의 작업도 혼자만의 연구에 닫혀 있기보다 동료들과 거래하고 교류하는 접점이 된다.","source":"S-ccb786affece","supportingSources":["S-9cf4a6f61025"]},"emotion":{"score":3,"text":"평소에는 웃음과 농담이 앞서지만 사고 뒤에는 사과하고 고향의 부고에는 움직인다. 감정의 영향은 장황한 표현보다 대응과 생활의 변화에 나타난다.","source":"S-0038e82a0fce","supportingSources":["S-e9c629fbe181"]},"altruism":{"score":3,"text":"동료에게 물건을 만들고 사고의 책임을 보상하려 한다. 동시에 자신의 실험이 주변에 위험을 전가한 일도 있어 생활의 기여와 위험을 함께 반영했다.","source":"S-e9c629fbe181","supportingSources":["S-ccb786affece"]},"initiative":{"score":5,"text":"새 재료와 도구를 실험하고 원하는 결과가 나오도록 배합과 제작을 바꾼다. 위험한 재료를 가공할 방법을 찾아 다른 가능성까지 시도한다.","source":"S-cfbe1a405e3d","supportingSources":["S-bc5234b4b558"]},"caution":{"score":2,"text":"보호장구를 쓰고 표시를 남길 줄은 알지만, 무리한 실험이 실제 사고로 이어진다. 안전 의식이 전혀 없다는 뜻이 아니라 위험 판단의 일관성이 부족하다는 평가다.","source":"S-e9c629fbe181","supportingSources":["S-9c3cf237ae44"]},"bonds":{"score":4,"text":"동료의 상태와 필요에 맞춰 물건을 만들고 고향의 상실에도 응답한다. 스승으로서 모카의 숙제를 챙기는 일도 관계를 지속하는 방식이다.","source":"S-0038e82a0fce","supportingSources":["S-bc5234b4b558","S-281a5b5643e7"]}},"relations":[{"name":"모카","text":"숙제와 배움을 주는 스승으로 만난다. 엘라의 부고를 듣는 자리에서도 곁에 있는 어른이다.","source":"S-281a5b5643e7","characterId":"P-f400f584340f"},{"name":"존 (마법사)","text":"초콜릿 사고에서 구조에 나서고 이후 공방 출입을 말린 동료.","source":"S-e9c629fbe181","characterId":"P-79263e0865dd"},{"name":"엘타리온","text":"초콜릿 실험 사고를 수습하러 나선 동료. 라르손의 실험이 공동체의 일이 된 장면이다.","source":"S-e9c629fbe181","characterId":"P-cf2651679b0b"},{"name":"햄 주니어","text":"만든 비누를 길드원 할인가로 산 동료. 작은 생활용품을 통해 공방과 길드의 일상이 이어진다.","source":"S-ccb786affece","characterId":"P-c6b8c16e2fba"}],"scenes":[{"source":"S-cfbe1a405e3d","text":"다른 세계의 자신과 손을 맞잡아 완성한 방패."},{"source":"S-e9c629fbe181","text":"무한 초콜릿 실험이 구조 작전이 되어버린 공방."},{"source":"S-9c3cf237ae44","text":"보호장구와 경고 표시가 등장하는 위험한 작업."},{"source":"S-bc5234b4b558","text":"남은 약을 돌아보다 라일락 향을 다시 맞추는 날."},{"source":"S-0038e82a0fce","text":"고향 청년의 부고를 듣고 떠나는 귀향."},{"source":"S-ccb786affece","text":"동료에게 초록 비누를 파는 평범한 공방의 하루."}],"asOf":"2026-09-23","sources":["S-ccb786affece","S-cfbe1a405e3d","S-e9c629fbe181","S-9c3cf237ae44","S-bc5234b4b558","S-0038e82a0fce","S-9cf4a6f61025","S-281a5b5643e7"]},"P-77d4478f4f51":{"name":"시안 던 브링어","updatedAt":"2026-10-01","tagline":"구하지 못한 사람을 검 끝에 새기는 검사, 지키려는 마음을 나누는 법은 아직 어렵다.","tags":["책임을 짊어지는","수련에 성실한","관계 표현에 서툰"],"profileNote":"동료의 상실을 겪은 시점별로 읽고, 라이티티아와 가까워지는 과정뿐 아니라 9월 26일 이별 갈등까지 포함했다. 상대를 지키려는 선의와 그 상대가 실제로 받은 상처를 구분했다.","facts":[{"label":"검의 목표","value":"검의 끝이라는 목표를 좇아 반복 수련한다. 동료를 구하다 팔을 잃은 뒤에도 자신이 찾은 실마리가 정답인지 단정하지 않고 훈련을 이어간다.","source":"S-6088af40e4d7"},{"label":"잃은 팔","value":"왼팔을 잃고 의수를 쓴다. 의수가 자신의 원래 팔을 대신하는 것은 아니라는 감각과, 자신에게 목숨을 넘겨준 이름 모를 마법사의 기억이 남아 있다.","source":"S-6088af40e4d7"},{"label":"상실과 자책","value":"마리아를 구하지 못한 일에서 자신이 더 빨랐어야 했다고 자책한다. 술로 피하기보다 맨정신으로 있고 싶다며 검을 다시 든다.","source":"S-28c547d1af01"},{"label":"길드와 책임","value":"토르번에게 운영 업무도 동료들의 모험을 가능하게 하는 중요한 일이라고 말한다. 사이먼의 소식과 책임의 무게를 나누며 친구로 지내자는 제안을 받아들인다.","source":"S-5c80169e53df"},{"label":"라이티티아와의 친밀함","value":"함께 대화하는 시간이 좋고 만나고 싶었다고 말한다. 서로의 모험과 두려움을 듣고, 혼자가 아니라는 생각을 나눈다.","source":"S-5c8d568a52c7"},{"label":"최근의 관계 갈등","value":"토팔에서 돌아온 뒤 상대가 원하는 답을 제대로 주지 못하고 이별을 말하는 갈등이 생긴다. 말을 돌이키려 따라가지만 라이티티아가 쓰러지며 기록이 끝나므로 회복이나 화해를 확정하지 않았다.","source":"S-8c99316e2a4d"}],"evaluation":[{"title":"수련은 목표이자 슬픔을 버티는 방식","text":"팔과 동료를 잃은 뒤에도 검을 든다. 강해지려는 의지는 분명하지만 그 안에는 다시 구하지 못할까 두려운 마음도 있다. 반복 훈련을 오직 성실함의 증거로만 보면 자신을 몰아붙이는 면을 놓친다.","source":"S-6088af40e4d7"},{"title":"모든 죽음을 자신의 속도로 설명하려 하다","text":"마리아의 죽음 앞에서 더 빨랐다면 달라졌을 것이라고 생각한다. 동료들은 각자의 방식으로 다른 관점을 내놓지만 시안은 쉽게 받아들이지 못한다. 책임감이 큰 만큼 자기 능력으로 바꿀 수 없는 결과까지 짊어지는 경향이 보인다.","source":"S-28c547d1af01"},{"title":"검 밖의 책임도 인정하는 사람","text":"토르번의 서류 작업을 사소한 뒷일로 보지 않고 모험을 가능하게 하는 일로 존중한다. 서로 무거운 마음을 나눈 뒤 친구가 되자는 말에 응한다. 강함을 증명하는 자리 밖에서도 동료로 연결될 수 있음을 보여준다.","source":"S-5c80169e53df"},{"title":"상대의 이야기를 들어주고 싶은 진심","text":"라이티티아에게 말하기 힘들면 하지 않아도 되지만 자신도 들어주고 싶다고 한다. 위로를 받는 위치에만 머물지 않고 같은 자리를 내주려는 태도다. 모닥불의 친밀함은 수련으로만 풀던 마음에 다른 통로를 만든다.","source":"S-5c8d568a52c7"},{"title":"선의만으로 상대의 답을 대신할 수 없다","text":"최근 갈등에서는 선택권을 준다는 말이 상대에게 이미 정한 이별을 떠넘기는 것으로 들린다. 시안도 뒤늦게 그 말을 놓쳤음을 깨닫는다. 사람을 지키려는 의지가 가까운 사람의 요청을 제대로 듣는 능력과 항상 같지는 않다는 한계가 드러난다.","source":"S-8c99316e2a4d"}],"traits":{"social":{"score":3,"text":"예의를 갖춰 인사하고 익숙한 동료에게 먼저 다가간다. 가까운 사람을 기다렸다는 마음도 말하기 시작하지만 사적인 표현에는 망설임이 있다.","source":"S-5c8d568a52c7","supportingSources":["S-5c80169e53df"]},"emotion":{"score":4,"text":"상실과 죄책감이 훈련과 관계의 판단에 깊이 작용한다. 표현은 절제되어도 동료를 잃는 일에 크게 흔들린다.","source":"S-28c547d1af01","supportingSources":["S-8c99316e2a4d"]},"altruism":{"score":4,"text":"동료를 구하려다 팔을 잃고 이후에도 다른 사람의 괴로움을 듣고자 한다. 다만 보호를 위한 판단이 상대의 뜻과 어긋나는 경우도 함께 반영했다.","source":"S-6088af40e4d7","supportingSources":["S-5c8d568a52c7","S-8c99316e2a4d"]},"initiative":{"score":4,"text":"수련을 이어가고 어려운 대화를 시작하며 잘못한 말을 돌이키려 행동한다. 정답을 몰라도 멈추기보다 자신이 할 수 있는 일을 찾는다.","source":"S-6088af40e4d7","supportingSources":["S-8c99316e2a4d"]},"caution":{"score":3,"text":"판단을 거듭 고민하지만 관계에서는 오래 생각한 말도 상처를 낼 수 있다. 신중하려는 태도와 상대에게 미칠 결과를 정확히 이해하는 능력은 구별했다.","source":"S-8c99316e2a4d","supportingSources":["S-5c8d568a52c7"]},"bonds":{"score":5,"text":"이름조차 모르는 은인과 잃은 동료를 기억하고 가까운 사람의 안위를 자신의 일로 여긴다. 관계를 중요하게 여기는 정도와 관계를 잘 유지하는 능력은 같지 않다.","source":"S-6088af40e4d7","supportingSources":["S-5c80169e53df","S-8c99316e2a4d"]}},"relations":[{"name":"라이티티아","text":"서로의 두려움을 듣고 가까워진 상대. 최근에는 이별과 선택을 둘러싼 말이 상처가 되었으며 뒤따른 화해는 확인되지 않았다.","source":"S-8c99316e2a4d","characterId":"P-fae6af716ea2"},{"name":"토르번 팔켄하인","text":"상실과 책임을 이야기하고 친구로 지내기로 한 동료. 운영자의 보이지 않는 일도 존중한다.","source":"S-5c80169e53df","characterId":"P-7ba611cf90be"},{"name":"션","text":"상실 뒤 쉬라고 권하고, 잃은 팔과 현재를 받아들이도록 말해준 선배.","source":"S-5c8d568a52c7","characterId":"P-3bbc4a823df9"},{"name":"델타인","text":"마리아를 잃은 밤 서로 다른 방식으로 책임과 죽음을 이야기한 동료. 위로의 방식이 곧바로 맞아떨어지지는 않는다.","source":"S-28c547d1af01","characterId":"P-c93f55c91873"}],"scenes":[{"source":"S-6088af40e4d7","text":"왼팔을 잃은 감각과 이름 모를 은인을 떠올리는 검술 수련."},{"source":"S-28c547d1af01","text":"마리아의 죽음을 자신의 부족함으로 받아들이는 밤."},{"source":"S-5c80169e53df","text":"토르번과 책임을 내려놓고 친구로 이야기하려는 시간."},{"source":"S-5c8d568a52c7","text":"라이티티아에게 만나고 싶었다고 말한 모닥불."},{"source":"S-403fcf1fea73","text":"귀환 후 안전과 선택을 둘러싸고 갈등한 빨래터."},{"source":"S-8c99316e2a4d","text":"이미 한 말을 되돌리려 뒤따라간 시안과 쓰러진 라이티티아."}],"asOf":"2026-09-26","sources":["S-6088af40e4d7","S-28c547d1af01","S-5c80169e53df","S-5c8d568a52c7","S-8c99316e2a4d","S-403fcf1fea73"]},"P-f310b84f8f20":{"name":"님드 알 쿠라이시","updatedAt":"2026-10-01","tagline":"죄인이라는 말을 견뎌온 성기사가, 신앙의 뜻을 타인을 돕는 행동 속에서 다시 묻는다.","tags":["말없이 돕는","신앙을 성찰하는","감정을 안으로 품는"],"profileNote":"검열된 출생과 정체의 세부사항은 추측하지 않았다. 죄인이라는 표현은 님드에게 가해진 평가와 그의 내면을 그린 서술이며, 그가 실제로 죄를 지었다는 판정이 아니다. 기도의 대상과 경험은 이 RP의 세계관 안에서 정리했다.","facts":[{"label":"성기사의 이력","value":"위험한 공격과 방어의 최일선에서 싸운 성기사. 고향 테네브란의 재앙 때 파견을 요청하고 경비대장으로 병력을 정비하며 외부 지원을 구한다.","source":"S-412be9514d39"},{"label":"과거의 상처","value":"어릴 때부터 정체를 받아들여지지 못하고 죄인이라는 비난을 들었다고 서술된다. 사랑하던 사람에게 비밀이 알려진 뒤 이별한 기억도 있다.","source":"S-412be9514d39"},{"label":"길드에 오기까지","value":"동료들을 잃고 무너진 자리에서 에레모시스와 의무와 생존을 논한다. 시신을 수습한 뒤 어설픈 용맹의 동료로 받아들여진다.","source":"S-e55b3e9bed13"},{"label":"일상의 신앙","value":"새벽에 몸을 씻고 기도한 뒤 말없이 장작을 팬다. 신앙은 특정 전투 장면뿐 아니라 반복되는 생활의 리듬이기도 하다.","source":"S-779ac011c978"},{"label":"치유와 나눔","value":"잘린 오른팔의 치료를 다른 종교의 교회에 부탁한다. 돈 대신 모두의 주님께 바치라는 말을 듣고 자신의 의뢰 보수로 음식을 사 빈민들에게 나눈다.","source":"S-07ebbbd8fac1"},{"label":"가족과의 연결","value":"사촌 와르다는 지출을 걱정하면서도 집에 들러달라고 편지를 쓴다. 님드는 이를 읽고 혼자 방에서 오래 운다.","source":"S-e1d64ff4bc66"}],"evaluation":[{"title":"침묵은 냉담함과 다르다","text":"엘라의 귀를 치료하는 자리에서 말은 몇 마디뿐이지만 필요한 도움은 바로 보탠다. 갑옷과 침묵으로 자신을 감춘 채로도 다른 사람의 고통에 응답할 수 있다. 사교성의 낮음과 이타성의 낮음을 혼동하지 않게 하는 장면이다.","source":"S-c537b6d2e9f7"},{"title":"타인의 신앙에서 받은 도움을 사람에게 돌려주다","text":"자존심이 상해도 다른 교회의 치료를 구하고, 그곳에서 들은 말을 빈민에게 음식을 주는 행동으로 해석한다. 신앙은 서로 다른 대상을 믿는다는 구분을 넘어 실제로 누구를 살피는가라는 질문으로 넓어진다.","source":"S-07ebbbd8fac1"},{"title":"정답을 듣는 것과 깨닫는 것을 구분하다","text":"모두의 주님이 누구인지 다시 물으려다가 스스로 찾지 못하면 답을 들어도 소용없다고 생각한다. 신앙의 언어를 그대로 반복하는 데 머물지 않고 자신의 이해를 요구하는 모습이다. 의심 없는 확신만이 이 인물의 믿음은 아니다.","source":"S-0d16b19e1035"},{"title":"약한 자리를 건드리는 유혹에 거절로 답하다","text":"기도 속 시험은 상실과 자존심, 재물과 생존을 건드린다. 님드는 이를 거부하고 다시 기도를 잇는다. 모든 고통이 해결되었다는 결말이 아니라 흔들리는 중에도 자신이 따를 원칙을 고르는 장면이다.","source":"S-52496c1323e2"},{"title":"잔소리 속 애정을 받았을 때","text":"와르다의 편지는 돈과 귀가를 따지면서도 사랑과 그리움을 명확히 담고 있다. 님드는 길게 답하는 대신 혼자 운다. 외부의 비난을 내면화한 과거와 함께 읽으면, 가족이 여전히 자신을 기다린다는 말이 얼마나 크게 닿는지 보인다.","source":"S-e1d64ff4bc66"}],"traits":{"social":{"score":2,"text":"짧게 답하고 다시 침묵하는 장면이 반복된다. 필요한 도움과 의사 표현은 하지만 자신을 드러내며 교류하는 데에는 거리를 둔다.","source":"S-c537b6d2e9f7","supportingSources":["S-779ac011c978"]},"emotion":{"score":4,"text":"겉으로 절제되어도 죄의식과 가족의 편지에 강하게 흔들린다. 감정이 드러나는 장소가 주로 독백과 혼자 있는 방이라는 점을 반영했다.","source":"S-e1d64ff4bc66","supportingSources":["S-412be9514d39"]},"altruism":{"score":5,"text":"부상한 동료의 치료를 돕고 자신의 몫으로 빈민의 식사를 마련한다. 보호와 나눔을 자신의 시간·힘·돈으로 실행하는 근거가 있다.","source":"S-07ebbbd8fac1","supportingSources":["S-c537b6d2e9f7"]},"initiative":{"score":4,"text":"고향의 재앙에 파견을 요청하고 필요한 치료와 구호를 직접 찾아 실행한다. 조용한 태도가 행동의 수동성을 뜻하지 않는다.","source":"S-412be9514d39","supportingSources":["S-07ebbbd8fac1"]},"caution":{"score":3,"text":"지휘와 신앙에서는 원칙과 절차를 살피지만 구조 현장에서는 마차를 놓지 못해 함께 추락하기도 한다. 위험을 인식하는 능력과 자신을 위험에서 떼어내는 판단에 차이가 있다.","source":"S-7bf2d0f5fa9c","supportingSources":["S-412be9514d39"]},"bonds":{"score":4,"text":"잃은 동료를 수습하고 가족의 편지에 마음이 무너진다. 유대를 중요하게 여기지만 집에 자주 돌아가지 못하는 등 표현과 유지에는 어려움이 남는다.","source":"S-e1d64ff4bc66","supportingSources":["S-e55b3e9bed13"]}},"relations":[{"name":"에레모시스","text":"테네브란에서 무너진 자신을 일으켜 세우고 길드로 맞아들인 동료. 생존과 의무를 두고 격한 대화를 나눈다.","source":"S-e55b3e9bed13","characterId":"P-d6e0d1eb8b63"},{"name":"마리아 아나이스 에스더","text":"엘라의 귀 접합을 서로의 신성으로 함께 도운 동료. 다른 힘이 충돌하지 않고 협력한다.","source":"S-c537b6d2e9f7","characterId":"P-c9505ea97ebc"},{"name":"엘라","text":"다친 귀를 회복시키는 데 도움을 준 동료. 치료를 마친 뒤에는 다시 조용히 물러선다.","source":"S-c537b6d2e9f7","characterId":"P-cc79cb0e0b1e"},{"name":"머챈트 마이아","text":"절벽으로 기우는 마차에서 함께 추락했다가 동료의 도움으로 살아 돌아온 상대. 모든 짐과 말을 구하지는 못했다.","source":"S-7bf2d0f5fa9c","characterId":"P-92738ae601c0"}],"scenes":[{"source":"S-412be9514d39","text":"죄의식과 잃은 연인, 고향으로의 파견을 다룬 과거."},{"source":"S-e55b3e9bed13","text":"에레모시스와 생존의 의무를 논하며 동료를 수습하는 테네브란."},{"source":"S-c537b6d2e9f7","text":"몇 마디 말과 신성으로 엘라의 치료를 돕는 자리."},{"source":"S-07ebbbd8fac1","text":"치료받은 팔로 빈민에게 나눌 음식을 마련하는 하루."},{"source":"S-e1d64ff4bc66","text":"사촌의 편지 한 통을 읽고 혼자 우는 밤."},{"source":"S-52496c1323e2","text":"기도 속에서 세 가지 유혹을 거절하는 시험."}],"asOf":"2026-08-13","sources":["S-412be9514d39","S-e55b3e9bed13","S-779ac011c978","S-07ebbbd8fac1","S-e1d64ff4bc66","S-c537b6d2e9f7","S-0d16b19e1035","S-52496c1323e2","S-7bf2d0f5fa9c"]},"P-55e987e3c831":{"name":"브랜","updatedAt":"2026-10-01","tagline":"망가진 장비를 다시 쓰게 만들며, 동료들이 살아 돌아올 생활을 받치는 제작자.","tags":["실용적인","꼼꼼한","일로 돕는"],"profileNote":"사용자가 브렌으로 부른 인물이며 게시된 원문 표기는 브랜이다. 작업과 동료 응대가 풍부한 반면 가족사와 깊은 내면 독백은 이번 근거에서 확인하지 못했다. 평가와 6축은 반복되는 제작·협업 장면의 행동에 한정했다.","facts":[{"label":"생업과 이력","value":"대장장이 일을 생업으로 해왔고 농민병과 용병 경험도 있다고 말한다. 길드 대장간을 활용하다 숀에게 길드의 대장장이로 일하라는 제안을 받는다.","source":"S-1807c202cc1a"},{"label":"제작 범위","value":"무기와 갑옷뿐 아니라 버클·리벳 같은 작은 부품도 고친다. 숀의 체격과 착용감을 확인하며 장비를 조정한다.","source":"S-1807c202cc1a"},{"label":"재료의 재사용","value":"망가진 검을 분해해 재질과 탄성을 살피고 쓸 만한 강철을 분류한다. 미리 준비한 판재로 새 방패를 만드는 등 재료와 시간을 아낀다.","source":"S-298ccc627353"},{"label":"연구 도구","value":"존의 철판과 룬 도장 주문을 받아 제작한다. 납품과 대금을 정리하고 길드 동료에게 할인을 적용한다.","source":"S-db3a967b65db"},{"label":"물건보다 사람","value":"아버지에게 받은 아서의 검을 수리해주되 장비는 몸 대신 지킬 대상이 아니라 소모품이라고 당부한다. 망가지면 다시 오라고 말한다.","source":"S-1943b460d332"},{"label":"생활 설비","value":"허그의 낙타들을 위해 기존 마구간 옆에 임시 천막과 울타리를 만드는 방안을 낸다. 영구 증축과 당장의 잠자리 마련을 구분한다.","source":"S-1f8db1c46da1"}],"evaluation":[{"title":"작은 불편을 구체적으로 해결한다","text":"갑옷이 헐겁고 핀이 튀어나온 문제를 하나씩 고친다. 멋진 새 무기만이 제작의 성과는 아니다. 착용자가 편하게 움직이고 다치지 않도록 만드는 세부 작업에서 실용적인 배려가 드러난다.","source":"S-1807c202cc1a"},{"title":"추억이 있는 물건도 몸보다 앞설 수 없다","text":"아서가 아버지의 검을 되찾아 기뻐하는 마음을 존중하면서도, 몸을 희생하며 검을 지키지 말라고 한다. 물건을 오래 쓰게 만드는 기술자이기에 오히려 물건은 다시 고칠 수 있다고 말해줄 수 있다.","source":"S-1943b460d332"},{"title":"고치는 과정을 함께하게 한다","text":"에스텔이 아교를 바르고 풀무질을 돕는 동안 방패를 완성한다. 작업은 전문가 혼자만의 비밀이 아니라 함께 기여할 수 있는 과정이 된다. 비용 처리도 설명해 상대가 불필요하게 부담을 느끼지 않도록 한다.","source":"S-298ccc627353"},{"title":"가능한 규모의 해법부터 만든다","text":"낙타의 잠자리를 당장 영구 건물로 만들기보다 임시 천막을 제안한다. 필요한 공간과 시간, 나중의 허가를 함께 고려한다. 도움을 주면서도 지금 해결할 수 있는 범위를 구분하는 현실감이 있다.","source":"S-1f8db1c46da1"},{"title":"일만 하는 인물로 닫히지는 않는다","text":"레마와 케이크를 나누다가 장비 이야기를 시작하곤 잠깐 일 이야기를 멈추자고 웃는다. 식사를 함께 준비하고 정리하는 모습은 직업적 성실함 바깥에도 편안한 교류가 있음을 보여준다.","source":"S-c863ba4de9c6"}],"traits":{"social":{"score":3,"text":"먼저 음식을 나누고 의뢰자의 말을 편하게 받아준다. 화려한 사교보다는 식사와 작업을 함께하며 가까워지는 방식이다.","source":"S-c863ba4de9c6","supportingSources":["S-1807c202cc1a"]},"emotion":{"score":2,"text":"확인한 장면에서는 작은 웃음과 만족을 표현하며 작업에 차분히 집중한다. 내면의 감정이 적다는 단정이 아니라 공방에서 드러나는 표현 강도에 관한 평가다.","source":"S-298ccc627353","supportingSources":["S-c863ba4de9c6"]},"altruism":{"score":4,"text":"동료의 장비와 생활 설비를 고치고 몸을 우선하라고 조언한다. 유급 노동이라는 사실과 그 과정에서 상대의 안전과 편의를 챙기는 태도는 함께 볼 수 있다.","source":"S-1943b460d332","supportingSources":["S-1f8db1c46da1"]},"initiative":{"score":4,"text":"시설을 보고 스스로 제작을 시작하고 필요한 수리 방법을 제안한다. 주문을 실제 납품과 사용 가능한 결과로 이어가는 힘이 있다.","source":"S-1807c202cc1a","supportingSources":["S-db3a967b65db"]},"caution":{"score":5,"text":"재료를 검사하고 착용감을 확인하며 임시 작업과 영구 공사를 구별한다. 작업 장면에서 비용·안전·용도를 순서대로 살피는 행동이 반복된다.","source":"S-298ccc627353","supportingSources":["S-1f8db1c46da1","S-1943b460d332"]},"bonds":{"score":3,"text":"동료의 물건을 맡고 필요하면 다시 찾아오라고 말하며 지속적인 협업을 만든다. 깊은 사적 관계를 추측하기보다 반복되는 신뢰와 도움을 근거로 평가했다.","source":"S-1943b460d332","supportingSources":["S-db3a967b65db"]}},"relations":[{"name":"숀","text":"길드 대장장이 일을 제안하고 몸에 맞지 않는 장비의 수리를 맡긴 동료.","source":"S-1807c202cc1a","characterId":"P-5c88d36f51cd"},{"name":"아서 나이츠베인","text":"아버지에게 받은 검을 맡긴 동료. 수리 후 물건보다 자신의 몸을 지키라고 당부한다.","source":"S-1943b460d332","characterId":"P-9d7bf25dbba3"},{"name":"존 (마법사)","text":"연구용 철판과 룬 도장을 주문한 동료. 제작과 환영 마법 설명을 주고받는다.","source":"S-db3a967b65db","characterId":"P-79263e0865dd"},{"name":"에스텔 벨라시타","text":"새 방패를 만드는 과정을 함께한 동료. 필요한 장비를 걱정 없이 다시 구할 수 있도록 돕는다.","source":"S-298ccc627353","characterId":"P-b522cca806d0"},{"name":"가델랏 허그","text":"낙타의 잠자리를 부탁한 동료. 현재 가능한 임시 시설부터 함께 만든다.","source":"S-1f8db1c46da1","characterId":"P-6a1a99e98a44"}],"scenes":[{"source":"S-c863ba4de9c6","text":"길드 시설을 묻고 레마와 케이크를 나누는 신입의 식사."},{"source":"S-1807c202cc1a","text":"숀의 장비를 고치며 길드 대장장이 일을 제안받는 날."},{"source":"S-1943b460d332","text":"추억의 검을 수리하고 몸이 먼저라고 당부하는 배웅."},{"source":"S-db3a967b65db","text":"마법사의 연구를 위한 룬 도장 제작과 결제."},{"source":"S-298ccc627353","text":"에스텔과 함께 완성한 새 방패."},{"source":"S-1f8db1c46da1","text":"낙타 두 마리를 위한 천막과 울타리 작업."}],"asOf":"2026-09-26","sources":["S-1807c202cc1a","S-298ccc627353","S-db3a967b65db","S-1943b460d332","S-1f8db1c46da1","S-c863ba4de9c6"]},"P-89d5e8c6329e":{"name":"엘레나 레지아노","updatedAt":"2026-10-01","tagline":"누군가에게 도움이 되고 싶어 농장을 떠난 사람, 모험의 책임을 혼자 짊어지지 않는 법을 배워간다.","tags":["돕고 싶어 하는","스스로에게 엄격한","애정을 배우는"],"profileNote":"8월 입회부터 9월 말 귀환 후의 대화까지 읽었다. 자책하는 독백은 엘레나 자신의 평가이며, 그 말을 객관적인 무능이나 도덕적 결함으로 확정하지 않았다. 사랑을 얻은 뒤에도 의뢰의 상실과 갈등은 계속된다.","facts":[{"label":"출신과 입회","value":"농장 출신으로 가족의 걱정을 뒤로하고 길드를 찾아온다. 긴장해 말을 더듬지만 직접 가입 의사를 밝히고 션의 면담을 거친다.","source":"S-b8ac904d6442"},{"label":"모험의 동기","value":"더 많은 사람을 돕고 싶어 모험을 선택했다. 고향의 외모에 대한 험담과 가족의 반대를 꿈에서 되짚으며 잘 살아 돌아가겠다고 다짐한다.","source":"S-15042067edb8"},{"label":"전투와 도끼","value":"부모에게 받은 도끼를 잃은 뒤 아키라의 도끼를 선물받는다. 새 도끼에 적응하려 베어와 대련하고 부상과 치료를 거친 뒤 다시 겨룬다.","source":"S-e36897d1df2c"},{"label":"가족에게 보낸 소식","value":"가족에게 길드의 친절과 포투아에서의 일을 편지로 알린다. 당시의 두려움과 자신을 믿어준 동료에 대한 감사를 함께 적는다.","source":"S-212335fb7928"},{"label":"델타인과의 관계","value":"연인이 된 뒤 서로 사랑의 감정을 알아가기로 한다. 원치 않는 행동을 말하고 상대가 좋다는 마음도 직접 표현한다.","source":"S-250c1e1d96d1"},{"label":"최근의 고민","value":"토팔 귀환 뒤 마리나의 죽음과 동료의 상처를 떠올리며 자책한다. 9월 말에는 선물을 돌리다가 숀에게 신입과 선임이 함께 책임지는 관계라는 조언을 듣는다.","source":"S-ffd2261a1bae"}],"evaluation":[{"title":"겁을 내면서도 문을 넘는다","text":"입회 장면은 자신감 넘치는 출발과 거리가 있다. 눈치를 보고 말을 더듬으면서도 원하는 바를 밝히고, 다친 델타인의 발목을 고정해준다. 엘레나의 용기는 겁이 없는 성격보다 겁난 뒤에도 하는 행동에서 드러난다.","source":"S-b8ac904d6442"},{"title":"선한 의도가 결과의 무게를 없애주지 않는다","text":"첫 의뢰를 떠올리며 상대의 사연과 자신의 폭력을 함께 돌아본다. 책임을 외면하지 않으려는 마음은 있지만, 곧 자신 전체를 비난하는 독백으로 번진다. 반성할 수 있다는 장점과 자신을 몰아붙이는 고통이 같은 자리에서 생긴다.","source":"S-c91ce1c1108f"},{"title":"사랑을 받는 데에도 연습이 필요하다","text":"델타인과 서로의 감정을 알아가자고 말하고 싫은 행동에는 경계를 설명한다. 애정은 상대를 무조건 받아주는 일이 아니라 두 사람이 편한 방식을 함께 찾는 과정으로 묘사된다. 이 관계가 이전의 상처를 한 번에 지운다고 볼 수는 없다.","source":"S-250c1e1d96d1"},{"title":"돌아온 뒤에도 의뢰는 끝나지 않는다","text":"피 묻은 옷을 빨다가 죽은 사람과 남은 사람을 떠올린다. 에스텔의 자비를 받아들이지 못하고 대화에서 지쳐 떠나는 모습은, 서로 선의를 가졌어도 같은 경험을 같은 방식으로 견디지는 못한다는 점을 보여준다.","source":"S-403fcf1fea73"},{"title":"도움을 빚으로만 세지 않기","text":"신세를 진 사람에게 선물을 마련하는 성실함이, 자신은 늘 짐이라는 생각과 붙어 있다. 숀의 조언은 길드를 서로 실패를 감당하는 관계로 다시 보게 한다. 아직 문제가 해결된 결말은 아니지만, 엘레나가 배워갈 방향이 구체적으로 제시된다.","source":"S-ffd2261a1bae"}],"traits":{"social":{"score":3,"text":"낯선 자리에서는 위축되지만 직접 인사하고 함께 훈련하며 관계를 늘린다. 익숙해진 상대에게는 장난과 애정을 표현한다.","source":"S-b8ac904d6442","supportingSources":["S-250c1e1d96d1"]},"emotion":{"score":5,"text":"의뢰의 기억과 타인의 말, 사랑받는 기쁨이 생각과 행동에 강하게 영향을 준다. 감정이 풍부하다는 평가이며 임상적 판단은 아니다.","source":"S-c91ce1c1108f","supportingSources":["S-403fcf1fea73"]},"altruism":{"score":4,"text":"타인을 돕고 싶어 길드를 택하고 다친 사람을 돌보며 받은 도움을 돌려주려 한다. 실제 전투에서의 갈등과 타인에게 날카로워지는 장면도 함께 남아 있다.","source":"S-b8ac904d6442","supportingSources":["S-ffd2261a1bae"]},"initiative":{"score":4,"text":"가족의 반대에도 입회하고 대련을 청하며 가족에게 직접 소식을 쓴다. 자책하는 말만으로 행동까지 수동적인 사람으로 볼 수 없다.","source":"S-e36897d1df2c","supportingSources":["S-212335fb7928"]},"caution":{"score":3,"text":"다른 사람을 다치게 하지 않으려 도끼날을 감싸고 말의 영향을 고민한다. 다만 행동 뒤에 걱정이 커지는 경우도 있어 많이 고민한다는 사실을 높은 사전 판단력과 같게 보지는 않았다.","source":"S-e36897d1df2c","supportingSources":["S-c91ce1c1108f"]},"bonds":{"score":5,"text":"가족에게 인정받고 동료에게 도움이 되며 연인과 가까워지고 싶은 마음이 지속된다. 관계의 변화와 상실을 자기 삶의 큰 문제로 받아들인다.","source":"S-15042067edb8","supportingSources":["S-250c1e1d96d1","S-ffd2261a1bae"]}},"relations":[{"name":"델타인","text":"서로 사랑을 알아가기로 한 연인. 상대를 돌보는 동시에 자신이 원치 않는 행동도 설명한다.","source":"S-250c1e1d96d1","characterId":"P-c93f55c91873"},{"name":"아키라 베르데미켄","text":"잃어버린 도끼를 대신할 무기와 전사로 살아가는 조언을 건넨 동료.","source":"S-5ebcba6de26e","characterId":"P-ee0c9d156dde"},{"name":"베어","text":"대련하다 다친 자신을 어머니의 유품까지 바쳐 치료한 동료. 엘레나는 그 값을 갚으려 한다.","source":"S-e36897d1df2c","characterId":"P-fd3900116fbc"},{"name":"숀","text":"혼자 길드의 짐이라 여기던 마음에 선임도 함께 책임진다는 관점을 건넨 동료.","source":"S-ffd2261a1bae","characterId":"P-5c88d36f51cd"},{"name":"에스텔 벨라시타","text":"토팔 귀환 뒤 선의와 자비를 두고 충돌한 동료. 서로의 마음을 이해하는 일이 아직 남아 있다.","source":"S-403fcf1fea73","characterId":"P-b522cca806d0"}],"scenes":[{"source":"S-b8ac904d6442","text":"긴장 속에서 문을 두드리고 델타인의 발목을 돌보는 입회 첫날."},{"source":"S-c91ce1c1108f","text":"첫 의뢰의 죄책감을 안고 홀로 강가로 달려간 밤."},{"source":"S-250c1e1d96d1","text":"서로 사랑을 알아가기로 약속하는 델타인과의 대화."},{"source":"S-e36897d1df2c","text":"새 도끼에 적응하려 시작한 대련과 베어의 치유."},{"source":"S-403fcf1fea73","text":"피 묻은 빨래 앞에서 의뢰의 상처와 갈등이 되살아난 날."},{"source":"S-ffd2261a1bae","text":"보답할 선물을 준비하다 숀에게 함께 책임진다는 말을 듣는 장면."}],"asOf":"2026-09-28","sources":["S-b8ac904d6442","S-15042067edb8","S-e36897d1df2c","S-212335fb7928","S-250c1e1d96d1","S-ffd2261a1bae","S-c91ce1c1108f","S-403fcf1fea73","S-5ebcba6de26e"]},"P-ee0c9d156dde":{"name":"아키라 베르데미켄","updatedAt":"2026-10-01","tagline":"강함으로 세상을 읽는 오니 전사, 거친 말 사이로 가르침과 도움을 건넨다.","tags":["직접적인","강함을 좇는","몸으로 돕는"],"profileNote":"델타인과 같은 프로필로 이어 쓴 장면은 대사의 주체를 구별했다. 서툰 골기아어를 곧 지능의 부족으로 해석하지 않았고, 전투 경험에서 나오는 판단과 타인을 위험에 놓는 거친 태도를 함께 살폈다.","facts":[{"label":"종족과 자부심","value":"오니이며 자신의 부족에서 대전사라고 말한다. 강함을 중시하고 어머니 신을 모신다고 설명한다.","source":"S-d7442eea2b58"},{"label":"전사의 이력","value":"페트라에게 절벽을 오르며 힘을 기른 일과 형제들, 가짜 아버지라 부르는 상대를 이긴 일을 이야기한다.","source":"S-8ec0cb3af8cc"},{"label":"무기와 교육","value":"창의 종류에 따라 가능한 동작을 구별하고 찌르기의 자세와 상대가 파고드는 위험을 설명한다. 조·아이다·올리브에게 실제 동작을 보여준다.","source":"S-8ec0cb3af8cc"},{"label":"다이어울프","value":"거대한 다이어울프를 힘으로 제압하고 길들인다. 데스티나가 위험을 호소해도 싸움과 도전을 기준으로 응수한다.","source":"S-992b563f366b"},{"label":"동료 구조","value":"쓰러진 아카쿠를 보고 혈마법과 물약으로 도우려 한다. 업고 가다 넘어져 부상이 더 생기지만 옷을 찢어 부목을 돕고 치료사를 찾는다.","source":"S-8fe34d0a1ee6"},{"label":"선물","value":"가족에게 받은 도끼를 잃은 엘레나에게 자신의 큰 도끼를 준다. 무기의 의미는 앞으로 스스로 찾으라고 말한다.","source":"S-5ebcba6de26e"}],"evaluation":[{"title":"말은 짧아도 전투 지식은 구체적이다","text":"창을 무작정 세게 쓰라고 하지 않는다. 창날의 형태와 공격 방법, 상대가 가까이 들어오는 상황을 연결해서 설명한다. 낯선 언어의 발음과 실제로 익힌 기술을 분리해 읽어야 하는 인물이다.","source":"S-8ec0cb3af8cc"},{"title":"강함이라는 기준의 한계","text":"다이어울프와 데스티나를 대할 때 고통과 위험을 배움의 일부로 쉽게 받아들인다. 자신이 견딜 수 있는 것을 다른 존재도 감당해야 한다고 보는 태도가 드러난다. 용맹함과 주변의 안전을 충분히 살피는 능력은 별개다.","source":"S-992b563f366b"},{"title":"좋은 말보다 먼저 몸을 움직인다","text":"아카쿠를 놀리는 말투는 거칠지만 실제로 치료를 시도하고 옮기며 자신의 옷도 찢는다. 구조 중 실수로 상처가 더해진 사실까지 함께 있어, 마음이 있다고 늘 능숙하게 돕는 것은 아니라는 점도 드러난다.","source":"S-8fe34d0a1ee6"},{"title":"동료가 자기 길을 만들게 하는 선물","text":"도끼를 주며 특별한 의미를 떠맡기지 않고 엘레나가 앞으로 의미를 만들라고 한다. 무기를 주는 행동과 도구에 의존하지 말라는 조언이 함께 간다. 거친 표현 안에 후배를 전사로 대하는 존중이 있다.","source":"S-5ebcba6de26e"},{"title":"소란 속에서 놓치지 않는 실제 위협","text":"모두가 낯선 여인의 말에 집중할 때 뒤에서 가방을 노리는 공범을 알아본다. 붙잡은 상대는 경비에게 넘긴다. 늘 충동적으로 싸우기만 한다는 인상으로는 설명되지 않는 관찰과 대응이다.","source":"S-863cd61e8ac4"}],"traits":{"social":{"score":3,"text":"음악 소리를 따라오고 함께 식사하며 신입을 가르친다. 다만 거친 호칭과 강함을 기준으로 한 평가가 상대를 불편하게 만들기도 한다.","source":"S-d7442eea2b58","supportingSources":["S-5ebcba6de26e"]},"emotion":{"score":3,"text":"싸움의 흥분과 실망, 동료에게 느끼는 친근함을 숨기지 않는다. 확인한 장면에서는 긴 독백보다 즉각적인 말과 몸짓으로 드러난다.","source":"S-8fe34d0a1ee6","supportingSources":["S-5ebcba6de26e"]},"altruism":{"score":3,"text":"부상자를 옮기고 무기를 선물하며 도둑을 막는다. 동시에 상대의 두려움을 가볍게 여기고 위험에 노출시키는 행동도 있어 호의만으로 높게 평가하지 않았다.","source":"S-8fe34d0a1ee6","supportingSources":["S-992b563f366b"]},"initiative":{"score":5,"text":"직접 싸우고 시범을 보이며 문제를 발견하면 곧바로 나선다. 기술과 행동으로 상황을 바꾸는 경향이 뚜렷하다.","source":"S-8ec0cb3af8cc","supportingSources":["S-863cd61e8ac4"]},"caution":{"score":3,"text":"전투 기술과 수작을 읽는 판단은 구체적이다. 반면 구조와 동물 길들이기에서는 타인의 안전을 충분히 고려하지 않는 장면이 있다.","source":"S-863cd61e8ac4","supportingSources":["S-992b563f366b","S-8fe34d0a1ee6"]},"bonds":{"score":4,"text":"상대의 이름을 자기 방식으로 부르며 돕고 가르치는 관계를 이어간다. 친밀함은 다정한 어휘보다 무기와 시간, 행동을 내주는 데서 보인다.","source":"S-5ebcba6de26e","supportingSources":["S-8ec0cb3af8cc"]}},"relations":[{"name":"엘레나 레지아노","text":"새 무기를 찾는 동료에게 도끼를 선물하고 전사로 살아갈 조언을 준다.","source":"S-5ebcba6de26e","characterId":"P-89d5e8c6329e"},{"name":"라이아흐 아카쿠","text":"쓰러졌을 때 구조하고 시장에서는 소매치기를 막아준 동료. 거친 말투와 실제 도움이 함께 나타난다.","source":"S-863cd61e8ac4","characterId":"P-96ab98d2591c"},{"name":"페트라","text":"서로의 팔과 고향, 전사로 자란 경험을 나눈 상대. 다른 경험을 강함이라는 공통 관심으로 연결한다.","source":"S-8ec0cb3af8cc","characterId":"P-2eca709694d9"},{"name":"아마이 조","text":"창을 배우러 온 동료. 무기의 형태와 사용법부터 설명해준다.","source":"S-8ec0cb3af8cc","characterId":"P-5d58655d55ce"},{"name":"데스티나","text":"다이어울프 앞에서 도전과 안전, 동물을 대하는 방식을 두고 충돌한 상대.","source":"S-992b563f366b","characterId":"P-d2afca5de258"}],"scenes":[{"source":"S-d7442eea2b58","text":"음악 소리를 따라와 오니의 문화와 강함을 이야기한 날."},{"source":"S-992b563f366b","text":"다이어울프 길들이기를 두고 데스티나와 실랑이한 숲."},{"source":"S-8fe34d0a1ee6","text":"습격당한 아카쿠를 구하려다 서툰 구조가 이어진 사건."},{"source":"S-8ec0cb3af8cc","text":"무기의 차이를 설명하고 창술을 보여주는 수업."},{"source":"S-5ebcba6de26e","text":"엘레나에게 도끼와 새로운 의미를 만들 기회를 건넨 선물."},{"source":"S-863cd61e8ac4","text":"소란 뒤의 소매치기를 발견해 경비에게 넘긴 시장."}],"asOf":"2026-09-05","sources":["S-d7442eea2b58","S-8ec0cb3af8cc","S-992b563f366b","S-8fe34d0a1ee6","S-5ebcba6de26e","S-863cd61e8ac4"]},"P-a161473e74e0":{"name":"리엔 에이라스","updatedAt":"2026-10-01","tagline":"동화 같은 결말을 꿈꾸면서도, 지금 곁에 있는 사람에게 필요한 온도를 살피는 정령술사.","tags":["다정한","회복을 믿는","상대를 살피는"],"profileNote":"리엔 에이라스 한 사람의 시트다. 네레이드는 함께하는 정령이며 별개의 인물로서 서술된 행동을 구별했다. 밝은 말투 아래에 나타나는 굶주림과 가족의 상실도 함께 읽되, 이를 성격의 단일 원인으로 단정하지 않았다.","facts":[{"label":"프로필","value":"하얀 머리의 하프엘프 소년으로 서술된다. 인간의 수명을 가진 하프엘프라고 직접 말한다.","source":"S-d0224128eaef"},{"label":"네레이드","value":"물의 정령 네레이드와 함께한다. 물로 열을 식혀 간호하고, 달빛을 받아 반짝이는 모습을 보여주는 등 힘을 생활과 교류에도 쓴다.","source":"S-01a17ea5bb32"},{"label":"가족","value":"어머니가 자신을 낳다 돌아가셨고 아버지도 세상을 떠났다고 말한다. 아버지가 읽어주던 동화의 행복한 결말을 기억한다.","source":"S-01a17ea5bb32"},{"label":"모험의 바람","value":"어린 시절 먹을 것을 훔치다 맞았던 경험을 이야기하며 길드의 안전한 식사를 반긴다. 동화 속 영웅이 되고 싶다는 꿈도 말한다.","source":"S-01a17ea5bb32"},{"label":"간호","value":"몸살을 앓는 아도니스의 머리를 받치고 네레이드로 열을 식힌다. 말하지 말라는 요청에는 조용히 돌보는 방식으로 바꾼다.","source":"S-073520fdafec"},{"label":"시간에 대한 생각","value":"시간을 넘어지고 부서져도 다시 일어날 기회를 주는 가치라고 설명한다. 끝이 있다는 사실이 오히려 위로가 되기도 한다고 말한다.","source":"S-d0224128eaef"}],"evaluation":[{"title":"밝음은 힘든 일을 몰라서 생긴 것이 아니다","text":"안전한 밥과 행복한 동화의 결말을 이야기하는 자리에서 굶주림과 가족의 죽음도 나온다. 소박한 바람이 과거와 이어지면서 밝은 인상이 더 구체적인 의미를 얻는다. 다만 과거가 모든 다정함을 설명한다고 단정할 필요는 없다.","source":"S-01a17ea5bb32"},{"title":"위로를 거창한 정답으로 만들지 않는다","text":"엘타리온에게 자신의 시간관을 말하면서도 잘 모르는 문제라고 여지를 남긴다. 상대를 격려하되 과제를 대신 끝냈다고 하지 않는다. 다시 일어설 수 있다는 관점은 긴 수명과 상실을 두려워하는 동료에게 다른 시야를 준다.","source":"S-d0224128eaef"},{"title":"도움의 방식은 상대가 정한다","text":"아도니스가 말하지 말라고 하자 입을 닫고 간호한다. 이후 훈련장에서도 혼자 있을 시간이 필요한지 물은 뒤 물러난다. 가까이 있고 싶은 마음보다 상대가 지금 받을 수 있는 도움을 확인하는 태도가 반복된다.","source":"S-ce2db3299dcf"},{"title":"아픈 마음을 없애는 것을 어른됨이라 여기다가","text":"아룡 새끼에게 고통을 준 일을 괴로워하며 어른이 되면 이런 일에 덜 아플지 묻는다. 모나의 경험을 듣고 위로를 나누는 대화는, 성숙을 무감각함으로만 이해하지 않을 가능성을 연다. 고민을 숨기기보다 타인과 나눌 수 있다는 점도 특징이다.","source":"S-93c01cc4d806"},{"title":"작은 아름다움을 함께 보는 관계","text":"네레이드의 묘기와 스노우의 눈 마법을 서로 보여주고 감탄한다. 힘의 우열을 겨루기보다 함께 보고 즐기는 시간이 중심이다. 정령술은 전투 수단뿐 아니라 사람 사이를 이어주는 언어가 된다.","source":"S-01a17ea5bb32"}],"traits":{"social":{"score":4,"text":"반갑게 인사하고 음식과 마법을 나누며 상대를 칭찬한다. 처음 보는 아름다운 존재 앞에서는 긴장하지만 교류를 피하지는 않는다.","source":"S-93c01cc4d806","supportingSources":["S-01a17ea5bb32","S-8fbdeb37a30a"]},"emotion":{"score":4,"text":"아름다움에 크게 반응하고 생명에게 준 고통을 마음에 둔다. 밝게 이야기하는 중에도 가족의 기억과 꿈에 대한 애착이 드러난다.","source":"S-93c01cc4d806","supportingSources":["S-01a17ea5bb32"]},"altruism":{"score":4,"text":"아픈 동료를 간호하고 훈련장 정리를 돕고 음식을 나눈다. 상대의 사정을 확인해 도움이 부담이 되지 않게 바꾸는 모습도 있다.","source":"S-073520fdafec","supportingSources":["S-ce2db3299dcf"]},"initiative":{"score":3,"text":"필요한 간호와 대화를 먼저 시작하지만 상대가 원치 않으면 물러난다. 상황을 지휘하기보다 옆에서 필요한 일을 찾아 하는 쪽에 가깝다.","source":"S-ce2db3299dcf","supportingSources":["S-073520fdafec"]},"caution":{"score":4,"text":"상대에게 말과 동행이 필요한지 묻고 자신의 해석에도 여지를 둔다. 이 점수는 주로 대인 관계의 신중함이며 전투 판단 전반의 우수함을 뜻하지 않는다.","source":"S-ce2db3299dcf","supportingSources":["S-d0224128eaef"]},"bonds":{"score":4,"text":"아버지의 동화를 기억하고 동료와 반복해서 위로와 일상을 나눈다. 친밀함을 원하면서도 관계를 유지하기 위해 상대의 거리를 인정한다.","source":"S-01a17ea5bb32","supportingSources":["S-ce2db3299dcf"]}},"relations":[{"name":"아도니스","text":"몸살을 간호하고 고민을 살핀 동료. 말과 동행을 원하지 않을 때는 조용히 돌보거나 물러난다.","source":"S-ce2db3299dcf","characterId":"P-6eeed2b4661f"},{"name":"엘타리온","text":"시간과 실패, 다시 일어날 기회에 관해 이야기한 동료. 자기 생각을 건네며 과제를 풀 수 있다고 격려한다.","source":"S-d0224128eaef","characterId":"P-cf2651679b0b"},{"name":"모나 델핀","text":"사냥에서 남긴 고통과 어른이 되는 일을 이야기하며 음식과 위로를 나눈 동료.","source":"S-93c01cc4d806","characterId":"P-48cca58d02b2"},{"name":"스노우 글로우","text":"개울가에서 마법과 사랑, 가족과 동화의 꿈을 나눈 상대.","source":"S-01a17ea5bb32","characterId":"P-2bd2e06457e6"},{"name":"캐너리 지엘리히","text":"노래에 이끌려 다가가 포옹과 환영을 받은 상대. 아름다움에 압도된 첫 만남이 강하게 묘사된다.","source":"S-8fbdeb37a30a","characterId":"P-ec8583137a09"}],"scenes":[{"source":"S-8fbdeb37a30a","text":"노래를 따라가 캐너리의 품에서 위로받은 첫 만남."},{"source":"S-d0224128eaef","text":"낮잠 뒤 엘타리온에게 시간은 다시 일어날 기회라고 말한 대화."},{"source":"S-073520fdafec","text":"말을 멈추고 아도니스의 열을 식혀주는 간호."},{"source":"S-93c01cc4d806","text":"구운 버섯을 나누며 사냥의 고통과 어른됨을 고민한 저녁."},{"source":"S-ce2db3299dcf","text":"부서진 더미를 정리하고 혼자 있을 시간을 존중한 훈련장."},{"source":"S-01a17ea5bb32","text":"안전한 식사와 동화 속 영웅을 꿈꾸는 개울가의 밤."}],"asOf":"2026-09-12","sources":["S-d0224128eaef","S-01a17ea5bb32","S-073520fdafec","S-ce2db3299dcf","S-93c01cc4d806","S-8fbdeb37a30a"]},"P-dd70a1273f02":{"name":"도리안 바이덴스","updatedAt":"2026-10-01","tagline":"모든 것을 추리하려는 탐정, 자신의 기억과 마음 앞에서는 아직 풀리지 않은 질문을 만난다.","tags":["분석적인","호기심이 강한","마음을 알아가는"],"profileNote":"마법사 존이나 탐정 존 마커스와는 다른 인물이다. 과거의 기억 재현, 영혼길의 계약, 길드에 보고한 사실을 구분했다. 계약과 기억의 공백 사이에 원문이 확정하지 않은 인과관계를 덧붙이지 않았다.","facts":[{"label":"직업과 배경","value":"왕립 마도 대학에서 연구한 이력이 있는 탐정이다. 과거의 냉동 시신 사건을 기억 속에서 다시 추리한다.","source":"S-06a3c7cb11c9"},{"label":"가문과 가족","value":"귀족 바이덴스 가의 일원이며 여동생 베로니카가 있다. 가족에게 연애와 계약 소식을 제대로 전하지 않아 질책을 받는다.","source":"S-6996e4d07e39"},{"label":"어둠의 계약","value":"영혼길에서 검은 마녀를 아직 막지 못했다고 말하며 이름 없는 주인에게 이상을 대가로 어두운 힘을 받겠다고 선언한다.","source":"S-ed35a68b77cb"},{"label":"능력의 변화","value":"토르번에게 의뢰 중 잠시 죽었다 돌아왔으며 이후 마법 대신 흑마법을 쓰게 되었다고 보고한다. 길드의 조사 단계에서는 원인을 확정하지 못한다.","source":"S-2f74a2906936"},{"label":"올리브와의 관계","value":"죽은 정인의 묘를 찾는 올리브와 동행하고 눈물을 흘리는 곁을 지킨다. 이후 함께 운동하며 살아남아 달라는 소원을 말하고 애정을 확인한다.","source":"S-44c769d8352e"},{"label":"현재의 미해결점","value":"베로니카의 약혼과 관련된 기억에서 공백을 느낀다. 달맞이 마을에서도 비슷한 망각을 경험했지만 의미는 아직 알지 못한다.","source":"S-6996e4d07e39"}],"evaluation":[{"title":"익숙한 결론도 다시 질문한다","text":"과거의 사건이 사고로 처리되려 하자 시신의 상태와 탈출 거리 사이의 모순을 짚는다. 이미 해결했던 기억이 반복되자 사건의 정답보다 왜 다시 보고 있는지를 묻는다. 관찰과 추리를 자기 인식에도 적용하는 인물이다.","source":"S-06a3c7cb11c9"},{"title":"신중하게 생각한 선택도 안전하지는 않다","text":"영혼길에서 말을 내뱉기 전에 숙고하지만 끝내 이상을 내어준다. 오래 계산한다는 사실이 언제나 위험을 피한다는 뜻은 아니다. 목적을 이루려는 의지와 미지에 대한 호기심이 자신의 가장 소중한 것을 걸게 만든다.","source":"S-ed35a68b77cb"},{"title":"무심한 말 속에도 남아 있는 배려","text":"올리브에게 가격 부담이 적은 꽃집을 안내하고 꽃의 의미를 설명하며 묘 앞에서 곁을 지킨다. 울음 뒤에는 마실 것을 제안한다. 감정을 길게 대신 말해주지 않아도 상대의 시간과 필요에 맞춰 머무는 행동이 있다.","source":"S-0c47a593aafb"},{"title":"알고 싶다는 마음이 사람에게 향할 때","text":"올리브의 이야기를 궁금해하고 이후에는 함께할 오전 일정을 만들려 한다. 운동 내기의 소원을 생존에 쓰는 장면은 관계가 추리의 흥미를 넘어 지속을 바라는 마음이 되었음을 보여준다.","source":"S-44c769d8352e"},{"title":"유능함과 우선순위의 편향","text":"에스텔의 문양에는 곧 관심을 보이지만 사자회 자료는 상대가 기대하는 만큼 조사하지 않았다. 호기심이 이끄는 집중력과 업무의 우선순위가 항상 일치하지는 않는다. 뒤늦게 자료를 다시 모으려는 판단까지 함께 읽을 필요가 있다.","source":"S-cc7e377a27cb"}],"traits":{"social":{"score":3,"text":"상대에게 예의를 갖추고 필요하면 대화와 안내를 주도한다. 다만 보통은 타인의 사적인 이야기에 큰 흥미가 없다고 스스로 말하며 관심의 대상을 고르는 편이다.","source":"S-0c47a593aafb","supportingSources":["S-cc7e377a27cb"]},"emotion":{"score":3,"text":"차분한 말투 아래에 씁쓸한 기억과 애정, 상실에 대한 두려움이 있다. 올리브에게 살아남아 달라고 말할 때 그 마음이 분명해진다.","source":"S-44c769d8352e","supportingSources":["S-0c47a593aafb"]},"altruism":{"score":3,"text":"동료의 조사를 돕고 상실을 겪는 사람 곁에 머문다. 동시에 정보 공개와 관심의 순서를 자신의 입장과 흥미로 계산하는 면도 있다.","source":"S-cc7e377a27cb","supportingSources":["S-2f74a2906936"]},"initiative":{"score":4,"text":"사건의 통설에 이의를 제기하고 자료를 조사하며 큰 대가가 있는 선택도 직접 내린다. 가까워진 관계에서는 함께할 생활을 제안한다.","source":"S-ed35a68b77cb","supportingSources":["S-44c769d8352e"]},"caution":{"score":4,"text":"증거와 모순을 따지고 확정할 수 없는 원인을 남겨둔다. 다만 호기심과 목표 앞에서 큰 위험을 감수하므로 항상 안전한 판단을 한다는 평가는 아니다.","source":"S-06a3c7cb11c9","supportingSources":["S-ed35a68b77cb"]},"bonds":{"score":4,"text":"올리브의 기억을 존중하고 살아서 함께할 미래를 원한다. 가족에게 소식을 늦게 전하는 모습은 유대의 중요성과 관계를 돌보는 능력이 일치하지만은 않음을 보여준다.","source":"S-44c769d8352e","supportingSources":["S-6996e4d07e39"]}},"relations":[{"name":"올리브","text":"먼저 떠난 정인의 묘에 함께 갔고 이후 애정을 확인한 상대. 함께 운동하며 오래 살아남아 달라고 부탁한다.","source":"S-44c769d8352e","characterId":"P-6ba6a097816f"},{"name":"토르번 팔켄하인","text":"죽음과 부활, 흑마법으로의 변화를 보고받고 함께 원인을 찾기로 한 공대장.","source":"S-2f74a2906936","characterId":"P-7ba611cf90be"},{"name":"에스텔 벨라시타","text":"출생과 연결된 문양을 들고 찾아온 동료. 흑주술 마법진으로 읽고 추가 조사를 약속한다.","source":"S-cc7e377a27cb","characterId":"P-b522cca806d0"}],"scenes":[{"source":"S-06a3c7cb11c9","text":"기억 속의 냉동 시신 사건을 다시 마주한 탐정."},{"source":"S-ed35a68b77cb","text":"무너지는 영혼길에서 이상을 대가로 내놓은 계약."},{"source":"S-2f74a2906936","text":"검게 변한 목걸이와 능력의 변화를 토르번에게 보고한 날."},{"source":"S-0c47a593aafb","text":"올리브와 꽃을 골라 정인의 무덤을 찾은 오후."},{"source":"S-44c769d8352e","text":"운동 내기의 소원으로 살아남아 달라고 부탁한 아침."},{"source":"S-6996e4d07e39","text":"여동생과의 재회 뒤 자신의 기억에서 발견한 빈자리."}],"asOf":"2026-09-24","sources":["S-06a3c7cb11c9","S-6996e4d07e39","S-ed35a68b77cb","S-2f74a2906936","S-44c769d8352e","S-0c47a593aafb","S-cc7e377a27cb"]},"P-22fdf8486544":{"name":"티아멧","updatedAt":"2026-10-01","tagline":"먼저 떠난 전우를 기억하며 곁에 남은 친구와 낚싯대를 드리우던 용병.","tags":["전우를 기억하는","담담한","끝까지 싸우는"],"profileNote":"옛 용병 시절의 회상, 저주 이후의 생활, 8월 9일의 마지막 결투를 시점별로 구분했다. 8월 29일 재등장은 홀연히 나타났다가 사라지는 장면이며, 원문에 없는 부활이나 해주 성공을 확정하지 않았다.","facts":[{"label":"전투와 무기","value":"떠돌이 용병으로 자신을 소개한다. 불타며 되돌아오는 손도끼 와이번 슬레이어를 사용하고 원형 방패와 갑옷을 갖춘다.","source":"S-5a265fecb94a"},{"label":"쟝과의 과거","value":"쟝과 전장에서 서로를 구하고 패전 뒤 함께 도망치며 용병 생활을 이어갔다. 뒤늦은 독백에서는 떠난 쟝에게 말을 걸다 길드로 향한다.","source":"S-36e41161824e"},{"label":"저주와 귀환","value":"마녀의 영역에서 받은 저주로 여성의 모습이 되어 길드로 돌아온다. 동료들의 해주 시도는 그 자리에서 해결에 이르지 못한다.","source":"S-6fa0f3594f37"},{"label":"당시의 목표","value":"알세피나에게 현재 목표는 복수이며 끝나면 다른 목표를 찾을 것이라고 말한다. 그 복수심까지 마녀가 심었을 가능성은 본인의 추측으로 꺼낸다.","source":"S-5a265fecb94a"},{"label":"마지막 결투","value":"스카일라에서 패한 뒤 부서진 몸으로 도끼에 작별을 고한다. 명예와 원한을 내려놓는 인사와 함께 여정의 끝이 기록된다.","source":"S-c68797442290"},{"label":"이후의 재회","value":"8월 말 허그에게 무기 사용을 조언하고 피에르와 구울 묘지의 추억을 나눈다. 작별을 말한 뒤 홀연히 사라지며, 등장 방식의 정체는 확정되지 않는다.","source":"S-57619df3881f"}],"evaluation":[{"title":"전우애는 서로를 끌고 나온 기억이다","text":"쟝과의 과거에는 승리뿐 아니라 패주와 부상, 배고픔과 농담이 있다. 서로의 생존을 여러 번 떠받친 시간이 이후의 그리움에 무게를 준다. 전우를 기억하는 마음은 추상적인 명예보다 함께 버틴 생활에 가깝다.","source":"S-36e41161824e"},{"title":"모습이 바뀌어도 관계는 단순히 돌아오지 않는다","text":"귀환한 티아멧을 동료들은 반기지만 바뀐 몸과 목소리에 어색해한다. 티아멧 역시 혼란과 불편을 보인다. 익숙한 농담과 낚시가 관계를 이어주지만, 그 과정의 당혹감까지 없었던 일로 만들지는 않는다.","source":"S-8145bd3b237c"},{"title":"목표의 끝 다음을 생각하는 사람","text":"복수를 현재의 목표로 두면서도 그 후에는 새로운 것을 찾겠다고 말한다. 동시에 그 마음이 온전히 자기 것인지 잠깐 의심한다. 복수심만으로 닫힌 인물보다 자기 삶의 방향을 확정하지 못한 채 걸어가는 인물로 읽힌다.","source":"S-5a265fecb94a"},{"title":"남은 사람을 미래의 그리움으로 바라보다","text":"낚시하며 먼저 떠난 전우를 떠올리다가 언젠가 그리워질 친구들이 아직 곁에 있다고 말한다. 상실을 잊지는 않되 지금 함께할 저녁으로 돌아오는 태도다. 담담함 안에 관계를 소중히 여기는 마음이 분명히 있다.","source":"S-8145bd3b237c"},{"title":"마지막까지 병기와 나누는 인사","text":"결투의 끝에서 도끼를 자신과 적 사이에 서준 전우처럼 대한다. 패배를 부정하기보다 작별의 말을 완성하는 장면으로 여정을 닫는다. 이후의 짧은 재회도 승전담보다 조언과 안부로 남는다는 점에서 이별의 정조를 이어간다.","source":"S-c68797442290"}],"traits":{"social":{"score":3,"text":"익숙한 친구와 농담하고 처음 만난 사람의 질문에도 응한다. 어려운 말은 다 이해하지 못한 채 대화를 마무리하기도 해, 사교의 폭보다 편안한 동행이 두드러진다.","source":"S-5a265fecb94a","supportingSources":["S-8145bd3b237c"]},"emotion":{"score":3,"text":"저주 앞의 심란함과 전우를 향한 그리움을 드러내지만 주로 짧은 말과 행동으로 표현한다. 담담한 표현이 상실의 깊이가 작다는 뜻은 아니다.","source":"S-6fa0f3594f37","supportingSources":["S-8145bd3b237c"]},"altruism":{"score":4,"text":"전장에서 다친 쟝을 구하고 업어 돌아온다. 뒤의 재회에서도 후배에게 무기를 함부로 던지지 말라고 조언한다. 가까운 동료를 지키는 행동의 근거가 뚜렷하다.","source":"S-36e41161824e","supportingSources":["S-57619df3881f"]},"initiative":{"score":4,"text":"살 길을 찾아 싸우고 길드로 돌아와 저주에 관해 도움을 구한다. 현재의 목표를 자기 입으로 정해 말하며 다음 삶도 생각한다.","source":"S-6fa0f3594f37","supportingSources":["S-5a265fecb94a"]},"caution":{"score":3,"text":"오랜 전장 경험으로 무기 투척의 위험을 설명할 수 있다. 그러나 마지막 결투의 패배만으로 전체 판단을 평가하거나, 모든 위험을 충분히 계산했다고 단정할 근거는 없다.","source":"S-57619df3881f","supportingSources":["S-36e41161824e"]},"bonds":{"score":5,"text":"쟝과의 기억, 숀과의 오랜 동행, 피에르와 공유한 모험이 반복해서 등장한다. 마지막에는 자신의 도끼에도 전우로서 작별을 건넨다.","source":"S-8145bd3b237c","supportingSources":["S-36e41161824e","S-c68797442290"]}},"relations":[{"name":"숀","text":"낚시하며 지난 모험과 전우를 추억한 오랜 친구. 저주 뒤의 어색함 속에서도 함께할 일상을 이어간다.","source":"S-8145bd3b237c","characterId":"P-5c88d36f51cd"},{"name":"핀 머독","text":"길드 귀환을 격하게 반겨준 동료. 달라진 모습과 저주를 알게 되는 자리에 함께한다.","source":"S-6fa0f3594f37","characterId":"P-87b04eb56606"},{"name":"알세피나 마르케브","text":"불타는 무기를 계기로 삶의 목적과 복수에 관해 이야기한 상대.","source":"S-5a265fecb94a","characterId":"P-d51e51401bd1"},{"name":"피에르","text":"마지막 결투 이후의 재회에서 구울 묘지를 함께 다녔던 추억을 나눈 동료.","source":"S-57619df3881f","characterId":"P-1ba0b80ec424"},{"name":"가델랏 허그","text":"바위를 치며 훈련하던 밤에 무기와 무작정 부딪히는 태도에 관한 조언을 받은 후배.","source":"S-57619df3881f","characterId":"P-6a1a99e98a44"}],"scenes":[{"source":"S-36e41161824e","text":"쟝과 서로를 구하며 살아남았던 옛 용병 시절."},{"source":"S-6fa0f3594f37","text":"저주로 달라진 모습으로 길드의 문을 다시 연 날."},{"source":"S-5a265fecb94a","text":"알세피나와 무기와 삶의 목적을 묻고 답한 첫 만남."},{"source":"S-8145bd3b237c","text":"남은 친구들과의 시간을 돌아보는 숀과의 낚시."},{"source":"S-c68797442290","text":"스카일라의 마지막 결투 뒤 도끼에 건넨 작별."},{"source":"S-57619df3881f","text":"허그와 피에르 앞에 잠깐 나타났다가 사라진 늦여름 밤."}],"asOf":"2026-08-29","sources":["S-5a265fecb94a","S-36e41161824e","S-6fa0f3594f37","S-c68797442290","S-57619df3881f","S-8145bd3b237c"]},"P-96ee3cc09ac8":{"name":"코난 발토르","updatedAt":"2026-10-01","tagline":"힘과 노동의 책임을 아는 전사, 낯선 세상 앞에서는 자신의 믿음도 다시 묻는다.","tags":["책임을 중시하는","배우려는","가족을 기억하는"],"profileNote":"입회 이후의 생활과 고향의 회상을 구분했다. 단순한 공용어 말투와 사고의 깊이는 별개로 읽었다. 여동생의 장례와 아들의 등장은 과거 회상이며, 게시 날짜에 새로 발생한 사건으로 소개하지 않았다.","facts":[{"label":"출신과 이름","value":"서쪽 바바루 부족 출신의 전사다. 여동생에게 쓰는 편지에서는 자신을 언덕 위의 우뢰라고 부른다.","source":"S-f93b31b305ed"},{"label":"길드 입회","value":"태양을 향해 여행하다 길드를 찾는다. 스텔라의 설명을 듣고 새 목적을 찾을 동안 머물기를 청하며, 상회 소년을 보좌하는 과정을 거쳐 입회를 인정받는다.","source":"S-de3bf6bbeb63"},{"label":"가족","value":"사슴 뿔 위의 달이라는 넷째 여동생을 잃었다. 고향 회상에는 아들 초원을 누비는 산바람과 장례 뒤 대화를 나누는 모습이 나온다.","source":"S-58ab67597e40"},{"label":"추모의 방식","value":"여동생이 어느 사후세계에 있을지 몰라 같은 편지를 세 통 쓴다. 한 통은 태우고 한 통은 묻으며 한 통은 나중에 직접 전하려 보관한다.","source":"S-f93b31b305ed"},{"label":"노동","value":"성벽 공사로 돈을 벌고 향신료 와인을 마련한다. 그 술을 마신 아카쿠를 공사장에 데려가 노동의 시간과 가치를 체험하게 한다.","source":"S-303e84e4601c"},{"label":"최근의 질문","value":"남부 바다에서 거대한 존재들을 보고 두려웠다고 델타인과 베어에게 털어놓는다. 전사로서의 자신과 이전에 믿었던 세계관을 다시 생각한다.","source":"S-b822937db674"}],"evaluation":[{"title":"말을 배우는 사람도 세계를 해석한다","text":"여동생에게 쓰는 편지에서는 거대한 사회가 법과 규칙으로 움직이는 이유를 자기 부족의 생활과 비교한다. 서툰 공용어만 보면 놓치기 쉬운 관찰과 사유다. 모르는 것을 인정하면서 자신이 아는 언어로 이해를 넓힌다.","source":"S-f93b31b305ed"},{"title":"전통을 지키는 아버지, 전통을 묻는 아들","text":"장례 뒤 아들은 전사가 울어서는 안 된다는 관습에 의문을 제기한다. 코난은 책임의 무게를 말하지만 끝내 붉어진 눈으로 비 속에 남는다. 슬퍼하지 않는 강함보다 슬픔을 드러내기 어려운 전사의 모습을 보여준다.","source":"S-58ab67597e40"},{"title":"답을 모르는 채로도 사랑을 전한다","text":"어느 사후세계가 진짜인지 단정하지 않고 세 가지 방식으로 편지를 보낸다. 새로운 믿음을 접한 혼란을 한쪽을 조롱하는 방식으로 풀지 않는다. 누이에게 닿고 싶은 마음이 불확실함을 감수하는 행동을 만든다.","source":"S-f93b31b305ed"},{"title":"노동의 가치를 가르치지만 자기 기준도 강하다","text":"아카쿠에게 단순 변상 대신 공사 노동을 요구하고, 다른 일을 하고 있다는 항변은 가볍게 넘긴다. 동료에게 시간과 땀의 가치를 알리려는 의도와 자신의 방식으로 상대를 끌고 가는 완고함이 함께 있다. 마지막의 심심했다는 고백은 이 엄격함에 장난기를 더한다.","source":"S-303e84e4601c"},{"title":"두려움을 인정하는 것도 전사의 일이다","text":"자신이 감당할 수 없는 존재를 본 뒤 무서웠다고 말하고 답을 구한다. 대화로 즉시 결론을 내리지 못해도 더 생각해보겠다고 한다. 초기의 확신을 계속 반복하기보다 경험이 바꾼 자신을 인정하는 변화다.","source":"S-b822937db674"}],"traits":{"social":{"score":4,"text":"낯선 인사법을 배우고 모닥불에서 음식을 나누며 동료에게 먼저 질문한다. 직설적인 말과 농담이 상대를 압박할 때도 있다.","source":"S-de3bf6bbeb63","supportingSources":["S-303e84e4601c"]},"emotion":{"score":3,"text":"평소에는 담담하지만 누이의 죽음과 남부의 공포를 깊이 간직한다. 감정을 드러내는 방식은 편지와 제한된 대화에 집중된다.","source":"S-58ab67597e40","supportingSources":["S-b822937db674"]},"altruism":{"score":4,"text":"위축된 소년을 보좌하고 수확 지원과 노동에 참여하며 동료에게 책임을 요구한다. 배려가 때로 강압적인 가르침으로 표현되는 한계도 있다.","source":"S-de3bf6bbeb63","supportingSources":["S-86d788987bde"]},"initiative":{"score":5,"text":"고향의 경계를 넘어 직접 여행하고 일자리를 찾아 일하며 새 목적을 구한다. 궁금한 문제와 두려움도 동료에게 먼저 꺼낸다.","source":"S-de3bf6bbeb63","supportingSources":["S-b822937db674"]},"caution":{"score":4,"text":"새로운 믿음을 확정하지 않고 비교하며 큰 고민은 시간을 두고 생각하려 한다. 노동과 책임의 기준에서는 자신이 옳다고 여기는 방식을 강하게 밀어붙이기도 한다.","source":"S-f93b31b305ed","supportingSources":["S-b822937db674"]},"bonds":{"score":5,"text":"떠난 누이에게 편지를 쓰고 아들에게 책임을 이야기하며 길드의 공동생활을 부족과 비교한다. 가족을 기억하는 일이 여행과 세계 이해에 계속 연결된다.","source":"S-f93b31b305ed","supportingSources":["S-58ab67597e40"]}},"relations":[{"name":"스텔라 스타라이트","text":"코난의 목적과 성향을 확인하고 상회 소년을 보좌하는 일을 맡긴 뒤 입회를 허락한 상대.","source":"S-de3bf6bbeb63","characterId":"P-e6655a038328"},{"name":"라이아흐 아카쿠","text":"자신의 술을 마신 뒤 성벽 공사에 함께하게 된 동료. 노동의 가치에 대한 가르침과 장난이 얽힌 관계다.","source":"S-303e84e4601c","characterId":"P-96ab98d2591c"},{"name":"델타인","text":"남부에서 느낀 두려움과 거대한 존재를 대하는 마음을 물어본 동료.","source":"S-b822937db674","characterId":"P-c93f55c91873"},{"name":"베어","text":"전사로서의 길과 두려움에 대한 고민을 들은 동료. 대화는 즉각적인 해답 없이 남는다.","source":"S-b822937db674","characterId":"P-fd3900116fbc"},{"name":"잭 해리슨","text":"수확 지원 현장에서 빠뜨린 일을 마무리하게 하며 노동과 책임을 요구한 동료.","source":"S-86d788987bde","characterId":"P-58df75b248fb"}],"scenes":[{"source":"S-de3bf6bbeb63","text":"태양을 향하던 여행자가 새 목적을 찾으며 길드에 들어온 날."},{"source":"S-f93b31b305ed","text":"죽은 여동생에게 같은 편지를 세 가지 방식으로 보내는 밤."},{"source":"S-58ab67597e40","text":"여동생의 장례 뒤 아들과 슬픔과 전통을 이야기한 과거."},{"source":"S-303e84e4601c","text":"향신료 와인 한 병에서 시작된 아카쿠의 성벽 공사."},{"source":"S-b822937db674","text":"남부에서 자신도 두려웠다고 털어놓은 모닥불."},{"source":"S-86d788987bde","text":"자팔 마을의 수확을 도우며 노동과 동료 관계를 이야기한 하루."}],"asOf":"2026-09-24","sources":["S-f93b31b305ed","S-de3bf6bbeb63","S-58ab67597e40","S-303e84e4601c","S-b822937db674","S-86d788987bde"]},"P-f09ea4be26fb":{"name":"케닌 클로","updatedAt":"2026-10-01","tagline":"돈과 생존을 큰소리로 외치면서도, 추운 밤에는 동료에게 자신의 방을 내주는 쥐 데미간.","tags":["생활력이 강한","큰소리치는","호의를 숨기는"],"profileNote":"피에르·돈 뻬르난떼와 함께 진행된 프로필은 실제 케닌의 발화만 사용했다. 몸을 떨거나 말을 반복하는 버릇을 새로운 질환으로 진단하지 않았다. 다른 인물이 애완동물로 부르는 농담은 케닌의 종족·지위에 관한 사실로 채택하지 않았다.","facts":[{"label":"종족과 말투","value":"쥐 데미간으로 스스로도 쥐에 가깝게 생각한다. 말을 반복하고 상대를 맨–띵으로 부르며 자신을 강한 쥐라고 강조한다.","source":"S-598d6f68920a"},{"label":"생업","value":"고철을 모으고 분류해 대장장이에게 납품한다. 장난감과 잡다한 물건도 만들어봤지만 수입이 나은 일을 생업으로 고른다.","source":"S-40b1c278526d"},{"label":"어린 시절","value":"어릴 때 가족과 헤어졌고 하수도에서 살던 자신을 노인이 도와주었다고 말한다. 노인은 죽기 전 세상 밖에서 살라고 했고, 이후 일하다 단골의 소개로 길드에 왔다.","source":"S-598d6f68920a"},{"label":"생활 공간","value":"길드에서 델타인과 같은 방을 쓴다. 눈 오는 밤 레네르트에게 방을 빌려주고 자신은 가까운 일터에서 자겠다고 한다.","source":"S-87b9213359c4"},{"label":"모험의 도구","value":"헤제트 의뢰에 자물쇠 도구를 챙겨 잠긴 문을 열려고 시도한다. 새끼 검묘의 우리를 찾아 옮기고 마차에 싣는 일도 맡는다.","source":"S-1552a2738413"},{"label":"위험한 욕심","value":"배블스의 옛 저택에서 돈과 수정에 관심을 보인다. 동료의 제지를 받다가 석상과의 전투에 휘말리고 정신 공격으로 쓰러진다.","source":"S-8964aea23e8c"}],"evaluation":[{"title":"먹고살 수 있는 선택을 하는 손재주","text":"무언가를 만드는 즐거움보다 잘 팔리는 납품 일을 택한다. 일을 안 하면 먹고살 수 없다는 말과 맞물려, 돈을 좋아한다는 성격이 구체적인 노동에 뿌리내린다. 단순한 보물 욕심과 생업을 지탱하는 능력을 함께 봐야 한다.","source":"S-40b1c278526d"},{"title":"친목을 투자라고 부르면서 자리를 내준다","text":"모닥불에 나오는 이유를 미래를 위한 투자라고 설명한다. 그러나 그날 만난 동료에게 자기 잠자리를 양보하는 행동은 당장의 계산만으로 설명되지 않는다. 거친 말과 생색 아래에 실제로 비용을 치르는 호의가 있다.","source":"S-87b9213359c4"},{"title":"허세와 경계가 함께 움직인다","text":"위험을 즐긴다고 큰소리치다가도 동료의 경고에는 겁을 먹고 따른다. 그럼에도 물건의 값어치가 눈에 들어오면 안전을 뒷전으로 미룬다. 겁이 없어서라기보다 두려움을 느끼면서도 욕심과 자존심에 흔들리는 모습이다.","source":"S-8964aea23e8c"},{"title":"무례한 언어로도 잘못된 관계를 짚는다","text":"델타인에게 자신이 무엇을 원하는지 정확히 말하라고 묻고, 자식을 실험한 부모의 말을 그대로 따르지 말라고 한다. 동시에 주변 사람을 깎아내리는 언행은 다른 동료에게 상처가 될 수 있다. 돌봄의 순간이 평소의 무례함까지 정당화하지는 않는다.","source":"S-7f138dad8f7a"},{"title":"그리움에 닫힌 말, 관계에 열려 있는 생활","text":"자신을 돌본 노인의 죽음에는 그리워하면 오래 살지 못한다고 답한다. 그 말만으로 실제 그리움의 유무를 확정할 수는 없다. 지금은 길드의 식사와 모닥불에 자주 끼어드는 생활을 택한다는 사실이 함께 남는다.","source":"S-598d6f68920a"}],"traits":{"social":{"score":4,"text":"모닥불에 자주 나와 말을 걸고 농담과 말다툼에 끼어든다. 친목을 중시하지만 상대를 깎아내리는 호칭 때문에 원만한 사교와는 거리가 있다.","source":"S-87b9213359c4","supportingSources":["S-7f138dad8f7a"]},"emotion":{"score":3,"text":"자존심이 상하면 즉시 소리치고 겁나면 피하며 선물에는 반응한다. 깊은 상실에 대해서는 감정을 길게 풀기보다 생존의 말로 거리를 둔다.","source":"S-598d6f68920a","supportingSources":["S-8964aea23e8c"]},"altruism":{"score":3,"text":"동료에게 방을 내주고 잘못된 부모의 말에 얽매이지 말라고 조언한다. 자신의 이익과 물건의 값어치를 앞세우는 장면도 있어 호의와 자기 이익이 함께 작동한다.","source":"S-87b9213359c4","supportingSources":["S-7f138dad8f7a","S-8964aea23e8c"]},"initiative":{"score":4,"text":"생업을 이어가고 의뢰에 도구를 챙겨 나서며 직접 잠입과 물품 운반을 시도한다. 앞장서는 말만 있는 인물은 아니다.","source":"S-40b1c278526d","supportingSources":["S-1552a2738413"]},"caution":{"score":2,"text":"생활에서는 수입과 생존을 따지지만 모험에서는 값나가는 물건에 이끌려 위험을 과소평가한다. 동료의 제지가 행동을 멈추게 하는 경우가 있다.","source":"S-8964aea23e8c","supportingSources":["S-1552a2738413"]},"bonds":{"score":3,"text":"공동생활과 친목을 유지하고 받은 호의도 받아들이지만, 깊은 그리움을 인정하는 말에는 거리를 둔다. 가족을 잊었다거나 아무에게도 정이 없다고 단정할 근거는 없다.","source":"S-598d6f68920a","supportingSources":["S-87b9213359c4"]}},"relations":[{"name":"델타인","text":"방을 함께 쓰고 말다툼과 음식 나눔을 반복하는 동료. 부모의 뜻보다 자신이 원하는 것을 생각하라고 충고한다.","source":"S-7f138dad8f7a","characterId":"P-c93f55c91873"},{"name":"레네르트","text":"눈 오는 밤 길을 헤매다 만난 동료. 케닌은 자신의 방을 내주고 일터로 향한다.","source":"S-87b9213359c4","characterId":"P-ec13f36acacc"},{"name":"스텔라 스타라이트","text":"어린 시절과 보호자였던 노인의 이야기를 물으며 그리움의 의미를 나눈 상대.","source":"S-598d6f68920a","characterId":"P-e6655a038328"},{"name":"포말하우트","text":"저택에서 위험한 욕심을 제지하고 함께 싸운 동료. 케닌의 거친 말에서도 걱정을 읽어준다.","source":"S-8964aea23e8c","characterId":"P-3ab8153acc27"},{"name":"머챈트 마이아","text":"헤제트 의뢰를 함께하며 동료들 사이의 불필요한 감정싸움을 꾸짖은 상대.","source":"S-1552a2738413","characterId":"P-92738ae601c0"}],"scenes":[{"source":"S-40b1c278526d","text":"고철을 모으고 수입이 나은 일을 택하는 평소의 생업."},{"source":"S-1552a2738413","text":"헤제트 투기장의 불법 거래 조사와 새끼 검묘 운반."},{"source":"S-87b9213359c4","text":"눈 오는 밤 레네르트에게 자신의 방을 빌려준 만남."},{"source":"S-598d6f68920a","text":"먹거리 이야기에서 어린 시절과 보호자의 죽음으로 이어진 모닥불."},{"source":"S-8964aea23e8c","text":"수정을 탐내다 위험한 석상과 맞닥뜨린 저택 조사."},{"source":"S-7f138dad8f7a","text":"델타인과 다투고 치즈를 나누다가 부모와 꿈을 이야기한 날."}],"asOf":"2026-03-22","sources":["S-598d6f68920a","S-40b1c278526d","S-87b9213359c4","S-1552a2738413","S-8964aea23e8c","S-7f138dad8f7a"]},"P-cca78a891e49":{"name":"뮤리엘","updatedAt":"2026-10-01","tagline":"새로운 음식과 인연을 향해 걷던 여행자, 끝내 자신이 품고 갈 목표를 다시 묻는다.","tags":["호쾌한","행동으로 돕는","방향을 찾는"],"profileNote":"초기의 미식 여행 선언과 9월 27일의 독백을 함께 읽었다. 마지막 독백에서 미식을 도피처로 돌아보지만, 이전의 즐거움과 도움까지 모두 거짓이었다고 해석하지 않았다. 복수의 구체적인 과거는 이 근거만으로 보충하지 않았다.","facts":[{"label":"여행과 전투","value":"남부 군도를 떠난 여행자이며 할버드를 사용한다. 새벽 독백에는 인생의 절반가량을 배에서 보냈다는 서술이 나온다.","source":"S-57e510e57b33"},{"label":"미식 기록","value":"먹어보지 못한 음식의 맛과 식감을 양피지에 기록한다. 처음 먹은 트롤 고기에 크게 감탄하며 새로운 장소의 음식과 사람을 만나고 싶다고 말한다.","source":"S-938e31076d9c"},{"label":"구조와 사냥","value":"사슴을 사냥하다 다친 사람을 만나자 먼저 의원에게 데려가 치료비를 낸다. 이후 두 머리 사슴과 싸워 고기와 뿔을 얻고 환자의 생존을 확인한다.","source":"S-f59dd89f268f"},{"label":"삶의 방향","value":"신과 완전함을 논하는 자리에서 각자 신념이나 목표를 나침반 삼아 나아가는 일이 의미 있다고 말한다. 세상에 해를 주지 않는 방향이라는 조건도 붙인다.","source":"S-ccb4085ddc07"},{"label":"마리아의 룸메이트","value":"마리아와 방을 함께 쓰며 하일로를 향한 호감을 직접 듣는다. 보호하려는 마음에 상대를 시험하려 하지만 마리아가 막자 물러난다.","source":"S-fcb770f47e24"},{"label":"최근의 출발","value":"9월 말 홀로 술을 마시며 복수의 기회와 미식이라는 포부를 돌아본다. 무엇을 품고 살지 묻고 이전보다 길어질 여행길에 오른다.","source":"S-57e510e57b33"}],"evaluation":[{"title":"즐거움은 다음 장소로 가는 이유였다","text":"션이 안락함에 머물까 걱정하는 것과 달리, 뮤리엘은 좋은 음식과 인연이 새로운 여행을 재촉한다고 말한다. 머무는 기쁨과 떠나는 의지가 공존한다. 이 초기의 선언을 알 때 훗날 목표를 되묻는 독백의 무게가 커진다.","source":"S-938e31076d9c"},{"title":"기억나지 않는 사람도 먼저 살린다","text":"부상자가 자신을 안다고 해도 뮤리엘은 그를 기억하지 못한다. 그래도 치료에 노잣돈을 쓰고 상태를 다시 확인한다. 도움이 꼭 과거의 인연이나 보상에 의존하지 않는다는 점을 행동으로 보여준다.","source":"S-f59dd89f268f"},{"title":"전투적인 보호가 상대의 선택을 넘을 때","text":"마리아의 연애를 듣고 할버드를 들고 하일로를 시험하려 한다. 걱정의 표현이지만 상대가 원하는 도움과는 다르다. 마리아가 만류하자 그 사람에게도 자기 항해도가 있다고 인정하는 반응까지 함께 있어야 이 장면을 온전히 읽을 수 있다.","source":"S-fcb770f47e24"},{"title":"후회를 행동으로 옮기게 돕다","text":"9월에는 하일로에게 마리아의 부재와 마지막으로 본 방향을 알려준다. 후회만 하다가 중요한 것을 놓치지 말라는 말이 실제로 찾아갈 수 있는 정보와 붙어 있다. 상대를 대신 시험하려던 이전 모습과 다른 개입 방식이 보인다.","source":"S-5131143648a3"},{"title":"자기 나침반이 흐려지는 순간","text":"남에게 각자의 방향을 가지라고 말하던 사람이 마지막에는 자신의 목표를 의심한다. 미식을 도피처로 부르는 것은 그때의 자기 평가이며 여정 전체의 무가치함을 확정하는 결론은 아니다. 답을 얻었다는 선언 없이 다시 길로 나서는 미완의 변화가 남는다.","source":"S-57e510e57b33"}],"traits":{"social":{"score":4,"text":"음식과 술을 함께하며 먼저 말을 건네고 크게 웃는다. 상대의 이름과 마음을 챙기지만 보호하려는 의욕이 부담스러운 간섭으로 이어지기도 한다.","source":"S-938e31076d9c","supportingSources":["S-fcb770f47e24"]},"emotion":{"score":4,"text":"미식과 만남의 기쁨을 크게 표현하고 동료의 연애에 흔들린다. 최근에는 잊지 못한 복수심과 목표에 대한 공허함을 독백으로 드러낸다.","source":"S-57e510e57b33","supportingSources":["S-fcb770f47e24"]},"altruism":{"score":4,"text":"사냥을 미루고 자기 돈으로 부상자를 치료하며 동료가 관계를 바로잡도록 돕는다. 도움을 받는 사람이 원하는 방식을 놓칠 때도 있다.","source":"S-f59dd89f268f","supportingSources":["S-5131143648a3"]},"initiative":{"score":5,"text":"사냥과 구조, 여행을 직접 실행하고 고민하는 동료에게 행동할 계기를 준다. 자신의 목적이 흔들릴 때도 길을 떠나는 선택을 한다.","source":"S-f59dd89f268f","supportingSources":["S-57e510e57b33"]},"caution":{"score":3,"text":"낯선 부상자의 상태를 살피고 필요한 치료를 우선한다. 반면 연애 문제를 흑주술로 의심하는 등 충분한 확인 전에 결론을 내리는 장면도 있다.","source":"S-f59dd89f268f","supportingSources":["S-bdf3f54bc199"]},"bonds":{"score":4,"text":"여행의 즐거움을 함께한 사람과 연결하고 마리아의 부재를 기억하며 하일로를 움직인다. 떠난 누군가를 향한 말도 최근 독백에 남아 있다.","source":"S-5131143648a3","supportingSources":["S-57e510e57b33"]}},"relations":[{"name":"션","text":"트롤 고기와 술을 나누며 안락함과 여행의 의미를 다르게 설명한 동료.","source":"S-938e31076d9c","characterId":"P-3bbc4a823df9"},{"name":"마리아 아나이스 에스더","text":"룸메이트이자 보호하고 싶은 친구. 마리아는 뮤리엘에게 자신의 연애를 직접 말하고 과한 개입을 만류한다.","source":"S-fcb770f47e24","characterId":"P-c9505ea97ebc"},{"name":"하일로 조바","text":"초기에는 마리아의 연인으로서 시험하려 했지만, 이후 마리아를 찾아가도록 정보와 조언을 건넨 상대.","source":"S-5131143648a3","characterId":"P-f6ccefd2c259"},{"name":"숀","text":"하일로가 떠난 뒤 후회와 이별, 바로잡을 기회에 관해 이야기한 동료.","source":"S-5131143648a3","characterId":"P-5c88d36f51cd"},{"name":"존 (마법사)","text":"식탁에서 신과 인간의 인식, 각자의 삶의 방향을 함께 논한 동료.","source":"S-ccb4085ddc07","characterId":"P-79263e0865dd"}],"scenes":[{"source":"S-938e31076d9c","text":"트롤 고기를 기록하며 새로운 여행의 이유를 이야기한 야식."},{"source":"S-f59dd89f268f","text":"사냥보다 부상자 구조를 먼저 택한 숲의 만남."},{"source":"S-ccb4085ddc07","text":"자기 삶의 나침반을 가져야 한다고 말한 식탁."},{"source":"S-fcb770f47e24","text":"마리아의 연애를 듣고 보호와 간섭의 경계에 선 밤."},{"source":"S-5131143648a3","text":"후회하던 하일로에게 아직 찾아갈 수 있다고 알려준 장면."},{"source":"S-57e510e57b33","text":"미식과 복수를 되묻고 긴 여행길에 오른 새벽."}],"asOf":"2026-09-27","sources":["S-57e510e57b33","S-938e31076d9c","S-f59dd89f268f","S-ccb4085ddc07","S-fcb770f47e24","S-5131143648a3","S-bdf3f54bc199"]},"P-d80a97449dfc":{"name":"아르메리아","updatedAt":"2026-10-01","tagline":"상실을 지나온 손으로 꽃을 건네는 엘프, 다정함 속에서도 필요한 경계는 분명히 말한다.","tags":["세심한","장난기 있는","인연을 아끼는"],"profileNote":"자연의 힘과 정령을 만나는 장면을 근거로 기술을 소개했다. 확인되지 않은 공식 직업·나이·가족 설정은 보충하지 않았다. 어린 시절의 약초 사고와 이후의 위로는 별개 시점으로 정리했다.","facts":[{"label":"외모","value":"금발과 하트 모양 눈동자를 가진 엘프다. 카라와의 첫 대화에서는 진녹빛 눈동자와 그 안의 모양이 구체적으로 언급된다.","source":"S-811479ac23d0"},{"label":"어린 시절","value":"아픈 어머니와 단둘이 살았다. 치료할 꽃을 찾아 위험한 산을 올랐으나 약초와 독초를 혼동했고, 차를 마신 어머니가 다시 일어나지 못했다고 고백한다.","source":"S-f22b04e1eb1c"},{"label":"자연의 힘과 무기","value":"션과 무기점을 방문해 식물 정령의 응답을 받고 이실리엔 묘목 목검에 자연의 힘을 흘려넣는다. 마법사에게 위험할 수 있다는 설명을 듣고 주의하겠다고 답한다.","source":"S-cec9c9b1f11a"},{"label":"아이들과의 교류","value":"션과 고아원을 방문해 아이들 눈높이에서 인사하고 공주 역할로 놀이에 참여한다. 아이들이 이길 수 있도록 션의 주의를 끈다.","source":"S-5436b191c2a7"},{"label":"꽃 선물","value":"아이다·루체·마리아·뮤리엘의 방문에 각각 다른 꽃을 걸어둔다. 마리아에게는 좋아한다고 들었던 나팔꽃을 고른다.","source":"S-ecc1291f7eb2"},{"label":"길드와의 약속","value":"마리아와 죽음과 사랑을 이야기하며 죽음이 다시 올 때까지 웃을 일을 많이 만들자고 한다. 길드에 정이 들었으니 마음대로 떠나지 않겠다고 약속한다.","source":"S-c6b6514d34ea"}],"evaluation":[{"title":"괜찮다고 말한 뒤에도 받을 위로는 남는다","text":"어머니의 일을 지난 일이라고 말하지만 동료가 손을 잡아주자 비로소 눈물을 보인다. 자기 나름의 결론을 냈다는 사실과 위로가 필요하다는 사실이 함께 존재한다. 이를 완전히 극복했거나 전혀 극복하지 못했다는 양쪽 단정으로 좁히지 않았다.","source":"S-f22b04e1eb1c"},{"title":"꽃은 받는 사람마다 달라진다","text":"같은 선물을 한꺼번에 돌리지 않고 꽃의 종류와 받을 사람을 연결한다. 특히 마리아가 좋아하는 꽃을 기억했다는 점이 구체적이다. 세심함은 막연한 다정함보다 상대가 했던 말을 다음 행동에 반영하는 능력으로 드러난다.","source":"S-ecc1291f7eb2"},{"title":"사랑의 추상어를 일상의 기억으로 풀다","text":"꽃 때문에 아침과 길가의 풀까지 아름다워지는 경험으로 사랑을 설명한다. 도움을 받은 빚보다 함께 웃는 순간을 늘리자고 말한다. 죽음을 이미 이야기한 두 사람이 평범한 빨래를 하며 삶을 이어가는 장면이기도 하다.","source":"S-c6b6514d34ea"},{"title":"다정함은 모든 행동을 받아주는 태도가 아니다","text":"린네를 처음에는 부드럽게 맞지만 폭력과 예절의 문제를 듣고 질문을 이어간다. 대답에서 성찰이 부족하다고 판단하자 입회를 거절하는 쪽에 선다. 환대와 공동체를 위한 경계가 같은 인물 안에서 함께 작동한다.","source":"S-ad7c985fb1ec"},{"title":"아름다운 인상 밖의 장난기","text":"고아원 놀이에서는 아이들과 편을 짜고 션의 주의를 흐트러뜨린다. 상대가 가진 힘과 지위를 잠시 뒤집는 유쾌함이 있다. 늘 위로만 하는 조용한 조력자로 정리하면 일상의 활기와 능청스러움을 놓친다.","source":"S-5436b191c2a7"}],"traits":{"social":{"score":4,"text":"처음 만난 카라에게 먼저 인사하고 낯선 길드 방문자를 맞으며 아이들과 쉽게 어울린다. 상대에 따라 말투와 대화 방식을 조절한다.","source":"S-811479ac23d0","supportingSources":["S-5436b191c2a7"]},"emotion":{"score":4,"text":"과거의 상실을 차분히 말하다 위로를 받고 눈물을 보인다. 꽃과 기억, 사랑에 의미를 두며 타인의 감정에도 주의를 기울인다.","source":"S-f22b04e1eb1c","supportingSources":["S-c6b6514d34ea"]},"altruism":{"score":4,"text":"친구의 일을 도우려 하고 꽃을 고르며 아이들과 시간을 보낸다. 상대가 도움을 사양하면 억지로 대신하지 않고 곁에서 대화를 이어간다.","source":"S-c6b6514d34ea","supportingSources":["S-ecc1291f7eb2"]},"initiative":{"score":4,"text":"꽃을 준비해 직접 돌리고 정령과의 교감을 시도하며 필요하면 불편한 질문도 꺼낸다. 부드러운 인상이 상황을 수동적으로 따르기만 한다는 뜻은 아니다.","source":"S-ecc1291f7eb2","supportingSources":["S-ad7c985fb1ec"]},"caution":{"score":4,"text":"무기의 위험 설명을 듣고 주의를 약속하며 방문자의 말에서 무엇이 달라질 수 있는지 차근차근 묻는다. 어린 시절의 절박한 실수를 현재의 모든 판단으로 일반화하지 않았다.","source":"S-cec9c9b1f11a","supportingSources":["S-ad7c985fb1ec"]},"bonds":{"score":5,"text":"상대의 취향을 기억해 선물하고 길드와 서로 정들었다고 말한다. 먼저 떠나지 않겠다는 약속과 살아 있는 동안 웃을 일을 늘리려는 태도가 관계를 중심에 둔다.","source":"S-c6b6514d34ea","supportingSources":["S-ecc1291f7eb2"]}},"relations":[{"name":"마리아 아나이스 에스더","text":"과거의 상실을 나누고 죽음과 사랑을 다시 이야기한 친구. 좋아하는 나팔꽃을 기억해 선물한다.","source":"S-c6b6514d34ea","characterId":"P-c9505ea97ebc"},{"name":"션","text":"무기점과 고아원을 함께 찾은 동료. 도움을 받기도 하고 아이들과 함께 장난을 걸기도 한다.","source":"S-5436b191c2a7","characterId":"P-3bbc4a823df9"},{"name":"에레모시스","text":"어머니의 일을 고백했을 때 손을 잡고 위로해준 동료. 아르메리아는 그제야 눈물을 드러낸다.","source":"S-f22b04e1eb1c","characterId":"P-d6e0d1eb8b63"},{"name":"카라","text":"새벽에 처음 만나 이름과 외모, 정령에 관한 이야기를 나눈 동료. 카라의 정령 아엘리카와도 교감한다.","source":"S-811479ac23d0","characterId":"P-fa593b8f3d37"},{"name":"린네","text":"처음에는 환대했으나 행동을 되돌아보는 대화 끝에 입회를 거절한 상대.","source":"S-ad7c985fb1ec","characterId":"P-083603ba0af4"}],"scenes":[{"source":"S-f22b04e1eb1c","text":"어머니에게 쓰려던 약초의 실수를 동료들에게 고백한 밤."},{"source":"S-811479ac23d0","text":"카라와 번개의 정령 아엘리카를 만난 새벽."},{"source":"S-cec9c9b1f11a","text":"션과 찾아간 무기점에서 식물 정령과 목검을 만난 날."},{"source":"S-5436b191c2a7","text":"아이들과 함께 갈고리손 기사 션을 이기려 한 고아원 놀이."},{"source":"S-c6b6514d34ea","text":"빨래하며 죽음과 사랑, 길드에 남을 마음을 나눈 대화."},{"source":"S-ecc1291f7eb2","text":"친구들의 방문에 서로 다른 꽃을 걸어둔 늦여름."}],"asOf":"2026-08-30","sources":["S-811479ac23d0","S-f22b04e1eb1c","S-cec9c9b1f11a","S-5436b191c2a7","S-ecc1291f7eb2","S-c6b6514d34ea","S-ad7c985fb1ec"]},"P-fae6af716ea2":{"name":"라이티티아","updatedAt":"2026-10-01","tagline":"잊힌 얼굴을 찾아온 정령술사, 남을 지키고 싶은 마음과 버림받지 않으려는 마음 사이에서 흔들린다.","tags":["헌신적인","그리움을 품은","자신에게 엄격한"],"profileNote":"무표정한 첫인상, 관계가 가까워진 시기, 9월 26일 이별과 망각의 서술을 구분했다. 망각은 작품의 서술로 소개하며 질환명이나 정확한 마법 원인을 붙이지 않았다. 다음 날 일상에 나왔다는 사실을 회복이나 시안과의 재결합으로 해석하지 않았다.","facts":[{"label":"정령술","value":"바람의 정령들과 교류하며 의뢰에서 도움을 받는다. 돌아온 뒤 정령들에게 감사하고 더 도움이 되는 사람이 되도록 노력하겠다고 말한다.","source":"S-fa196e5aa629"},{"label":"고향과 방문 목적","value":"북부에서 살았으며 사라진 스승을 찾으러 왔다. 별을 세는 습관과 잠 못 드는 밤의 청소에 스승을 기다리던 기억이 겹친다.","source":"S-b2aa45cfe634"},{"label":"스승과 이름","value":"스승은 자신을 길러준 사람이며 같은 정령술사는 아니라고 설명한다. 9월 말에는 스승의 얼굴과 목소리를 떠올리지 못한다. 원래 이름도 잊었고 지금은 라이티티아라고 말한다.","source":"S-35b73bd42c5a"},{"label":"피난민에 관한 고민","value":"첩자 조사에서 만난 피난민을 돌아보며 살아 있는 사람을 구하는 데 우선순위를 꼭 나눠야 하는지 괴로워한다.","source":"S-5c8d568a52c7"},{"label":"동료 돌봄","value":"딜라일라가 구한 포션을 다친 모나에게 서둘러 전달한다. 자신도 통증이 남아 있으나 도움이 되고 싶어 움직이고, 모나 역시 쉬라고 당부한다.","source":"S-e37297ab4b6c"},{"label":"관계와 기억의 변화","value":"가까워졌던 시안과 9월 26일 이별의 말을 겪고, 그를 잊는다는 서술과 함께 쓰러진다. 원문은 이를 어린 시절부터 반복된 망각과 연결한다.","source":"S-8c99316e2a4d"}],"evaluation":[{"title":"차가워 보이는 표정과 작은 시도","text":"에스페에게 정중히 인사한 뒤 손가락으로 입꼬리를 올려 웃음을 만들어 보인다. 감정이 없어서라기보다 관계에 들어갈 표현을 애써 찾는 장면으로 읽힌다. 지나친 칭찬을 삼가 달라고 말하는 등 자기 경계도 조심스럽게 전한다.","source":"S-742eaad2351f"},{"title":"작게라도 나아가야 한다는 생활","text":"잠이 오지 않는 밤 청소를 하며 자신이 아무것도 못할까 걱정한다. 눈물을 흘리면서도 빗자루를 움직이는 모습에는 성실함과 불안이 함께 있다. 계속 행동한다는 사실만으로 마음도 괜찮다고 볼 수는 없다.","source":"S-b2aa45cfe634"},{"title":"지키고 싶은 대상의 범위가 넓다","text":"동료뿐 아니라 의뢰에서 만난 피난민의 생존도 자신의 문제로 받아들인다. 사람마다 우선순위를 나눠야 하는 현실을 쉽게 납득하지 못한다. 넓은 연민은 장점이지만 자신이 해결할 수 없는 문제까지 짊어질 때 고통이 커진다.","source":"S-5c8d568a52c7"},{"title":"도움을 주면서 자신의 필요를 줄여 말한다","text":"모나의 통증에는 세심하게 반응하면서 자신의 상처는 괜찮다고 한다. 이미 마신 포션까지 아쉬워하며 충분히 돕지 못했다는 생각을 반복한다. 헌신과 자기 돌봄이 균형을 이루는 단계라고 보기는 어렵다.","source":"S-e37297ab4b6c"},{"title":"붙잡고 싶은 관계가 기억의 단절로 이어질 때","text":"이별 뒤 독백은 함께하며 감정을 느낀 기쁨과 더는 견디기 힘든 고통을 번갈아 보여준다. 결국 잊는다는 서술은 갈등이 대화로 해결된 결말이 아니다. 다음 날의 일상에서도 기억의 빈자리가 남아 있어, 밝은 표정만으로 회복을 선언하지 않았다.","source":"S-8c99316e2a4d"}],"traits":{"social":{"score":3,"text":"정중히 인사하고 대화에 합류하며 가까운 사람에게 보고 싶었다고 말한다. 표현이 서툴고 평가받는 자리에서는 긴장하지만 교류를 포기하지 않는다.","source":"S-742eaad2351f","supportingSources":["S-5c8d568a52c7"]},"emotion":{"score":5,"text":"스승에 대한 그리움과 동료의 상처, 관계의 단절이 내면에 큰 영향을 준다. 무표정이나 억지웃음은 감정이 약하다는 근거가 되지 않는다.","source":"S-b2aa45cfe634","supportingSources":["S-8c99316e2a4d"]},"altruism":{"score":4,"text":"피난민을 살피고 다친 동료에게 필요한 물건을 직접 전달한다. 남을 돕기 위해 자기 몸의 필요를 작게 취급하는 한계도 함께 나타난다.","source":"S-e37297ab4b6c","supportingSources":["S-5c8d568a52c7"]},"initiative":{"score":4,"text":"스승을 찾아 이동하고 신입의 일을 챙기며 의뢰 뒤 자신의 부족함을 돌아본다. 위축된 말과 달리 스스로 시작한 행동이 반복된다.","source":"S-b2aa45cfe634","supportingSources":["S-fa196e5aa629"]},"caution":{"score":3,"text":"조용히 청소하고 상대를 살피며 자신의 행동을 거듭 점검한다. 그러나 지나친 자책과 불안이 쌓이면 감당 가능한 한계를 지키기 어려워진다.","source":"S-e37297ab4b6c","supportingSources":["S-8c99316e2a4d"]},"bonds":{"score":5,"text":"스승을 찾는 목적과 정령에 대한 감사, 동료와 시안에게 느끼는 애착이 행동의 중심이다. 곁에 있어달라는 바람이 강하며 이별을 크게 받아들인다.","source":"S-742eaad2351f","supportingSources":["S-fa196e5aa629","S-8c99316e2a4d"]}},"relations":[{"name":"시안 던 브링어","text":"서로 보고 싶었다고 말하며 가까워졌으나 귀환 후 갈등과 이별을 겪은 상대. 최신 기록에서 재결합을 확인하지는 못했다.","source":"S-8c99316e2a4d","characterId":"P-77d4478f4f51"},{"name":"에스페","text":"첫 무렵 별빛 아래 스승을 찾는 사정을 듣고 함께 별을 센 동료.","source":"S-742eaad2351f","characterId":"P-492692198c9a"},{"name":"모나 델핀","text":"다친 팔을 위해 포션을 전달한 동료. 모나는 라이티티아가 이미 기여했음을 말하고 함께 쉬기를 권한다.","source":"S-e37297ab4b6c","characterId":"P-48cca58d02b2"},{"name":"엘레나 레지아노","text":"토팔의 경험과 이후의 일상을 함께 나눈 동료. 9월 말 모닥불에서 고향과 미래에 관한 생각을 나눈다.","source":"S-35b73bd42c5a","characterId":"P-89d5e8c6329e"},{"name":"피에르","text":"고향과 스승을 찾는 이유를 듣고 질문한 동료. 대화 중 기억의 공백이 다시 드러난다.","source":"S-35b73bd42c5a","characterId":"P-1ba0b80ec424"}],"scenes":[{"source":"S-742eaad2351f","text":"에스페와 별을 세며 찾고 있는 스승의 이야기를 꺼낸 밤."},{"source":"S-b2aa45cfe634","text":"눈 없는 창밖을 보며 조용히 청소를 이어간 새벽."},{"source":"S-fa196e5aa629","text":"의뢰를 돌아보고 정령들에게 고마움을 전한 뒤뜰."},{"source":"S-5c8d568a52c7","text":"시안과 재회해 피난민을 지키는 마음을 털어놓은 대화."},{"source":"S-e37297ab4b6c","text":"자신도 다친 채 모나에게 포션을 전하러 간 날."},{"source":"S-8c99316e2a4d","text":"이별 뒤 기억을 놓는다는 서술과 함께 쓰러진 냇가."},{"source":"S-35b73bd42c5a","text":"다음 날의 모닥불에서 스승의 얼굴을 떠올리려 한 대화."}],"asOf":"2026-09-27","sources":["S-fa196e5aa629","S-b2aa45cfe634","S-35b73bd42c5a","S-5c8d568a52c7","S-e37297ab4b6c","S-8c99316e2a4d","S-742eaad2351f"]}}};
